// GENERATED by `yuu-dev bundle` from bundle.manifest - do not edit by hand.
// Edit the individual static/*.js files (or the manifest order) and re-run
// `yuu-dev bundle`. tests/unit/test_bundle_drift.py guards this file.

//# sourceURL=clipexport.js
(function () {
// Feature-map - Clip export (the Export modal flow + per-format export-file actions).
//   API: routes/clips/ (export.py, delete.py clip-exports, crud.py export-files, edit.py suggest-framing) · Tests: tests/ui/test_ui_clips.py, tests/ui/test_ui_exporteditor.py
// Renders and drives the Export dialog and the per-format rows in the clip
// detail's Export card. The rows themselves are built by _exportFormatsHtml in
// clips.js (it renders inside the detail pane); the actions they dispatch live here.

// ── per-format export row actions (Export presets - Plan 07) ───────────────
function _downloadFile(filename) {
  const a = document.createElement('a');
  a.href = `/media/exports/${encodeURIComponent(filename)}`;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
}

// Download the clip's exported video plus any SRT caption sidecars on disk.
async function _downloadClipExport(clipId) {
  let files = [];
  try {
    const data = await fetch(`/api/clips/${clipId}/export-files`).then(r => r.json());
    files = (data && data.files) || [];
  } catch (_) { /* fall back to the single known media file below */ }
  if (!files.length && AppState.activeMediaFilename) files = [AppState.activeMediaFilename];
  if (!files.length) { showToast('No exported files found', 'warning'); return; }
  // Stagger so the browser doesn't collapse rapid sequential downloads into one.
  files.forEach((fn, i) => setTimeout(() => _downloadFile(fn), i * 200));
  if (files.length > 1) showToast(`Downloading ${files.length} files (video + captions)`, 'info');
}

async function _revealClipExport(clipId) {
  let files = [];
  try {
    const data = await fetch(`/api/clips/${clipId}/export-files`).then(r => r.json());
    files = (data && data.files) || [];
  } catch (_) { /* fall back to the single known media file below */ }
  if (!files.length && AppState.activeMediaFilename) files = [AppState.activeMediaFilename];
  if (!files.length || !AppState.exportDir) { showToast('No exported files found', 'warning'); return; }
  const sep = AppState.exportDir.includes('\\') ? '\\' : '/';
  revealInFolder(`${AppState.exportDir}${sep}${files[0]}`);
}

async function _copyClipExportPaths(clipId) {
  let files = [];
  try {
    const data = await fetch(`/api/clips/${clipId}/export-files`).then(r => r.json());
    files = (data && data.files) || [];
  } catch (_) { /* fall back to the single known media file below */ }
  if (!files.length && AppState.activeMediaFilename) files = [AppState.activeMediaFilename];
  if (!files.length) { showToast('No exported files found', 'warning'); return; }
  const sep = AppState.exportDir && AppState.exportDir.includes('\\') ? '\\' : '/';
  const paths = files.map(fn => AppState.exportDir ? `${AppState.exportDir}${sep}${fn}` : fn);
  copyText(paths.join('\n'), files.length > 1 ? 'File paths' : 'File path');
}

function _handleExportFormatAction(action, data) {
  // Read from the row's own dataset rather than AppState.activeClipId - the
  // Export card can be rendered for a clip before it's the globally "active"
  // one (e.g. in tests, or a future non-selection preview), so each row must
  // be self-contained.
  const clipId = parseInt(data.clipId, 10);
  if (!clipId) return;
  if (action === 'download') _downloadFile(data.filename);
  else if (action === 'reveal') {
    if (!AppState.exportDir) { showToast('Exports folder unknown', 'warning'); return; }
    const sep = AppState.exportDir.includes('\\') ? '\\' : '/';
    revealInFolder(`${AppState.exportDir}${sep}${data.filename}`);
  } else if (action === 'copy-path') {
    const path = AppState.exportDir ? `${AppState.exportDir}${AppState.exportDir.includes('\\') ? '\\' : '/'}${data.filename}` : data.filename;
    copyText(path, 'File path');
  } else if (action === 'regenerate') {
    _confirmRegenerateExportFormat(clipId, data);
  } else if (action === 'delete') {
    _confirmDeleteExportFormat(clipId, data.exportId);
  }
}

function _confirmRegenerateExportFormat(clipId, data) {
  const label = exportPresetLabel(data.presetName);
  showConfirm(
    'Regenerate this format?',
    `Re-export "${escHtml(label)}" with the same settings, overwriting the existing file.`,
    'Regenerate',
    () => _regenerateExportFormat(clipId, data),
  );
}

function _regenerateExportFormat(clipId, data) {
  const params = new URLSearchParams();
  if (data.presetName && data.presetName !== 'default') params.set('preset', data.presetName);
  if (data.burnSubs) params.set('burn_subs', 'true');
  else if (data.embedSubs) params.set('embed_subs', 'true');
  if (data.titleCard) params.set('title_card', 'true');
  const qs = params.toString() ? `?${params}` : '';

  openLog();
  streamSSE(
    `/api/clips/${clipId}/export${qs}`,
    async () => {
      const clip = await fetch(`/api/clips/${clipId}`).then(r => r.json());
      AppState.activeClipData = clip;
      if (!PanelNav.isOpen()) renderDetail(clip);
      await _reloadClipList(AppState.activeVideoId);
      showToast('Format regenerated');
      SoundFx.play('export');
    },
    [{label: 'Export', patterns: ['Exporting', 'OK Saved']}],
    'Exporting',
  );
}

function _confirmDeleteExportFormat(clipId, exportId) {
  showConfirm(
    'Delete this format?',
    'This exported file will be removed from disk. The clip\'s other formats (if any) are kept.',
    'Delete Format',
    () => _deleteExportFormat(clipId, exportId),
    true,
  );
}

async function _deleteExportFormat(clipId, exportId) {
  await _releasePlayerBeforeDelete();
  const res = await fetch(`/api/clip-exports/${exportId}`, {method: 'DELETE'});
  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    showToast(`Failed to delete format: ${formatApiError(err)}`, 'error');
    selectClip(clipId);
    return;
  }
  const clip = await fetch(`/api/clips/${clipId}`).then(r => r.json());
  AppState.activeClipData = clip;
  if (!clip.has_export) renderPlayer(null, null, clipId);
  renderDetail(clip);
  await _reloadClipList(AppState.activeVideoId);
  showToast('Format deleted');
}

// ── export dialog (modal) flow ───────────────────────────────────────────────
let _exportClipId = null;
let _exportOpener = null;
let _exportDiarReady  = false;
let _exportDiarReason = '';
let _exportCropX = 0.5;  // vertical-framing crop position for the active export

// A 9:16 column spanning the full height of a 16:9 preview is (9/16)^2 = 31.64%
// of its width; the box's left edge therefore travels across the remaining 68.36%.
const _VERT_BOX_W_PCT = 31.64;
const _VERT_BOX_TRAVEL_PCT = 100 - _VERT_BOX_W_PCT;

// One always-visible line answering "will this be quick or slow, and why" -
// the terms match the Getting Started guide and glossary (Quick/Precise export).
function _exportModeSummary(hardsub, titleCard, retranscribe) {
  const reencodeReasons = [];
  if (hardsub)   reencodeReasons.push('burned-in captions');
  if (titleCard) reencodeReasons.push('the title card');
  const retxNote = retranscribe ? ' Retranscribing runs first and adds time.' : '';
  if (reencodeReasons.length) {
    return {
      precise: true,
      text: `Precise export - re-encodes for ${reencodeReasons.join(' and ')} (slower).${retxNote}`,
    };
  }
  return {
    precise: false,
    text: `Quick export - copies the video without re-encoding (seconds). Cuts may land up to ~1 s off the exact mark.${retxNote}`,
  };
}

function _renderExportModeSummary(el, hardsub, titleCard, retranscribe) {
  const summary = _exportModeSummary(hardsub, titleCard, retranscribe);
  el.textContent = summary.text;
  el.style.color = summary.precise ? 'var(--warning)' : 'var(--muted)';
}

function _updateExportModeSummary() {
  _renderExportModeSummary(
    document.getElementById('export-mode-summary'),
    document.getElementById('export-captions').value === 'hardsub',
    document.getElementById('export-title-card').checked,
    document.getElementById('export-retranscribe').checked,
  );
}

function _onExportCaptionsChange() {
  _updateExportModeSummary();
}

// Preset exports always re-encode and don't support the soft-subtitle (embed)
// track or a container override - the preset dictates both. Reflect that in
// the rest of the modal so a creator never hits the server-side 400 for the
// unsupported combination.
function _onExportPresetChange(presetName) {
  const containerSel = document.getElementById('export-container');
  const captionsSel  = document.getElementById('export-captions');
  const softsubOpt   = captionsSel.querySelector('option[value="softsub"]');
  const usingPreset  = !!presetName;

  containerSel.disabled = usingPreset;
  softsubOpt.disabled = usingPreset;
  if (usingPreset && captionsSel.value === 'softsub') captionsSel.value = 'none';
  document.getElementById('export-framing').style.display =
    exportPresetIsVertical(presetName) ? '' : 'none';
  _updateExportTightCapWarning(presetName);
  _updateExportModeSummary();
}

// A size-capped preset spreads target_size_mb across the whole clip, so a long
// selection leaves too little video bitrate and comes out blocky. Below this
// total budget the result looks rough; a 4-min clip under Discord's 10 MB cap
// lands here, a short clip or a generous/CRF preset does not. Coarse mirror of
// export/presets.py's size math - the real encode still uses the server formula.
const _TIGHT_CAP_TOTAL_KBPS = 900;

function _exportTightCapWarning(presetName, clip) {
  const capMb = exportPresetTargetSizeMb(presetName);
  if (!capMb || !clip || clip.start_ms == null || clip.end_ms == null) return '';
  const durationS = (clip.end_ms - clip.start_ms) / 1000;
  if (durationS <= 0) return '';
  if ((capMb * 8192) / durationS >= _TIGHT_CAP_TOTAL_KBPS) return '';
  const minutes = Math.max(1, Math.round(durationS / 60));
  const noun = clip.kind === 'scene' ? 'scene' : 'clip';
  return `This ${minutes}-minute ${noun} squeezed under a ${capMb} MB cap will look rough (blocky). Consider a larger preset or a shorter selection.`;
}

// Advisory only - never blocks export; just surfaces when the cap is too tight.
function _updateExportTightCapWarning(presetName) {
  const el = document.getElementById('export-tightcap-warning');
  if (!el) return;
  const message = _exportTightCapWarning(presetName, AppState.activeClipData);
  el.textContent = message;
  el.style.display = message ? '' : 'none';
}

// Position the 9:16 crop box for the active export and keep the slider + buttons in sync.
function _setExportFraming(fraction) {
  _exportCropX = Math.max(0, Math.min(1, fraction));
  const slider = document.getElementById('export-framing-slider');
  if (slider && parseFloat(slider.value) !== _exportCropX) slider.value = _exportCropX;
  const box = document.getElementById('export-framing-box');
  if (box) {
    box.style.width = `${_VERT_BOX_W_PCT}%`;
    box.style.left  = `${_exportCropX * _VERT_BOX_TRAVEL_PCT}%`;
  }
  document.querySelectorAll('#export-framing [data-frame-pos]').forEach(btn => {
    btn.classList.toggle('active', parseFloat(btn.dataset.framePos) === _exportCropX);
  });
}

// Ask the server to suggest a crop position from faces in the clip (MediaPipe).
// Fills the slider on success; the creator still confirms by exporting. Absent
// package (503) points at the Settings install; no face found leaves the manual
// position untouched.
async function _autoFrameExport() {
  const btn  = document.getElementById('export-autoframe-btn');
  const note = document.getElementById('export-autoframe-note');
  btn.disabled = true;
  note.textContent = 'Finding faces…';
  try {
    const res = await fetch(`/api/clips/${_exportClipId}/suggest-framing`, {method: 'POST'});
    if (res.status === 503) {
      note.innerHTML = 'Needs MediaPipe - <a href="#" onclick="closeExportModal();openSettings();return false">install it in Settings</a>.';
      return;
    }
    if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))) || `HTTP ${res.status}`);
    const {crop_x} = await res.json();
    if (crop_x == null) {
      note.textContent = 'No face found - set the crop manually.';
      return;
    }
    _setExportFraming(crop_x);
    note.textContent = 'Framed on faces.';
  } catch (err) {
    note.textContent = `Auto-frame failed: ${err.message}`;
  } finally {
    btn.disabled = false;
  }
}

// Speaker labels only apply to a retranscribe pass and need the diarization
// backend set up (SpeechBrain installed), so the checkbox is enabled only when
// readiness holds.
function _onExportRetranscribeChange(checked) {
  document.getElementById('export-retranscribe-model').disabled = !checked;
  const row  = document.getElementById('export-speaker-row');
  const box  = document.getElementById('export-speaker-labels');
  const note = document.getElementById('export-speaker-note');
  row.style.opacity = checked ? '1' : '.5';
  box.disabled = !checked || !_exportDiarReady;
  // Only surface the prerequisite note when retranscribe is on; when it's off the
  // row is dimmed for that reason and a token/install note would be ambiguous.
  if (checked && !_exportDiarReady) {
    note.innerHTML = _diarizationNoteHtml(_exportDiarReason, 'closeExportModal();openSettings()');
  } else {
    note.textContent = '';
  }
  _updateExportModeSummary();
}

async function _loadExportSpeakerDefault() {
  const box = document.getElementById('export-speaker-labels');
  const readiness = await _diarizationReadiness();
  _exportDiarReady  = readiness.ready;
  _exportDiarReason = readiness.reason;
  box.checked = readiness.ready;  // on by default when fully set up
  _onExportRetranscribeChange(document.getElementById('export-retranscribe').checked);
}

// Prefill the export dialog's Caption style group from the global defaults so the
// per-export override starts where Settings -> Export left it. Failures are
// non-fatal - the fields just stay empty (renderer default).
async function _prefillExportCaptionStyle() {
  try {
    const cfg = await fetch('/api/config').then(r => r.json());
    document.getElementById('export-caption-font').value = cfg.caption_font_name || '';
    document.getElementById('export-caption-size').value = cfg.caption_font_size ? cfg.caption_font_size : '';
    document.getElementById('export-caption-position').value = cfg.caption_position || 'bottom';
    document.getElementById('export-caption-word-highlight').checked = !!cfg.caption_word_highlight;
    document.getElementById('export-caption-chunk-size').value = cfg.caption_word_chunk_size || 4;
    _onExportWordHighlightChange(!!cfg.caption_word_highlight);
  } catch { /* leave fields at their defaults */ }
}

// The words-on-screen count only applies when word-highlight is on; grey it out
// otherwise so the control's dependency is discoverable.
function _onExportWordHighlightChange(enabled) {
  document.getElementById('export-caption-chunk-size').disabled = !enabled;
}

async function exportClip(id) {
  _exportOpener = document.activeElement;
  _exportClipId = id;
  document.getElementById('export-captions').value = 'softsub';
  document.getElementById('export-container').value = '';
  document.getElementById('export-trim-start').value = _fmtOffset(AppState.activeClipData?.start_offset);
  document.getElementById('export-trim-end').value   = _fmtOffset(AppState.activeClipData?.end_offset);
  const retx = document.getElementById('export-retranscribe');
  retx.checked = false;
  document.getElementById('export-retranscribe-model').disabled = true;
  document.getElementById('export-title-card').checked = false;
  await _prefillExportCaptionStyle();
  await populateExportPresetSelect('');
  const savedCropX = AppState.activeClipData?.crop_x;
  _setExportFraming(savedCropX == null ? 0.5 : savedCropX);
  document.getElementById('export-autoframe-note').textContent = '';
  _onExportPresetChange('');
  _updateExportModeSummary();
  _loadExportSpeakerDefault();
  document.getElementById('export-settings-modal').classList.add('visible');
  setTimeout(() => document.getElementById('export-captions')?.focus(), 50);
}

function closeExportModal() {
  document.getElementById('export-settings-modal').classList.remove('visible');
  const opener = _exportOpener;
  _exportOpener = null;
  if (opener?.focus) opener.focus();
}

async function confirmExport() {
  const id        = _exportClipId;
  const captions  = document.getElementById('export-captions').value;
  const burnSubs  = captions === 'hardsub';
  const embedSubs = captions === 'softsub';
  const container = document.getElementById('export-container').value;
  const preset    = document.getElementById('export-preset').value;
  const trimStart = _parseTimingOffset(document.getElementById('export-trim-start').value);
  const trimEnd   = _parseTimingOffset(document.getElementById('export-trim-end').value);
  const retx      = document.getElementById('export-retranscribe').checked;
  const retxModel = document.getElementById('export-retranscribe-model').value;
  const speakerLabels = document.getElementById('export-speaker-labels').checked;
  const titleCard = document.getElementById('export-title-card').checked;
  closeExportModal();

  if (!isNaN(trimStart) && !isNaN(trimEnd)) {
    const timingRes = await fetch(`/api/clips/${id}/timing`, {
      method: 'PATCH', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({start_offset: trimStart, end_offset: trimEnd}),
    }).catch(err => { showToast(`Failed to save trim: ${err.message}`, 'error'); return null; });
    if (!timingRes || !timingRes.ok) {
      if (timingRes) showToast('Failed to save trim points', 'error');
      return;
    }
  }

  if (exportPresetIsVertical(preset)) {
    const framingRes = await fetch(`/api/clips/${id}/framing`, {
      method: 'PATCH', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({crop_x: _exportCropX}),
    }).catch(err => { showToast(`Failed to save framing: ${err.message}`, 'error'); return null; });
    if (!framingRes || !framingRes.ok) {
      if (framingRes) showToast('Failed to save vertical framing', 'error');
      return;
    }
  }

  const params = new URLSearchParams();
  if (burnSubs)   params.set('burn_subs', 'true');
  if (embedSubs)  params.set('embed_subs', 'true');
  if (preset)     params.set('preset', preset);
  else if (container) params.set('container', container);  // a preset dictates its own container
  if (retx)       {
    params.set('retranscribe', 'true');
    params.set('retranscribe_model', retxModel);
    params.set('speaker_labels', speakerLabels ? 'true' : 'false');
  }
  if (titleCard)  params.set('title_card', 'true');
  if (burnSubs) {
    // Caption style only affects burned-in captions; send the dialog's values so
    // the export is pinned to what the creator saw, independent of later config edits.
    params.set('caption_font', document.getElementById('export-caption-font').value.trim());
    const sizeRaw = document.getElementById('export-caption-size').value.trim();
    params.set('caption_size', sizeRaw === '' ? '0' : sizeRaw);
    params.set('caption_position', document.getElementById('export-caption-position').value);
    const wordHighlight = document.getElementById('export-caption-word-highlight').checked;
    params.set('word_highlight', wordHighlight ? 'true' : 'false');
    if (wordHighlight) {
      const chunkRaw = document.getElementById('export-caption-chunk-size').value.trim();
      if (chunkRaw !== '') params.set('word_chunk_size', chunkRaw);
    }
  }
  const qs = params.toString() ? `?${params}` : '';

  const steps = [{label: 'Export', patterns: ['Exporting', 'OK Saved']}];
  if (retx) steps.unshift({label: 'Transcribe', patterns: ['Retranscribing', 'OK']});

  openLog();
  streamSSE(
    `/api/clips/${id}/export${qs}`,
    async () => {
      const [clip, media] = await Promise.all([
        fetch(`/api/clips/${id}`).then(r => r.json()),
        fetch(`/api/clips/${id}/media_url`).then(r => r.json()),
      ]);
      AppState.activeClipData = clip;
      AppState.activeMediaFilename = media.filename;
      // A takeover panel (e.g. Split Editor) may have opened while the export
      // was streaming - don't clobber it by re-rendering the covered detail pane.
      if (!PanelNav.isOpen()) {
        const captionsUrl = media.has_captions ? `/api/clips/${id}/captions.vtt` : null;
        renderPlayer(media.url, captionsUrl, id);
        renderDetail(clip);
      }
      await _reloadClipList(AppState.activeVideoId);
      loadVideos();
      showToast('Clip exported successfully');
      SoundFx.play('export');
    },
    steps,
    retx ? 'Retranscribing' : 'Exporting',
  );
}

// Public API - symbols referenced cross-module, by an inline handler, or by a
// test. Internal helpers above stay private to this module's closure.
Object.assign(window, {
  exportClip, closeExportModal, confirmExport,
  _onExportCaptionsChange, _onExportRetranscribeChange, _onExportPresetChange,
  _onExportWordHighlightChange, _exportTightCapWarning, _updateExportTightCapWarning,
  _setExportFraming, _autoFrameExport, _updateExportModeSummary, _renderExportModeSummary,
  _handleExportFormatAction, _downloadClipExport, _revealClipExport, _copyClipExportPaths,
});
})();

//# sourceURL=analyze.js
// Feature-map - Analyze (start + SSE progress) + Import from URL, both in the New Recording panel.
//   API: routes/analyze.py, routes/imports.py · Tests: tests/ui/test_ui_analyze.py
// ── shared live panel state ───────────────────────────────────────────────────
// _probedInfo and _panelDirty are read cross-file by videos.js (analyze-button
// enablement, dirty-guard on view switch). Kept at top level, outside the IIFE
// below, so the global lexical binding stays live - an Object.assign export
// would snapshot the value and readers would see stale data.
let _probedInfo    = null;
let _panelDirty    = false;

(function () {
// ── new recording panel ───────────────────────────────────────────────────────
let _probeTimer    = null;
// When set, the New Recording panel is re-analyzing an existing recording rather
// than ingesting a new file: the source picker / pre-split are hidden, settings
// default to the recording's original run, and Start submits {video_id, force}.
let _reanalyzeTarget = null;

function _isNewRecordingPanelOpen() {
  return document.getElementById('new-recording-panel').style.display !== 'none';
}

function _revealRecordingPanel() {
  document.getElementById('player-area').style.display = 'none';
  document.getElementById('player-resize-handle').style.display = 'none';
  document.getElementById('detail').style.display = 'none';
  document.getElementById('new-recording-panel').style.display = '';
  document.getElementById('btn-analyze').setAttribute('aria-pressed', 'true');
}

// Toggle the panel chrome between "new recording" and "re-analyze" modes.
function _applyPanelMode() {
  const reanalyze = !!_reanalyzeTarget;
  const src = document.getElementById('recording-source-field');
  if (src) src.style.display = reanalyze ? 'none' : '';
  const title = document.getElementById('new-recording-title');
  if (title) title.textContent = reanalyze ? 'Re-analyze recording' : 'New Recording';
  const warn = document.getElementById('reanalyze-warning');
  if (warn) {
    warn.style.display = reanalyze ? '' : 'none';
    warn.innerHTML = reanalyze ? _reanalyzeWarningHtml(_reanalyzeTarget) : '';
  }
  const btn = document.getElementById('btn-start-analyze');
  if (btn) {
    btn.textContent = reanalyze ? 'Re-analyze' : 'Start Analysis';
    btn.classList.toggle('danger', reanalyze);
    btn.classList.toggle('primary', !reanalyze);
  }
}

function _reanalyzeWarningHtml(target) {
  const exportedNote = target.exported > 0
    ? ` Files you already exported stay on disk, but the ${plural(target.exported, 'exported clip')} will be regenerated.`
    : '';
  return `<span aria-hidden="true">&#9888;</span>
    <span>Re-analyzing <strong>${escHtml(target.filename)}</strong> re-runs the full pipeline and replaces all
    current clips, including your approvals and any edited descriptions.${exportedNote}
    Adjust the settings below, then choose Re-analyze.</span>`;
}

async function openNewRecordingPanel() {
  if (_isNewRecordingPanelOpen()) return;
  if (document.getElementById('btn-analyze').disabled) return;
  if (document.getElementById('settings-panel').classList.contains('visible')) {
    closeSettings(openNewRecordingPanel);
    return;
  }
  _reanalyzeTarget = null;
  _revealRecordingPanel();

  document.getElementById('analyze-path').value = '';
  document.getElementById('estimate-area').innerHTML = '';
  const stEl = document.getElementById('subtitle-source-field');
  if (stEl) stEl.style.display = 'none';
  _probedInfo   = null;
  _panelDirty   = false;
  _updateStartIngestButton();
  hidePreSplitSection();
  hideImportUrlSection();
  _applyPanelMode();
  await _loadAnalysisDefaults();
  await _loadProfileDropdown();
  await _loadIngestContextPicker();
  await _loadDiarizationDefault();
  document.getElementById('analyze-path').focus();
}

// Re-analyze an already-analyzed recording: reuse the New Recording panel with
// its settings defaulted to the original run (editable), the source picker and
// pre-split hidden, and the existing file re-probed so the time estimate and
// captions picker still work.
async function openReanalyzePanel(video) {
  if (document.getElementById('btn-analyze').disabled) return;
  if (document.getElementById('settings-panel').classList.contains('visible')) {
    closeSettings(() => openReanalyzePanel(video));
    return;
  }
  _reanalyzeTarget = {
    id: video.id, filename: video.filename, path: video.path, exported: video.exported || 0,
    subtitleSource: video.analyze_run?.settings?.subtitle_source || null,
  };
  _revealRecordingPanel();

  document.getElementById('estimate-area').innerHTML = '';
  const stEl = document.getElementById('subtitle-source-field');
  if (stEl) stEl.style.display = 'none';
  _probedInfo   = null;
  _panelDirty   = false;
  _updateStartIngestButton();
  hidePreSplitSection();
  hideImportUrlSection();
  _applyPanelMode();
  await _loadProfileDropdown();
  await _loadIngestContextPicker();
  await _loadDiarizationDefault();
  await _applyReanalyzeSettings(video);
  document.getElementById('analyze-path').value = video.path;
  runProbe(video.path);
}

// Default the panel's controls to how this recording was originally analyzed.
async function _applyReanalyzeSettings(video) {
  const params = await _reanalyzeParams(video);
  _setSelectIfPresent('analyze-model',       params.model);
  _setSelectIfPresent('analyze-scene-mode',  params.scene_mode);
  _setSelectIfPresent('analyze-energy-mode', params.energy_mode);
  _setSelectIfPresent('analyze-profile',     params.profile || '__default__');
  const diarBox = document.getElementById('analyze-diarize');
  if (diarBox && !diarBox.disabled && typeof params.diarize === 'boolean') {
    diarBox.checked = params.diarize;
  }
  _preselectContexts(params.context_names);
}

function _preselectContexts(ids) {
  const wanted = new Set(ids || []);
  document.querySelectorAll('.ctx-pill').forEach(pill => {
    pill.classList.toggle('selected', wanted.has(pill.dataset.ctxId));
  });
  const note = document.getElementById('ctx-none-selected-note');
  if (note) note.style.display = document.querySelectorAll('.ctx-pill.selected').length ? 'none' : '';
}

// Pre-fill the panel's model/scene/energy selects from the Settings-managed
// config defaults; the panel's values remain a per-run override.
async function _loadAnalysisDefaults() {
  try {
    const cfg = await fetch('/api/config').then(r => r.json());
    _setSelectIfPresent('analyze-model',       cfg.whisper_model);
    _setSelectIfPresent('analyze-scene-mode',  cfg.scene_detection_mode);
    _setSelectIfPresent('analyze-energy-mode', cfg.energy_mode);
  } catch { /* config unreachable - keep the static defaults */ }
}

function _setSelectIfPresent(id, value) {
  const sel = document.getElementById(id);
  if (!sel || !value) return;
  if (Array.from(sel.options).some(o => o.value === value)) sel.value = value;
}

function closeNewRecordingPanel() {
  if (!_isNewRecordingPanelOpen()) return;
  if (_panelDirty) {
    showConfirm(
      'Discard new recording?',
      'You have unsaved configuration. Close anyway?',
      'Discard',
      _doCloseNewRecordingPanel,
      true,
    );
    return;
  }
  _doCloseNewRecordingPanel();
}

function _doCloseNewRecordingPanel() {
  clearTimeout(_probeTimer);
  document.getElementById('new-recording-panel').style.display = 'none';
  document.getElementById('player-area').style.display = '';
  document.getElementById('player-resize-handle').style.display = '';
  document.getElementById('detail').style.display = '';
  document.getElementById('btn-analyze').setAttribute('aria-pressed', 'false');
  _panelDirty = false;
  _reanalyzeTarget = null;
}

async function _loadIngestContextPicker() {
  AppState.contexts = await fetch('/api/contexts').then(r => r.json()).catch(() => []);
  const list = document.getElementById('analyze-context-list');
  if (!AppState.contexts.length) {
    list.innerHTML = `<div style="font-size:12px;color:var(--muted)">
      No World Contexts set up - clip descriptions will be generic.
      <button class="btn ghost" style="font-size:11px;padding:0 6px;color:var(--accent);display:inline-flex"
              onclick="closeNewRecordingPanel();openContextManager()">Add one →</button>
    </div>`;
    return;
  }
  list.innerHTML =
    `<div class="ctx-picker" id="ctx-picker">` +
    AppState.contexts.map(c =>
      `<button type="button" class="ctx-pill" data-ctx-id="${escHtml(c.context_id)}"
               onclick="_toggleCtxPill(this)">${escHtml(c.display_name || c.context_id)}</button>`
    ).join('') +
    `</div>` +
    `<div id="ctx-none-selected-note" style="font-size:11px;color:var(--muted);margin-top:6px">No context selected - descriptions will be generic</div>`;
}

function _toggleCtxPill(btn) {
  btn.classList.toggle('selected');
  const note = document.getElementById('ctx-none-selected-note');
  if (note) note.style.display = document.querySelectorAll('.ctx-pill.selected').length ? 'none' : '';
}

function _selectedContextIds() {
  return Array.from(document.querySelectorAll('.ctx-pill.selected')).map(b => b.dataset.ctxId);
}

async function _loadDiarizationDefault() {
  const box  = document.getElementById('analyze-diarize');
  const note = document.getElementById('analyze-diarize-note');
  if (!box || !note) return;
  try {
    const readiness = await _diarizationReadiness();
    if (!readiness.ready) {
      box.checked = false;
      box.disabled = true;
      note.innerHTML = _diarizationNoteHtml(
        readiness.reason, 'closeNewRecordingPanel();openSettings()');
    } else {
      const enabledByDefault = readiness.backend !== 'null';
      box.disabled = false;
      box.checked = enabledByDefault;
      note.textContent = enabledByDefault ? 'On by default (from Settings)' : 'Off by default (from Settings)';
    }
  } catch { /* leave the checkbox at its default state on error */ }
}

async function _loadProfileDropdown() {
  const sel = document.getElementById('analyze-profile');
  try {
    AppState.analyzeProfiles = await fetch('/api/profiles').then(r => r.json());
    sel.innerHTML = AppState.analyzeProfiles.map(p =>
      `<option value="${escHtml(p.name)}">${escHtml(p.display_name)}</option>`
    ).join('');
  } catch { AppState.analyzeProfiles = []; }
}

function scheduleProbe() {
  clearTimeout(_probeTimer);
  const path = document.getElementById('analyze-path').value.trim();
  if (!path) {
    document.getElementById('estimate-area').innerHTML = '';
    _probedInfo = null;
    _updateStartIngestButton();
    return;
  }
  _panelDirty = true;
  document.getElementById('estimate-area').innerHTML = '<div class="probing-spinner">Inspecting file...</div>';
  _probeTimer = setTimeout(() => runProbe(path), 700);
}

async function runProbe(path) {
  try {
    const res = await fetch('/api/probe', {
      method: 'POST', headers: {'Content-Type': 'application/json'},
      body:   JSON.stringify({path}),
    });
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      _probedInfo = null;
      _updateStartIngestButton();
      document.getElementById('estimate-area').innerHTML =
        `<div style="color:var(--red);font-size:12px">${escHtml(formatApiError(err))}</div>`;
      return;
    }
    _probedInfo = await res.json();
    _updateStartIngestButton();
    _renderSubtitleSourcePicker(_probedInfo);
    if (_reanalyzeTarget) _selectSubtitleSource(_reanalyzeTarget.subtitleSource);
    runEstimate();
    if (!_reanalyzeTarget) initPreSplitDuration(_probedInfo.duration_s);
  } catch (err) {
    _probedInfo = null;
    _updateStartIngestButton();
    hidePreSplitSection();
    document.getElementById('estimate-area').innerHTML =
      `<div style="color:var(--red);font-size:12px">Could not inspect file: ${escHtml(String(err.message || err))}</div>`;
  }
}

function _renderSubtitleSourcePicker(info) {
  let el = document.getElementById('subtitle-source-field');
  if (!el) {
    const anchor = document.getElementById('estimate-area');
    el = document.createElement('div');
    el.id = 'subtitle-source-field';
    el.className = 'field';
    anchor.before(el);
  }
  el.style.display = '';
  const opts = [`<option value="">Transcribe with Whisper (default)</option>`];
  if (info.srt_sidecar) {
    const name = info.srt_sidecar.split(/[\\/]/).pop();
    opts.push(`<option value="${escHtml(info.srt_sidecar)}">Use SRT sidecar: ${escHtml(name)}</option>`);
  }
  for (const s of info.subtitle_streams || []) {
    const label = s.title || s.language || `stream ${s.index}`;
    opts.push(`<option value="stream:${s.index}">Use embedded captions: ${escHtml(label)}</option>`);
  }
  opts.push(`<option value="__pick-srt__">Choose SRT file&#8230;</option>`);
  el.innerHTML = `<label for="analyze-subtitle-source">Captions</label>
    <select id="analyze-subtitle-source" onchange="_onSubtitleSourceChange(this)">${opts.join('')}</select>`;
}

// Add (or update) the "External SRT: name" option for an arbitrary picked/recorded
// SRT path, inserted just before the "Choose SRT file…" entry.
function _addExternalSrtOption(sel, srtPath) {
  let ext = document.getElementById('subtitle-external-option');
  if (!ext) {
    ext = document.createElement('option');
    ext.id = 'subtitle-external-option';
    sel.insertBefore(ext, sel.querySelector('option[value="__pick-srt__"]'));
  }
  ext.value = srtPath;
  ext.textContent = `External SRT: ${srtPath.split(/[\\/]/).pop()}`;
}

// Default the captions picker to a previously-used source (re-analyze). A path or
// stream already listed is simply selected; an arbitrary external SRT path gets an
// injected option first. An embedded stream absent from this file is left at default.
function _selectSubtitleSource(srtSource) {
  const sel = document.getElementById('analyze-subtitle-source');
  if (!sel || !srtSource) return;
  const known = Array.from(sel.options).some(o => o.value === srtSource);
  if (!known) {
    if (srtSource.startsWith('stream:')) return;
    _addExternalSrtOption(sel, srtSource);
  }
  sel.value = srtSource;
  sel.dataset.prev = srtSource;
}

// "Choose SRT file…" opens the native picker; a successful pick becomes a
// selectable "External SRT: name" option, cancel restores the previous choice.
async function _onSubtitleSourceChange(sel) {
  if (sel.value !== '__pick-srt__') {
    sel.dataset.prev = sel.value;
    runEstimate();
    return;
  }
  const prev = sel.dataset.prev || '';
  try {
    const data = await fetch('/api/pick-file?kind=captions').then(r => r.json());
    if (data.path) {
      _addExternalSrtOption(sel, data.path);
      sel.value = data.path;
      sel.dataset.prev = data.path;
    } else {
      sel.value = prev;
    }
  } catch {
    sel.value = prev;
  }
  runEstimate();
}

function _selectedSubtitleSource() {
  const sel = document.getElementById('analyze-subtitle-source');
  if (!sel || !sel.value || sel.value === '__pick-srt__') return null;
  return sel.value;
}

async function runEstimate() {
  if (!_probedInfo) return;
  const profileName = document.getElementById('analyze-profile').value;
  const profile     = AppState.analyzeProfiles.find(p => p.name === profileName);
  const transcribeTracks = profile
    ? profile.assignments.filter(a => a.do_transcribe).length
    : undefined;
  const extractTracks = profile
    ? profile.assignments.filter(a => a.do_score || a.do_transcribe).length
    : _probedInfo.audio_tracks;
  const usingExternalCaptions = !!_selectedSubtitleSource();
  try {
    const res = await fetch('/api/estimate', {
      method: 'POST', headers: {'Content-Type': 'application/json'},
      body:   JSON.stringify({
        duration_s:        _probedInfo.duration_s,
        model:             document.getElementById('analyze-model').value,
        audio_tracks:      extractTracks,
        transcribe_tracks: usingExternalCaptions ? 0 : transcribeTracks,
        has_gpu:           true,
        scene_mode:        document.getElementById('analyze-scene-mode').value,
        energy_mode:       document.getElementById('analyze-energy-mode').value,
        diarize:           !!document.getElementById('analyze-diarize')?.checked,
      }),
    });
    if (!res.ok) return;
    renderEstimate(_probedInfo, await res.json());
  } catch { /* estimate is non-critical */ }
}

const _warnThresholdMin = 30;

// Shared by the New Recording panel's own probe estimate (renderEstimate) and
// the Import from URL inspect card (renderImportUrlEstimate) - both call
// /api/estimate and show the same per-step breakdown, just under a different
// header (local file probe info vs. downloaded-video metadata).
function _estimateBodyHTML(data) {
  AppState.lastEstimateSteps = data.steps;
  const warnS = _warnThresholdMin * 60;
  const tClass = s => s >= warnS ? 't-warn' : s >= warnS / 3 ? 't-medium' : 't-fast';

  const rows = data.steps.map(s => {
    const isWarn = s.seconds >= warnS;
    return `
      <div class="estimate-row${isWarn ? ' warn' : ''}">
        <span class="warn-icon">${isWarn ? '&#9888;' : ''}</span>
        <span class="estimate-step">${s.name}</span>
        <span class="estimate-note">${s.note}</span>
        <span class="estimate-time ${tClass(s.seconds)}">${s.hms}</span>
      </div>`;
  }).join('');

  const totalWarn  = data.total_seconds >= warnS;
  const totalBadge = totalWarn ? `<span class="total-warn-badge">&#9888; Long job</span>` : '';
  const pctLine    = data.pct_of_video != null
    ? `<div class="estimate-pct">&#8776; ${data.pct_of_video.toFixed(1)}% of recording duration</div>`
    : '';
  const sourceLine = `<div class="estimate-source">${
    data.source === 'measured' ? 'Based on your last runs on this model/device' : 'Rough estimate - no matching past runs yet'
  }</div>`;
  const longRunWarning = data.long_run_warning ? `
    <div class="long-run-warning">
      <span aria-hidden="true">&#9888;</span>
      <span>This is a long analysis (over ${data.warn_hours}h estimated). Consider splitting the
      recording into smaller segments before analyzing (see Pre-split below), or analyzing fewer
      recordings at once. You can also pause between videos, or let auto-pause hold it if your
      GPU runs hot (Settings &rarr; Hardware).</span>
    </div>` : '';

  return `
      ${rows}
      <div class="estimate-total">
        <span>Total estimated</span>
        <span style="display:flex;align-items:center;gap:8px">
          ${totalBadge}
          <span class="${tClass(data.total_seconds)}">${data.total_hms}</span>
        </span>
      </div>
      ${pctLine}
      ${sourceLine}
      ${longRunWarning}`;
}

function renderEstimate(info, data) {
  document.getElementById('estimate-area').innerHTML = `
    <div class="estimate-box">
      <div class="probe-info">
        ${escHtml(info.filename)} &middot; ${info.duration_hms} &middot;
        ${info.width}&#x2715;${info.height} @ ${info.fps.toFixed(0)}fps &middot;
        ${plural(info.audio_tracks, 'audio track')}
      </div>
      ${_estimateBodyHTML(data)}
    </div>`;
}

// Before starting, warn if the speech model is still downloading - analysis will
// pause at the transcription step until it finishes (it waits on the same HF
// download rather than starting a second one). Never silently block or duplicate.
async function startAnalyze() {
  const path = document.getElementById('analyze-path').value.trim();
  if (!path) return;
  let status = null;
  try {
    status = await fetch('/api/llm/download-status').then(r => r.json());
  } catch { /* can't tell - don't block the user */ }
  if (status && status.whisper_downloading) {
    const pct = window.getWhisperDownloadPct ? getWhisperDownloadPct() : null;
    const pctText = (typeof pct === 'number' && pct >= 0) ? ` (${pct}%)` : '';
    showConfirm(
      'Speech model still downloading',
      `The speech-to-text model is still downloading${pctText}. Analysis will pause at the ` +
        `transcription step until it finishes. Start anyway, or wait for the download to complete?`,
      'Start anyway',
      _doStartAnalyze,
      false,
      'Wait',
    );
    return;
  }
  _doStartAnalyze();
}

async function _doStartAnalyze() {
  const path       = document.getElementById('analyze-path').value.trim();
  const model      = document.getElementById('analyze-model').value;
  const profileVal = document.getElementById('analyze-profile').value;
  const profile    = (!profileVal || profileVal === '__default__') ? null : profileVal;
  if (!path) return;

  const energyMode    = document.getElementById('analyze-energy-mode').value;
  const sceneMode     = document.getElementById('analyze-scene-mode').value;
  const diarizeEl     = document.getElementById('analyze-diarize');
  const diarize       = diarizeEl && !diarizeEl.disabled ? diarizeEl.checked : null;
  const contextNames  = _selectedContextIds();
  const subtitleSource = _selectedSubtitleSource();

  const preSplitToggle = document.getElementById('pre-split-toggle');
  if (preSplitToggle && preSplitToggle.checked && _splitPoints.length > 0 && _splitDurationS > 0) {
    const pts      = [0, ..._splitPoints, _splitDurationS];
    const segments = pts.slice(0, -1)
      .map((start, i) => ({ start_s: start, end_s: pts[i + 1], ignored: _splitIgnored.has(i) }))
      .filter(s => !s.ignored);
    _panelDirty = false;
    _doCloseNewRecordingPanel();
    openLog();
    _analyzeSegmentsSequentially(
      path, model, profile, energyMode, sceneMode, contextNames, subtitleSource, diarize, segments, 0,
    );
    return;
  }

  const target = _reanalyzeTarget;
  const btn = document.getElementById('btn-start-analyze');
  btn.disabled = true;
  btn.textContent = target ? 'Starting re-analysis…' : 'Starting…';

  const payload = {
    path, model, profile, energy_mode: energyMode, scene_mode: sceneMode,
    diarize, context_names: contextNames, subtitle_source: subtitleSource,
  };
  if (target) { payload.video_id = target.id; payload.force = true; }

  const startRes = await fetch('/api/analyze/start', {
    method:  'POST',
    headers: {'Content-Type': 'application/json'},
    body:    JSON.stringify(payload),
  });

  if (!startRes.ok) {
    const err = await startRes.json().catch(() => ({}));
    showToast(formatApiError(err) || `Failed to start ${target ? 're-analysis' : 'analysis'}`, 'error');
    btn.disabled = false;
    btn.textContent = target ? 'Re-analyze' : 'Start Analysis';
    return;
  }

  const filename = target ? target.filename : path.split(/[\\/]/).pop();
  AppState.analyzeFilename = filename;
  _panelDirty = false;
  _doCloseNewRecordingPanel();
  loadVideos();  // surface the recording in the sidebar immediately (placeholder until its row exists)
  openLog();
  appendLog(`${target ? 'Re-analyzing' : 'Analyzing'}: ${filename}`);
  _streamAnalyzeEvents(filename);
}

// Attach the header progress bar + in-detail panel to the analyze SSE stream.
// Shared by a fresh start and by reattachAnalysis() after a page refresh - the
// stream replays everything so far, so both paths render the same live UI.
function _streamAnalyzeEvents(filename) {
  streamSSE(
    '/api/analyze/events',
    async () => {
      await loadVideos();
      const v = AppState.videos.find(x => x.filename === filename);
      AppState.analyzeFilename = null;
      _rerenderActiveVideoDetail();
      _showAnalysisToast(v);
      _surfaceAnalyzeWarnings(v);
      if (v) _warmPreviewProxy(v.id);
      SoundFx.play('analysis');
    },
    INGEST_STEPS,
    `Analyzing ${filename}`,
    true,
    null,
    true,
  );
}

// On page load, reconnect to an analysis that was already running server-side
// (detected via /api/status). The subprocess kept going through the refresh; we
// rebuild the sidebar row, header progress bar, and in-detail progress panel by
// replaying the job's buffered output.
async function reattachAnalysis(filename, paused = false) {
  if (!filename || AppState.analyzeFilename === filename) return;
  AppState.analyzeFilename = filename;
  openLog();
  appendLog(`Reconnected to analysis in progress: ${filename}`);
  await loadVideos();
  _rerenderActiveVideoDetail();
  _streamAnalyzeEvents(filename);
  if (paused) _setPausedUIFromStatus(true);
}

function _rerenderActiveVideoDetail() {
  if (AppState.activeVideoId == null) return;
  const active = AppState.videos.find(x => x.id === AppState.activeVideoId);
  if (active) renderVideoDetail(active, null);
}

async function _analyzeSegmentsSequentially(
  path, model, profile, energyMode, sceneMode, contextNames, subtitleSource, diarize, segments, index,
) {
  if (index >= segments.length) {
    loadVideos().then(() =>
      showToast(`Analysis complete - ${plural(segments.length, 'segment')}`)
    );
    SoundFx.play('analysis');
    return;
  }
  await _waitWhileAnalyzePaused();
  const seg = segments[index];
  appendLog(`Analyzing segment ${index + 1}/${segments.length}: ${_fmtSplitTime(seg.start_s)}–${_fmtSplitTime(seg.end_s)}`);
  fetch('/api/analyze/start', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({
      path,
      model,
      profile,
      energy_mode:      energyMode,
      scene_mode:       sceneMode,
      diarize,
      context_names:    contextNames,
      subtitle_source:  subtitleSource,
      segment_start_s:  seg.start_s,
      segment_end_s:    seg.end_s,
    }),
  }).then(res => {
    if (!res.ok) {
      res.json().catch(() => ({})).then(err =>
        showToast(formatApiError(err) || `Failed to start segment ${index + 1}`, 'error')
      );
      return;
    }
    streamSSE(
      '/api/analyze/events',
      () => _analyzeSegmentsSequentially(
        path, model, profile, energyMode, sceneMode, contextNames, subtitleSource, diarize, segments, index + 1,
      ),
      INGEST_STEPS,
      `Segment ${index + 1}/${segments.length}`,
      false,
      null,
      true,
    );
  }).catch(err => showToast(netErrMsg(err), 'error'));
}

function _showAnalysisToast(video) {
  const count = video ? video.clip_count : 0;
  const canJump = video && AppState.activeVideoId !== video.id;
  showToast(`Analysis complete - ${plural(count, 'clip')} found`, 'success', {
    durationMs: 8000,
    ...(canJump ? {action: {label: 'Review', onClick: () => selectVideo(video.id)}} : {}),
  });
}

// Warm the 720p preview proxy in the background after analysis finishes. The
// proxy build used to run inline in the analyze subprocess and blocked "Analysis
// complete" while the whole recording re-encoded; now completion is instant and
// this drains the existing encode SSE quietly (no job pill). Non-fatal - if it's
// skipped or the page closes, the proxy still builds lazily on first preview.
async function _warmPreviewProxy(videoId) {
  try {
    const status = await fetch(`/api/videos/${videoId}/proxy-status`).then(r => r.ok ? r.json() : null);
    if (!status || status.available || status.generating) return;
    const response = await fetch(`/api/videos/${videoId}/proxy/generate`);
    if (!response.ok || !response.body) return;
    const reader = response.body.getReader();
    while (true) { const {done} = await reader.read(); if (done) break; }
  } catch (_) {
    // Preview is a convenience; a failed warm must never surface as an error.
  }
}

// A run can finish "successfully" while a signal was skipped (most often the LLM,
// leaving clips with a basic description). Those reasons are recorded in the run
// metadata; surface them as dismissible warnings so they aren't lost in the log.
async function _surfaceAnalyzeWarnings(video) {
  if (!video) return;
  try {
    const detail = await fetch(`/api/videos/${video.id}`).then(r => r.json());
    for (const warning of (detail?.analyze_run?.warnings || [])) {
      showToast(warning, 'warning', {durationMs: 14000});
    }
  } catch (_) {
    // A missing warning must never break the completion flow.
  }
}

// ── native file picker ────────────────────────────────────────────────────────
async function pickFile() {
  const btn = document.getElementById('btn-browse-recording');
  const orig = btn.textContent;
  btn.textContent = '…';
  btn.disabled = true;
  try {
    const data = await fetch('/api/pick-file').then(r => r.json());
    if (data.path) {
      document.getElementById('analyze-path').value = data.path;
      scheduleProbe();
    }
  } finally {
    btn.textContent = orig;
    btn.disabled = false;
  }
}

// ── Import from URL (Twitch VOD / YouTube) ────────────────────────────────────
let _importUrlInfo = null;
let _importUrlUrl  = null;

function showImportUrlSection() {
  document.getElementById('recording-source-field').style.display = 'none';
  document.getElementById('import-url-field').style.display = '';
  document.getElementById('analyze-path').value = '';
  scheduleProbe();
  document.getElementById('import-url-input').focus();
}

function hideImportUrlSection() {
  document.getElementById('recording-source-field').style.display = '';
  document.getElementById('import-url-field').style.display = 'none';
  document.getElementById('import-url-input').value = '';
  document.getElementById('import-url-inspect-area').innerHTML = '';
  _importUrlInfo = null;
  _importUrlUrl  = null;
}

async function checkImportUrl() {
  const url = document.getElementById('import-url-input').value.trim();
  const area = document.getElementById('import-url-inspect-area');
  if (!url) return;
  _panelDirty = true;
  const btn = document.getElementById('btn-check-url');
  btn.disabled = true;
  btn.textContent = 'Checking…';
  area.innerHTML = '<div class="probing-spinner">Checking link...</div>';
  _importUrlInfo = null;
  try {
    const res = await fetch('/api/import-url/inspect', {
      method: 'POST', headers: {'Content-Type': 'application/json'},
      body:   JSON.stringify({url}),
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) {
      area.innerHTML = `<div style="color:var(--red);font-size:12px">${escHtml(formatApiError(data))}</div>`;
      return;
    }
    _importUrlInfo = data;
    _importUrlUrl  = url;
    renderImportUrlInspect(data);
  } catch (err) {
    area.innerHTML = `<div style="color:var(--red);font-size:12px">Could not check link: ${escHtml(String(err.message || err))}</div>`;
  } finally {
    btn.disabled = false;
    btn.textContent = 'Check link';
  }
}

function _fmtDurationS(seconds) {
  return _msToHms(Math.max(0, seconds || 0) * 1000);
}

function _fmtBytesHuman(n) {
  if (!n || n <= 0) return 'unknown';
  const units = ['B', 'KB', 'MB', 'GB'];
  let size = n;
  for (const unit of units) {
    if (size < 1024 || unit === 'GB') return `${unit === 'B' ? Math.round(size) : size.toFixed(1)} ${unit}`;
    size /= 1024;
  }
  return `${size.toFixed(1)} GB`;
}

function renderImportUrlInspect(info) {
  const area = document.getElementById('import-url-inspect-area');
  const metaParts = [
    escHtml(info.uploader || 'Unknown channel'),
    _fmtDurationS(info.duration_s),
    ...(info.category ? [escHtml(info.category)] : []),
    ...(info.upload_date ? [escHtml(info.upload_date)] : []),
    `est. ${_fmtBytesHuman(info.estimated_size_bytes)}`,
  ];
  const alreadyNote = info.already_imported ? `
    <div class="long-run-warning">
      <span aria-hidden="true">&#9888;</span>
      <span>Already imported as "${escHtml(info.existing_filename || '')}". Downloading again saves a separate copy.</span>
    </div>` : '';

  area.innerHTML = `
    <div class="estimate-box">
      <div class="probe-info"><strong>${escHtml(info.title)}</strong><br>${metaParts.join(' &middot; ')}</div>
      <div id="import-url-estimate-body"><div class="probing-spinner">Estimating processing time...</div></div>
      ${alreadyNote}
    </div>
    <div class="new-recording-actions" style="padding-top:10px">
      <button class="btn primary" id="btn-start-import" onclick="startImportUrlDownload()">Download</button>
    </div>`;
  _renderImportUrlEstimate(info.duration_s);
}

async function _renderImportUrlEstimate(durationS) {
  const body = document.getElementById('import-url-estimate-body');
  try {
    const res = await fetch('/api/estimate', {
      method: 'POST', headers: {'Content-Type': 'application/json'},
      // Downloaded VODs have exactly one audio track (see roadmap plan 08) -
      // the default one-track/one-transcribe estimate is trivially right.
      body:   JSON.stringify({duration_s: durationS, audio_tracks: 1, transcribe_tracks: 1, has_gpu: true}),
    });
    if (!body) return;
    if (!res.ok) { body.innerHTML = ''; return; }
    body.innerHTML = _estimateBodyHTML(await res.json());
  } catch {
    if (body) body.innerHTML = '';
  }
}

async function startImportUrlDownload() {
  if (!_importUrlInfo || !_importUrlUrl) return;
  const btn = document.getElementById('btn-start-import');
  btn.disabled = true;
  btn.textContent = 'Starting…';

  const startRes = await fetch('/api/import-url/start', {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    body:   JSON.stringify({url: _importUrlUrl}),
  });
  if (!startRes.ok) {
    const err = await startRes.json().catch(() => ({}));
    showToast(formatApiError(err) || 'Failed to start download', 'error');
    btn.disabled = false;
    btn.textContent = 'Download';
    return;
  }

  const title = _importUrlInfo.title;
  _panelDirty = false;
  _doCloseNewRecordingPanel();
  openLog();
  appendLog(`Downloading: ${title}`);
  streamSSE(
    '/api/import-url/events',
    () => _onImportUrlDownloadDone(title),
    [{label: 'Download', patterns: ['[Download]']}],
    `Importing ${title}`,
    true,
    line => _onImportUrlLine(line),
  );
  setJobCancel({
    url:     '/api/import-url/cancel',
    title:   'Cancel download?',
    body:    'The partial download will be discarded. You can start the import again later.',
    confirm: 'Cancel Download',
    logMsg:  '[Import cancelled]',
  });
}

// Mirrors url_import.py's format_progress_line/parse_progress_line - keep the
// three in sync if that format ever changes.
const _IMPORT_PROGRESS_RE = /^\[Download\] ([\d.]+)% of (\S+)(?: at (\S+)\/s)?(?:, ETA (\S+))?$/;
const _IMPORT_DONE_RE     = /^\[Imported\] (.+)$/;

let _lastImportedPath = null;

function _onImportUrlLine(line) {
  const imported = line.match(_IMPORT_DONE_RE);
  if (imported) { _lastImportedPath = imported[1].trim(); return; }

  const m = line.match(_IMPORT_PROGRESS_RE);
  const el = document.getElementById('step-0');
  if (!m || !el) return;
  const pct = parseFloat(m[1]);
  const speedPart = m[3] ? ` at ${m[3]}/s` : '';
  const etaPart = m[4] ? ` (~${m[4]} left)` : '';
  el.textContent = `Download · ${pct.toFixed(0)}%${speedPart}${etaPart}`;
  el.style.backgroundImage = `linear-gradient(to right, var(--green) ${pct}%, var(--accent) ${pct}%)`;
}

function _onImportUrlDownloadDone(title) {
  showToast('Download complete', 'success');
  SoundFx.play('analysis');
  if (!_lastImportedPath) {
    showToast('Download finished, but the file path was not reported - open it from the downloads folder.', 'warning');
    return;
  }
  const path = _lastImportedPath;
  _lastImportedPath = null;
  // The job just finished, but endJobUI() only re-enables #btn-analyze after its
  // cosmetic 2s "done" pill delay - force it open now instead of waiting.
  document.getElementById('btn-analyze').disabled = false;
  openNewRecordingPanel().then(() => {
    document.getElementById('analyze-path').value = path;
    scheduleProbe();
  });
}

// ── profile manager ───────────────────────────────────────────────────────────
const TRACK_LABELS = ['player_voice', 'ingame_voicechat', 'game_sounds', 'combined', 'unlabeled'];
const TRACK_LABEL_DISPLAY = {
  player_voice:      'Player voice',
  ingame_voicechat:  'In-game voice chat',
  game_sounds:       'Game sounds',
  combined:          'Combined (all tracks)',
  unlabeled:         'Unlabeled',
};
let _allProfiles = [];
let _profileEditorDirty = false;
let _profileModalOpener = null;

async function openProfileManager() {
  _profileModalOpener = document.activeElement;
  document.getElementById('profile-modal').classList.add('visible');
  document.getElementById('profile-editor').style.display = 'none';
  await _refreshProfileList();
  setTimeout(() => document.querySelector('#profile-modal .btn.primary')?.focus(), 50);
}

function closeProfileManager() {
  if (!document.getElementById('profile-modal').classList.contains('visible')) return;
  const editor = document.getElementById('profile-editor');
  if (editor && editor.style.display !== 'none' && _profileEditorDirty) {
    showConfirm(
      'Discard changes?',
      'You have unsaved changes in the track layout editor. Close without saving?',
      'Discard',
      () => { _profileEditorDirty = false; _doCloseProfileManager(); },
      true,
    );
    return;
  }
  _doCloseProfileManager();
}

function _doCloseProfileManager() {
  document.getElementById('profile-modal').classList.remove('visible');
  _loadProfileDropdown();
  const opener = _profileModalOpener;
  _profileModalOpener = null;
  if (opener?.focus) opener.focus();
}

async function _refreshProfileList() {
  _allProfiles = await fetch('/api/profiles').then(r => r.json());
  const el = document.getElementById('profile-list');
  if (!_allProfiles.length) {
    el.innerHTML = '<div style="color:var(--muted);font-size:13px">No track layouts saved.</div>';
    return;
  }
  el.innerHTML = _allProfiles.map(p => `
    <div style="display:flex;align-items:center;gap:8px;padding:8px 0;border-bottom:1px solid var(--border)">
      <span style="flex:1;font-size:13px">${p.builtin ? '<span title="Built-in layout - cannot be edited or deleted">&#128274;</span> ' : ''}${escHtml(p.display_name)}</span>
      <span style="color:var(--muted);font-size:12px">${plural(p.num_tracks, 'track')}</span>
      ${!p.builtin ? `
        <button class="btn" style="padding:4px 10px;font-size:12px" data-edit-profile="${escHtml(p.name)}">Edit</button>
        <button class="btn danger" style="padding:4px 10px;font-size:12px" data-delete-profile="${escHtml(p.name)}">Delete</button>
      ` : ''}
    </div>`).join('');
  el.onclick = e => {
    const editBtn   = e.target.closest('[data-edit-profile]');
    const deleteBtn = e.target.closest('[data-delete-profile]');
    if (editBtn)   editProfile(editBtn.dataset.editProfile);
    if (deleteBtn) deleteProfile(deleteBtn.dataset.deleteProfile);
  };
}

function openNewProfile() {
  _profileEditorDirty = false;
  _clearPeNameError();
  document.getElementById('profile-editor').style.display = '';
  document.getElementById('pe-name').value = '';
  document.getElementById('pe-numtracks').value = 2;
  renderTrackRows();
  setTimeout(() => document.getElementById('pe-name')?.focus(), 50);
}

function editProfile(name) {
  const p = _allProfiles.find(x => x.name === name);
  if (!p) return;
  _profileEditorDirty = false;
  _clearPeNameError();
  document.getElementById('profile-editor').style.display = '';
  document.getElementById('pe-name').value     = p.name;
  document.getElementById('pe-numtracks').value = p.num_tracks;
  renderTrackRows(p.assignments);
}

function renderTrackRows(existingAssignments) {
  const n   = parseInt(document.getElementById('pe-numtracks').value) || 1;
  const rows = [];
  for (let i = 0; i < n; i++) {
    const a     = existingAssignments?.[i] ?? null;
    const label = a ? a.label : (i === 0 ? 'combined' : 'unlabeled');
    const doTx  = a ? (a.do_transcribe !== false) : (label !== 'game_sounds');
    const doSc  = a ? (a.do_score !== false)      : (label !== 'game_sounds');
    const opts  = TRACK_LABELS.map(l =>
      `<option value="${l}"${l === label ? ' selected' : ''}>${TRACK_LABEL_DISPLAY[l] || l}</option>`
    ).join('');
    rows.push(`
      <div style="display:flex;align-items:center;gap:8px;padding:5px 0;font-size:13px">
        <span style="color:var(--muted);width:60px;flex-shrink:0">Track ${i + 1}</span>
        <select id="pe-label-${i}" onchange="onLabelChange(${i})"
                style="flex:1;padding:5px 8px;background:var(--bg);border:1px solid var(--border);border-radius:5px;color:var(--text);font-size:12px">${opts}</select>
        <label style="display:flex;align-items:center;gap:4px;font-size:12px;white-space:nowrap"
               title="Transcribe this track's speech">
          <input type="checkbox" id="pe-tx-${i}" ${doTx ? 'checked' : ''}> Transcribe
        </label>
        <label style="display:flex;align-items:center;gap:4px;font-size:12px;white-space:nowrap"
               title="Use this track for scoring">
          <input type="checkbox" id="pe-sc-${i}" ${doSc ? 'checked' : ''}> Score
        </label>
      </div>`);
  }
  document.getElementById('pe-tracks').innerHTML = rows.join('');
}

function onLabelChange(i) {
  const isGameSound = document.getElementById(`pe-label-${i}`).value === 'game_sounds';
  document.getElementById(`pe-tx-${i}`).checked = !isGameSound;
  document.getElementById(`pe-sc-${i}`).checked = !isGameSound;
}

function _peNameError(msg) {
  const errEl = document.getElementById('pe-name-error');
  errEl.textContent = msg;
  errEl.style.display = '';
  document.getElementById('pe-name').focus();
}

function _clearPeNameError() {
  const errEl = document.getElementById('pe-name-error');
  if (errEl) { errEl.textContent = ''; errEl.style.display = 'none'; }
}

async function saveProfile() {
  const name = document.getElementById('pe-name').value.trim();
  if (!name)                 { _peNameError('Enter a name for this layout'); return; }
  if (name.startsWith('__')) { _peNameError('Names starting with "__" are reserved for built-in layouts'); return; }
  const n = parseInt(document.getElementById('pe-numtracks').value) || 1;
  const assignments = Array.from({length: n}, (_, i) => ({
    stream_position: i,
    label:           document.getElementById(`pe-label-${i}`).value,
    do_transcribe:   document.getElementById(`pe-tx-${i}`).checked,
    do_score:        document.getElementById(`pe-sc-${i}`).checked,
  }));
  const res = await fetch('/api/profiles', {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    body:   JSON.stringify({name, assignments}),
  });
  if (!res.ok) {
    const e = await res.json();
    showToast(e.detail || 'Save failed', 'error');
    return;
  }
  _profileEditorDirty = false;
  document.getElementById('profile-editor').style.display = 'none';
  await _refreshProfileList();
  showToast(`Track layout "${name}" saved`);
}

function deleteProfile(name) {
  showConfirm(
    'Delete track layout?',
    `Delete track layout <strong>${escHtml(name)}</strong>? This cannot be undone.`,
    'Delete',
    () => _doDeleteProfile(name),
    true,
  );
}

async function _doDeleteProfile(name) {
  const res = await fetch(`/api/profiles/${encodeURIComponent(name)}`, {method: 'DELETE'});
  if (!res.ok) {
    const e = await res.json().catch(() => ({}));
    showToast(formatApiError(e) || 'Delete failed', 'error');
    return;
  }
  await _refreshProfileList();
  showToast(`Track layout "${name}" deleted`);
}

function cancelProfileEdit() {
  _profileEditorDirty = false;
  document.getElementById('profile-editor').style.display = 'none';
}

document.addEventListener('DOMContentLoaded', () => {
  const editor = document.getElementById('profile-editor');
  if (editor) {
    editor.addEventListener('input',  () => { _profileEditorDirty = true; });
    editor.addEventListener('change', () => { _profileEditorDirty = true; });
  }
});

// ── drag-and-drop analyze (Electron-first) ──────────────────────────────────
// A plain browser can't read a filesystem path off a dropped File, so the
// overlay affordance only appears when window.electronAPI is present; a
// browser drop still gets a toast pointing at manual path entry instead.
const DROP_VIDEO_EXTENSIONS = ['.mp4', '.mkv', '.mov', '.avi', '.webm', '.flv', '.ts'];

let _dragDepth = 0;

function _dragHasFiles(e) {
  return !!(e.dataTransfer && Array.from(e.dataTransfer.types).includes('Files'));
}

document.addEventListener('dragenter', e => {
  if (!_dragHasFiles(e) || !window.electronAPI) return;
  e.preventDefault();
  _dragDepth++;
  document.getElementById('drop-overlay').style.display = 'flex';
});

document.addEventListener('dragover', e => {
  if (!_dragHasFiles(e) || !window.electronAPI) return;
  e.preventDefault();  // required for the browser to fire 'drop'
});

document.addEventListener('dragleave', e => {
  if (!_dragHasFiles(e) || !window.electronAPI) return;
  e.preventDefault();
  _dragDepth = Math.max(0, _dragDepth - 1);
  if (_dragDepth === 0) document.getElementById('drop-overlay').style.display = 'none';
});

document.addEventListener('drop', async e => {
  if (!_dragHasFiles(e)) return;
  e.preventDefault();
  _dragDepth = 0;
  document.getElementById('drop-overlay').style.display = 'none';

  const files = Array.from(e.dataTransfer.files);
  if (!files.length) return;

  if (!window.electronAPI || typeof window.electronAPI.getPathForFile !== 'function') {
    showToast('Drag and drop needs the desktop app - use Analyze and enter the file path instead.', 'info');
    return;
  }
  if (files.length > 1) {
    showToast('Drop one recording at a time - using the first file.', 'warning');
  }
  const file = files[0];
  const ext = '.' + (file.name.split('.').pop() || '').toLowerCase();
  if (!DROP_VIDEO_EXTENSIONS.includes(ext)) {
    showToast(`Unsupported file type "${ext}" - expected a video file.`, 'error');
    return;
  }
  const path = window.electronAPI.getPathForFile(file);
  if (!path) {
    showToast("Could not read the dropped file's path.", 'error');
    return;
  }
  await openNewRecordingPanel();
  document.getElementById('analyze-path').value = path;
  scheduleProbe();
});

Object.assign(window, {
  _isNewRecordingPanelOpen, openNewRecordingPanel, openReanalyzePanel, closeNewRecordingPanel,
  _doCloseNewRecordingPanel, _toggleCtxPill, scheduleProbe,
  _renderSubtitleSourcePicker, _onSubtitleSourceChange,
  runEstimate, renderEstimate, startAnalyze, _doStartAnalyze, _streamAnalyzeEvents, reattachAnalysis,
  _showAnalysisToast, _surfaceAnalyzeWarnings, _warmPreviewProxy, pickFile,
  showImportUrlSection, hideImportUrlSection, checkImportUrl, startImportUrlDownload,
  openProfileManager, closeProfileManager, openNewProfile, renderTrackRows,
  onLabelChange, _clearPeNameError, saveProfile, deleteProfile, cancelProfileEdit,
});
})();

//# sourceURL=reel.js
(function () {
// Feature-map - Highlight reel (code: demo_reel; UI "Highlight Reel").
//   API: routes/reel.py · Tests: tests/ui/test_ui_reel.py
// ── highlight reels (combined Build + View modal) ──────────────────────────────
let _reelClips = [];
let _reelsOpener = null;
// Curation (order + inclusion) lives for one modal session: tab switches keep
// it; reopening the modal or changing the source select starts fresh.
let _reelBuildLoaded = false;

// Preselected "Clips from" source (e.g. a session) applied on the next Build-tab
// population, so a caller can open the reel builder already scoped.
let _reelPendingSource = null;

// Adds one "Session: {name}" option per session that has at least one member with
// approved clips, so the reel pool can span a whole session's recordings.
function _appendSessionScopeOptions(sel) {
  const approvedByVideo = new Map(AppState.videos.map(v => [v.id, v.approved]));
  const usable = (AppState.sessions || []).filter(
    s => s.member_ids.some(id => (approvedByVideo.get(id) || 0) > 0)
  );
  if (!usable.length) return;
  const group = document.createElement('optgroup');
  group.label = 'Sessions';
  for (const s of usable) {
    const approved = s.member_ids.reduce((n, id) => n + (approvedByVideo.get(id) || 0), 0);
    const opt = document.createElement('option');
    opt.value = `session:${s.id}`;
    opt.textContent = `${s.name || s.title || 'Session'} (${approved} approved)`;
    group.appendChild(opt);
  }
  sel.appendChild(group);
}

function openReelForSession(sessionId, _memberIds) {
  _reelPendingSource = `session:${sessionId}`;
  openHighlightReelsModal('build');
}

async function openHighlightReelsModal(tab) {
  _reelsOpener = _reelsOpener || document.activeElement;
  _reelBuildLoaded = false;
  _reelPoolStatuses = new Set(['approved']);
  document.querySelectorAll('[data-reel-status]').forEach(chip => {
    const active = chip.dataset.reelStatus === 'approved';
    chip.classList.toggle('active', active);
    chip.setAttribute('aria-pressed', active ? 'true' : 'false');
  });
  document.getElementById('highlight-reels-modal').classList.add('visible');
  await switchReelTab(tab || 'build');
  _prefillReelWordHighlight();
  setTimeout(() => document.querySelector('#highlight-reels-modal .btn')?.focus(), 50);
}

// Word-highlight is a burn-in-only option, so its controls only show when the
// capture mode is "Burn into video", and the words-on-screen count only when
// word-highlight itself is on.
function _onReelCaptionsChange(mode) {
  document.getElementById('demo-word-highlight-row').style.display = mode === 'burnin' ? '' : 'none';
  _onReelWordHighlightChange(document.getElementById('demo-word-highlight').checked);
}

function _onReelWordHighlightChange(enabled) {
  const burnin = document.getElementById('demo-captions').value === 'burnin';
  document.getElementById('demo-chunk-size-row').style.display = (enabled && burnin) ? 'flex' : 'none';
}

async function _prefillReelWordHighlight() {
  try {
    const cfg = await fetch('/api/config').then(r => r.json());
    document.getElementById('demo-word-highlight').checked = !!cfg.caption_word_highlight;
    document.getElementById('demo-chunk-size').value = cfg.caption_word_chunk_size || 4;
  } catch { /* leave defaults */ }
  _onReelCaptionsChange(document.getElementById('demo-captions').value);
}

async function switchReelTab(tab) {
  document.getElementById('reel-tab-build').style.display = tab === 'build' ? '' : 'none';
  document.getElementById('reel-tab-view').style.display  = tab === 'view'  ? '' : 'none';
  document.getElementById('reel-tab-btn-build').classList.toggle('active', tab === 'build');
  document.getElementById('reel-tab-btn-view').classList.toggle('active',  tab === 'view');

  if (tab === 'build') {
    const totalApproved = AppState.videos.reduce((n, v) => n + v.approved, 0);
    if (totalApproved === 0) {
      _reelClips = [];
      _reelBuildLoaded = false;
      document.getElementById('demo-status').textContent = '';
      document.getElementById('reel-clip-list').innerHTML =
        '<div style="padding:24px;text-align:center;color:var(--muted);font-size:12px">No approved clips yet - approve clips from the sidebar, then come back.</div>';
      document.getElementById('reel-estimate').textContent = '';
      return;
    }
    document.getElementById('demo-status').textContent = '';
    const sel = document.getElementById('demo-video-id');
    const prevSource = _reelPendingSource || sel.value;
    _reelPendingSource = null;
    sel.innerHTML = '<option value="">All approved clips</option>';
    _appendSessionScopeOptions(sel);
    for (const v of AppState.videos) {
      if (!v.approved) continue;
      const opt = document.createElement('option');
      opt.value = v.id;
      opt.textContent = `${v.filename} (${v.approved} approved)`;
      sel.appendChild(opt);
    }
    sel.value = prevSource;
    if (sel.value !== prevSource) {
      // Selected source lost its approved clips - fall back to all and reload
      sel.value = '';
      _reelBuildLoaded = false;
    }
    if (!_reelBuildLoaded) await loadReelClips();
  } else {
    const layout = document.getElementById('reels-layout');
    layout.innerHTML = '<div class="reels-empty">Loading&#x2026;</div>';
    const reels = await fetch('/api/demo/list').then(r => r.json()).catch(() => []);
    if (!reels.length) {
      layout.innerHTML = '<div class="reels-empty">No highlight reels yet - build one first.</div>';
      return;
    }
    layout.innerHTML = `
      <div class="reels-list" id="reels-list"></div>
      <div class="reels-player-area">
        <video controls id="reels-video"></video>
      </div>
    `;
    const list = document.getElementById('reels-list');
    reels.forEach((reel, i) => {
      const item = document.createElement('div');
      item.className = 'reel-item' + (i === 0 ? ' active' : '');
      const capBadge = reel.has_captions ? ' &middot; <span style="color:var(--green)" title="Captions available">CC</span>' : '';
      const staleBadge = reel.stale ? ' &middot; <span style="color:var(--warning)" title="A member clip was re-exported since this reel was built">Stale - rebuild to update</span>' : '';
      item.innerHTML =
        `<div class="reel-name">${escHtml(reel.filename)}</div>` +
        `<div class="reel-meta">${escHtml(reel.date)} &middot; ${reel.size_mb} MB${capBadge}${staleBadge}</div>`;
      if (reel.can_caption) {
        const capBtn = document.createElement('button');
        capBtn.className = 'btn ghost';
        capBtn.style.cssText = 'font-size:10px;padding:2px 6px;margin-top:4px';
        capBtn.textContent = reel.has_captions ? '↻ Regenerate captions' : '+ Generate captions';
        capBtn.onclick = e => { e.stopPropagation(); _regenReelCaptions(reel, capBtn); };
        item.appendChild(capBtn);
      }
      if (AppState.canReveal) {
        const revealBtn = document.createElement('button');
        revealBtn.className = 'btn ghost';
        revealBtn.style.cssText = 'font-size:10px;padding:2px 6px;margin-top:4px';
        revealBtn.textContent = 'Show in Folder';
        revealBtn.onclick = e => {
          e.stopPropagation();
          const sep = AppState.reelsDir && AppState.reelsDir.includes('\\') ? '\\' : '/';
          revealInFolder(`${AppState.reelsDir}${sep}${reel.filename}`);
        };
        item.appendChild(revealBtn);
      }
      const delBtn = document.createElement('button');
      delBtn.className = 'btn ghost danger';
      delBtn.style.cssText = 'font-size:10px;padding:2px 6px;margin-top:4px';
      delBtn.textContent = 'Delete';
      delBtn.onclick = e => { e.stopPropagation(); _deleteReel(reel); };
      item.appendChild(delBtn);
      item.onclick = () => _playReel(reel, item);
      list.appendChild(item);
    });
    _playReel(reels[0], list.firstChild);
  }
}

function closeHighlightReelsModal() {
  const vid = document.getElementById('reels-video');
  if (vid) { vid.pause(); vid.src = ''; }
  document.getElementById('highlight-reels-modal').classList.remove('visible');
  const opener = _reelsOpener;
  _reelsOpener = null;
  if (opener?.focus) opener.focus();
}

// Status filter for the reel builder's clip pool - Approved only by default,
// matching the historical /api/demo/approved-clips behavior.
let _reelPoolStatuses = new Set(['approved']);

function _reelPoolQs() {
  const params = new URLSearchParams();
  const sourceVal = document.getElementById('demo-video-id').value;
  if (sourceVal.startsWith('session:')) {
    const sessionId = parseInt(sourceVal.slice('session:'.length), 10);
    const session = (AppState.sessions || []).find(s => s.id === sessionId);
    if (session && session.member_ids.length) params.set('video_ids', session.member_ids.join(','));
  } else if (sourceVal) {
    params.set('video_id', sourceVal);
  }
  params.set('statuses', [..._reelPoolStatuses].join(','));
  return `?${params.toString()}`;
}

// Toggling a chip must never leave zero statuses selected - the API rejects
// an empty statuses param, and an empty pool with no way back out is a trap.
function _toggleReelPoolStatus(status) {
  if (_reelPoolStatuses.has(status)) {
    if (_reelPoolStatuses.size === 1) return;
    _reelPoolStatuses.delete(status);
  } else {
    _reelPoolStatuses.add(status);
  }
  document.querySelectorAll('[data-reel-status]').forEach(chip => {
    const active = _reelPoolStatuses.has(chip.dataset.reelStatus);
    chip.classList.toggle('active', active);
    chip.setAttribute('aria-pressed', active ? 'true' : 'false');
  });
  _refetchReelPool();
}

async function loadReelClips() {
  _reelClips = [];
  await _refetchReelPool();
}

// Fetches the current status/video pool and merges it into _reelClips:
// clips still in the pool keep their order and included/excluded state;
// clips newly entering the pool are appended, defaulting to excluded unless
// they're approved - so toggling on Unreviewed/Rejected can't silently stuff
// clips into the reel. Clips that fell out of the pool are dropped.
async function _refetchReelPool() {
  const listEl = document.getElementById('reel-clip-list');
  if (!_reelBuildLoaded) {
    listEl.innerHTML = '<div style="padding:16px;text-align:center;color:var(--muted);font-size:12px">Loading…</div>';
  }
  let fresh;
  try {
    fresh = await fetch(`/api/demo/approved-clips${_reelPoolQs()}`).then(r => r.json());
    _reelBuildLoaded = true;
  } catch {
    fresh = null;
  }
  if (!fresh) {
    _reelClips = [];
    _reelBuildLoaded = false;
    renderReelClipList();
    updateReelEstimate();
    return;
  }
  const freshById = new Map(fresh.map(c => [c.id, c]));
  const kept = _reelClips.filter(c => freshById.has(c.id)).map(c => ({...c, ...freshById.get(c.id), included: c.included}));
  const keptIds = new Set(kept.map(c => c.id));
  const added = fresh.filter(c => !keptIds.has(c.id)).map(c => ({...c, included: c.status === 'approved'}));
  _reelClips = [...kept, ...added];
  renderReelClipList();
  updateReelEstimate();
}

function renderReelClipList() {
  const listEl = document.getElementById('reel-clip-list');
  if (!_reelClips.length) {
    listEl.innerHTML = '<div style="padding:16px;text-align:center;color:var(--muted);font-size:12px">No approved clips found</div>';
    return;
  }
  listEl.innerHTML = '';
  listEl.ondragover = _reelListDragOver;
  _reelClips.forEach((c, i) => {
    const row = document.createElement('div');
    row.className = 'reel-clip-row' + (c.included ? '' : ' excluded');
    row.dataset.clipId = c.id;
    row.innerHTML = `
      <div class="reel-clip-drag" title="Drag to reorder">&#x2830;&#x2830;</div>
      <div class="reel-clip-move">
        <button title="Move up" ${i === 0 ? 'disabled' : ''} onclick="_reelMove(${i}, -1)">&#9650;</button>
        <button title="Move down" ${i === _reelClips.length - 1 ? 'disabled' : ''} onclick="_reelMove(${i}, 1)">&#9660;</button>
      </div>
      <input type="checkbox" ${c.included ? 'checked' : ''} onchange="_reelToggle(${i}, this.checked)" title="Include in reel">
      <div class="reel-clip-info">
        <div class="reel-clip-name">${escHtml(c.description || `Clip ${c.id}`)}</div>
        <div class="reel-clip-meta">${escHtml(c.start_hms)} · ${escHtml(c.duration_hms)} · &#11088;${Math.round(c.score_overall*100)}%
          ${c.has_export ? '' : ' · <span style="color:var(--warning)">not exported</span>'}
        </div>
      </div>`;
    _wireReelRowDrag(row);
    listEl.appendChild(row);
  });
}

// Rows are draggable only while the grip is pressed, so text selection and the
// checkbox keep working; the ▲▼ buttons remain the keyboard path.
function _wireReelRowDrag(row) {
  const handle = row.querySelector('.reel-clip-drag');
  handle.addEventListener('mousedown', () => { row.draggable = true; });
  row.addEventListener('dragstart', e => {
    row.classList.add('dragging');
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', row.dataset.clipId);
  });
  row.addEventListener('dragend', () => {
    row.classList.remove('dragging');
    row.draggable = false;
    _commitReelDomOrder();
  });
}

function _reelListDragOver(e) {
  const listEl = e.currentTarget;
  const dragging = listEl.querySelector('.reel-clip-row.dragging');
  if (!dragging) return;
  e.preventDefault();
  const rows = [...listEl.querySelectorAll('.reel-clip-row:not(.dragging)')];
  const rowBelow = rows.find(el => {
    const box = el.getBoundingClientRect();
    return e.clientY < box.top + box.height / 2;
  });
  if (rowBelow) listEl.insertBefore(dragging, rowBelow);
  else listEl.appendChild(dragging);
}

function _commitReelDomOrder() {
  const listEl = document.getElementById('reel-clip-list');
  const domOrder = [...listEl.querySelectorAll('.reel-clip-row')].map(el => Number(el.dataset.clipId));
  _reelClips.sort((a, b) => domOrder.indexOf(a.id) - domOrder.indexOf(b.id));
  renderReelClipList();
  updateReelEstimate();
}

function _reelMove(i, dir) {
  const j = i + dir;
  if (j < 0 || j >= _reelClips.length) return;
  [_reelClips[i], _reelClips[j]] = [_reelClips[j], _reelClips[i]];
  renderReelClipList();
  updateReelEstimate();
}

function _reelToggle(i, included) {
  _reelClips[i].included = included;
  renderReelClipList();
  updateReelEstimate();
}

function updateReelEstimate() {
  const included = _reelClips.filter(c => c.included);
  const n = included.length;
  const totalFootageMs = included.reduce((s, c) => s + c.duration_ms, 0);
  const titleDur = parseFloat(document.getElementById('demo-title-dur')?.value || 3);
  const transDur = parseFloat(document.getElementById('demo-trans-dur')?.value || 0.5);
  const transition = document.getElementById('demo-transition')?.value || 'fade';

  const totalFootageS = totalFootageMs / 1000;
  let encodeEtaS = 0;
  if (transition === 'none') {
    encodeEtaS = 5;
  } else {
    const totalEncodeS = totalFootageS + n * titleDur;
    encodeEtaS = totalEncodeS / 3;
  }

  const unexported = included.filter(c => !c.has_export).length;
  const exportBtn = document.getElementById('reel-export-btn');
  if (exportBtn) {
    exportBtn.style.display = unexported > 0 ? '' : 'none';
    exportBtn.textContent = `⬇ Export ${plural(unexported, 'clip')}`;
  }
  const el = document.getElementById('reel-estimate');
  if (!el) return;
  if (!n) {
    el.innerHTML = 'No clips selected';
    return;
  }
  const fmtS = s => s < 60 ? `${s.toFixed(0)}s` : `${Math.floor(s/60)}m ${(s%60).toFixed(0)}s`;
  el.innerHTML =
    `${plural(n, 'clip')} · ${fmtS(totalFootageS)} footage · encode ~${fmtS(encodeEtaS)}` +
    (unexported ? `<div class="reel-no-export-warn">⚠ ${plural(unexported, 'clip')} not yet exported - export them first or they will be skipped</div>` : '');
}

async function exportUnexportedReelClips() {
  if (_blockedByAnalyze('export clips')) return;
  const toExport = _reelClips.filter(c => c.included && !c.has_export);
  if (!toExport.length) {
    showToast('All selected clips are already exported', 'info');
    return;
  }
  const ids = toExport.map(c => c.id).join(',');
  const statusEl = document.getElementById('demo-status');
  statusEl.style.color = 'var(--muted)';
  statusEl.textContent = `Exporting ${plural(toExport.length, 'clip')}…`;
  openLog();
  streamSSE(
    `/api/clips/bulk-export?clip_ids=${encodeURIComponent(ids)}`,
    () => {
      statusEl.textContent = '';
      showToast('Clips exported');
      SoundFx.play('export');
      _refreshReelExportStatus();
      loadVideos();
    },
    [{label: 'Exporting', patterns: ['Exporting clip', 'OK clip', 'Skipping']}],
    'Export',
  );
}

// Refresh has_export on the current clip list without discarding the user's
// order/inclusion choices (loadReelClips() would reset both).
async function _refreshReelExportStatus() {
  const fresh = await fetch(`/api/demo/approved-clips${_reelPoolQs()}`).then(r => r.json()).catch(() => null);
  if (!fresh) return;
  const exportById = new Map(fresh.map(c => [c.id, c.has_export]));
  _reelClips.forEach(c => { if (exportById.has(c.id)) c.has_export = exportById.get(c.id); });
  renderReelClipList();
  updateReelEstimate();
}

function closeDemoModal() { closeHighlightReelsModal(); }

let _reelPreviewOpener = null;
let _reelPreviewList = [];
let _reelPreviewIdx = 0;

async function previewReelPlaylist() {
  const included = _reelClips.filter(c => c.included && c.has_export);
  if (!included.length) {
    showToast('No exported clips selected - export clips first to preview them', 'warning');
    return;
  }
  _reelPreviewOpener = document.activeElement;
  _reelPreviewList = included;
  document.getElementById('reel-preview-modal').classList.add('visible');
  setTimeout(() => document.querySelector('#reel-preview-modal .btn')?.focus(), 50);
  await _reelPreviewPlay(0);
}

async function _reelPreviewPlay(idx) {
  const vid   = document.getElementById('reel-preview-video');
  const label = document.getElementById('reel-preview-label');
  if (idx >= _reelPreviewList.length) {
    _reelPreviewIdx = _reelPreviewList.length;  // Previous from here returns to the last clip
    label.textContent = 'Playlist complete';
    vid.pause();
    _updateReelPreviewNav();
    return;
  }
  _reelPreviewIdx = idx;
  label.textContent = `Clip ${idx + 1} of ${_reelPreviewList.length}`;
  _updateReelPreviewNav();
  const c = _reelPreviewList[idx];
  const media = await fetch(`/api/clips/${c.id}/media_url`).then(r => r.json()).catch(() => null);
  if (media?.url) {
    vid.src = media.url;
    vid.onended = () => _reelPreviewPlay(_reelPreviewIdx + 1);
    vid.play().catch(() => {});
  } else {
    await _reelPreviewPlay(idx + 1);
  }
}

function _reelPreviewStep(dir) {
  const target = _reelPreviewIdx + dir;
  if (target < 0 || target >= _reelPreviewList.length) return;
  _reelPreviewPlay(target);
}

function _updateReelPreviewNav() {
  const prev = document.getElementById('reel-preview-prev');
  const next = document.getElementById('reel-preview-next');
  if (!prev || !next) return;
  prev.disabled = _reelPreviewIdx <= 0;
  next.disabled = _reelPreviewIdx >= _reelPreviewList.length - 1;
}

function closeReelPreview() {
  const vid = document.getElementById('reel-preview-video');
  vid.pause();
  vid.src = '';
  vid.onended = null;
  document.getElementById('reel-preview-modal').classList.remove('visible');
  const opener = _reelPreviewOpener;
  _reelPreviewOpener = null;
  if (opener?.focus) opener.focus();
}

async function startDemo() {
  const included = _reelClips.filter(c => c.included);
  if (!included.length) {
    showToast('No clips selected', 'warning');
    return;
  }
  const unexported = included.filter(c => !c.has_export);
  if (unexported.length > 0 && included.length === unexported.length) {
    showToast('None of the selected clips have been exported - export them first', 'warning');
    return;
  }

  const captionMode = document.getElementById('demo-captions').value;
  const body = {
    clip_ids:    included.map(c => c.id),
    transition:  document.getElementById('demo-transition').value,
    trans_dur:   parseFloat(document.getElementById('demo-trans-dur').value),
    title_dur:   parseFloat(document.getElementById('demo-title-dur').value),
    output_name: document.getElementById('demo-output-name').value.trim(),
    captions:      captionMode !== 'none',
    bake_captions: captionMode === 'burnin',
  };
  if (captionMode === 'burnin') {
    body.word_highlight = document.getElementById('demo-word-highlight').checked;
    if (body.word_highlight) {
      const chunkRaw = document.getElementById('demo-chunk-size').value.trim();
      if (chunkRaw !== '') body.word_chunk_size = parseInt(chunkRaw, 10);
    }
  }

  const statusEl = document.getElementById('demo-status');
  statusEl.style.color = 'var(--muted)';
  statusEl.textContent = 'Starting…';

  const res = await fetch('/api/demo/start', {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    body:   JSON.stringify(body),
  });
  if (!res.ok) {
    const e = await res.json();
    statusEl.style.color = 'var(--red)';
    statusEl.textContent = e.detail || 'Failed to start reel build.';
    return;
  }
  const data = await res.json();
  const skipNote = unexported.length ? ` - ${plural(unexported.length, 'unexported clip')} skipped` : '';
  statusEl.textContent = `Building reel from ${plural(data.clip_count, 'clip')}…${skipNote}`;
  closeDemoModal();
  openLog();
  if (unexported.length) appendLog(`[Skipping ${plural(unexported.length, 'clip')} not yet exported]`);
  streamSSE(
    '/api/demo/events',
    () => {
      loadVideos();
      showToast(`Highlight reel complete!${skipNote}`, 'success');
      openHighlightReelsModal('view');
      SoundFx.play('reel');
    },
    [{label: 'Building', patterns: ['Generating title', 'Encoding', 'OK']}],
    'Reel',
  );
}

// ── batch export ──────────────────────────────────────────────────────────────
let _batchExportVideoId = null;
let _batchExportOpener = null;

function _updateBatchModeSummary() {
  _renderExportModeSummary(
    document.getElementById('batch-mode-summary'),
    document.getElementById('batch-captions').value === 'hardsub',
    false,
    document.getElementById('batch-retranscribe').checked,
  );
}

function _onBatchCaptionsChange() {
  _updateBatchModeSummary();
}

function _onBatchRetranscribeChange(checked) {
  document.getElementById('batch-retranscribe-model').disabled = !checked;
  _updateBatchModeSummary();
}

function openBatchExportModal(videoId) {
  _batchExportOpener = document.activeElement;
  _batchExportVideoId = videoId;
  const video = AppState.videos.find(v => v.id === videoId);
  const modalTitle = document.querySelector('#batch-export-modal h3');
  if (modalTitle) modalTitle.textContent = video ? `Export Approved - ${video.filename}` : 'Export Approved Clips';
  document.getElementById('batch-min-score').value = 0;
  document.getElementById('batch-min-score-val').textContent = '0%';
  document.getElementById('batch-skip-exported').checked = true;
  document.getElementById('batch-container').value = '';
  document.getElementById('batch-captions').value = 'none';
  const retx = document.getElementById('batch-retranscribe');
  retx.checked = false;
  document.getElementById('batch-retranscribe-model').disabled = true;
  _updateBatchModeSummary();
  document.getElementById('batch-export-modal').classList.add('visible');
  updateBatchEstimate();
  setTimeout(() => document.getElementById('batch-min-score')?.focus(), 50);
}

function closeBatchExportModal() {
  document.getElementById('batch-export-modal').classList.remove('visible');
  const opener = _batchExportOpener;
  _batchExportOpener = null;
  if (opener?.focus) opener.focus();
}

function updateBatchEstimate() {
  const minScore = parseFloat(document.getElementById('batch-min-score').value);
  const video = AppState.videos.find(v => v.id === _batchExportVideoId);
  if (!video) return;
  const el = document.getElementById('batch-estimate-line');
  const eligible = AppState.clips
    ? AppState.clips.filter(c => c.status === 'approved' && c.score_overall >= minScore).length
    : video.approved;
  el.textContent = `${plural(eligible, 'clip')} ${eligible === 1 ? 'matches' : 'match'}`;
}

async function confirmBatchExport() {
  const id = _batchExportVideoId;
  const minScore   = parseFloat(document.getElementById('batch-min-score').value);
  const skipExp    = document.getElementById('batch-skip-exported').checked;
  const container  = document.getElementById('batch-container').value;
  const captions   = document.getElementById('batch-captions').value;
  const retx       = document.getElementById('batch-retranscribe').checked;
  const retxModel  = document.getElementById('batch-retranscribe-model').value;
  closeBatchExportModal();

  const params = new URLSearchParams({min_score: minScore});
  if (!skipExp) params.set('skip_exported', 'false');
  if (container) params.set('container', container);
  if (captions === 'hardsub') params.set('burn_subs', 'true');
  if (captions === 'softsub') params.set('embed_subs', 'true');
  if (retx) { params.set('retranscribe', 'true'); params.set('retranscribe_model', retxModel); }

  openLog();
  streamSSE(
    `/api/videos/${id}/batch-export?${params}`,
    () => { loadVideos(); showToast('Batch export complete'); SoundFx.play('export'); },
    [{label: 'Exporting', patterns: ['Exporting clip', 'OK clip', 'Skipping']}],
    'Batch Export',
  );
}

function _playReel(reel, itemEl) {
  document.querySelectorAll('#reels-list .reel-item').forEach(el => el.classList.remove('active'));
  itemEl.classList.add('active');
  const vid = document.getElementById('reels-video');
  vid.innerHTML = '';
  vid.src = reel.url;
  if (reel.has_captions) {
    const track = document.createElement('track');
    track.kind = 'captions';
    track.label = 'Captions';
    track.srclang = 'en';
    track.default = true;
    track.src = `/api/demo/${encodeURIComponent(reel.filename)}/captions.vtt`;
    vid.appendChild(track);
  }
  vid.load();
}

function _deleteReel(reel) {
  showConfirm(
    'Delete highlight reel?',
    `"${escHtml(reel.filename)}" will be permanently removed from disk, along with its captions. Your clips are not affected.`,
    'Delete Reel',
    async () => {
      // Release the player's file handle first - on Windows the server keeps the
      // reel open while the <video> is connected, blocking the delete.
      const vid = document.getElementById('reels-video');
      if (vid) { vid.pause(); vid.removeAttribute('src'); vid.load(); }
      await new Promise(resolve => setTimeout(resolve, 400));
      const res = await fetch(`/api/demo/${encodeURIComponent(reel.filename)}`, {method: 'DELETE'});
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        showToast(`Failed to delete reel: ${formatApiError(err)}`, 'error');
      } else {
        showToast('Highlight reel deleted');
      }
      switchReelTab('view');
    },
    true,
  );
}

async function _regenReelCaptions(reel, btn) {
  if (_blockedByAnalyze('generate captions')) return;
  const original = btn.textContent;
  btn.disabled = true;
  btn.textContent = 'Generating…';
  try {
    const res = await fetch(`/api/demo/${encodeURIComponent(reel.filename)}/captions`, {method: 'POST'});
    if (!res.ok) {
      const e = await res.json().catch(() => ({}));
      showToast(e.detail || 'Could not generate captions', 'error');
      btn.textContent = original;
      btn.disabled = false;
      return;
    }
    showToast('Captions generated');
    switchReelTab('view');  // refresh badge + player track
  } catch {
    showToast('Could not generate captions', 'error');
    btn.textContent = original;
    btn.disabled = false;
  }
}

// Public API - symbols referenced cross-module, by an inline handler, or by a
// test. Internal helpers above stay private to this module's closure.
Object.assign(window, {
  openHighlightReelsModal, openReelForSession, closeHighlightReelsModal, switchReelTab,
  loadReelClips, _reelMove, _reelToggle, _toggleReelPoolStatus,
  startDemo, closeDemoModal, updateReelEstimate, exportUnexportedReelClips,
  _onReelCaptionsChange, _onReelWordHighlightChange,
  previewReelPlaylist, closeReelPreview, _reelPreviewStep,
  openBatchExportModal, closeBatchExportModal, confirmBatchExport,
  updateBatchEstimate, _onBatchCaptionsChange, _onBatchRetranscribeChange,
});
})();

//# sourceURL=contexts.js
(function () {
// Feature-map - World context (code: rp_context / Context; UI term "Contexts").
//   API: routes/contexts.py · Tests: tests/ui/test_ui_contexts.py
// ── context manager ───────────────────────────────────────────────────────────
function _parseWeight(id) {
  const v = parseFloat(document.getElementById(id).value);
  return isNaN(v) ? null : Math.max(0, v);
}
async function _loadContexts() {
  AppState.contexts = await fetch('/api/contexts').then(r => r.json()).catch(() => []);
}

// A successful load always returns at least the built-in contexts, so an empty
// list means the boot-time fetch is still pending or failed transiently. Callers
// that render contexts (e.g. the recording detail) await this so the list heals
// itself instead of staying stuck empty until a manual page refresh.
async function ensureContexts() {
  if (Array.isArray(AppState.contexts) && AppState.contexts.length) return;
  await _loadContexts();
}

// ── shared term-scope helpers (hot-words + sensitive terms) ───────────────────
// Both Settings lists let an entry be Global or scoped to a world context. These
// two helpers build the per-row "Applies to" <select> and the grouped rendering,
// so hotwords.js and sensitive.js stay identical on scoping without duplicating it.
function _termContextName(slug) {
  const ctx = (AppState.contexts || []).find(c => c.context_id === slug);
  return ctx ? (ctx.display_name || ctx.context_id) : null;
}

// Options: Global first, then every known context by display name. A slug that no
// longer names a live context (its context was deleted) keeps a "(removed)" option
// so the orphaned entry still shows its scope rather than silently reading Global.
function _termContextOptions(selectedSlug) {
  const slug = selectedSlug || '';
  let html = `<option value=""${slug === '' ? ' selected' : ''}>Global (all recordings)</option>`;
  const known = new Set();
  for (const c of (AppState.contexts || [])) {
    known.add(c.context_id);
    html += `<option value="${escHtml(c.context_id)}"${slug === c.context_id ? ' selected' : ''}>`
          + `${escHtml(c.display_name || c.context_id)}</option>`;
  }
  if (slug && !known.has(slug)) {
    html += `<option value="${escHtml(slug)}" selected>${escHtml(slug)} (removed)</option>`;
  }
  return html;
}

// Group terms under a "Global (all recordings)" heading, one heading per context
// that has entries (in the context list's order), then a "Removed context" group
// for orphaned entries. rowHtmlFn renders a single term row.
function _renderTermGroups(terms, rowHtmlFn) {
  const buckets = new Map();
  for (const term of terms) {
    const key = term.context_slug || '';
    if (!buckets.has(key)) buckets.set(key, []);
    buckets.get(key).push(term);
  }
  const order = [''];
  for (const c of (AppState.contexts || [])) if (buckets.has(c.context_id)) order.push(c.context_id);
  for (const key of buckets.keys()) {
    if (key && !order.includes(key)) order.push(key);
  }
  let html = '';
  for (const key of order) {
    const rows = buckets.get(key);
    if (!rows) continue;
    const label = key === '' ? 'Global (all recordings)' : (_termContextName(key) || `${key} (removed)`);
    html += `<div style="font-size:11px;font-weight:600;color:var(--muted);margin:10px 0 2px;`
          + `text-transform:uppercase;letter-spacing:.04em">${escHtml(label)}</div>`;
    html += rows.map(rowHtmlFn).join('');
  }
  return html;
}

let _contextEditorDirty = false;
let _contextModalOpener = null;
// True once the user types in the Context ID field directly - from then on the
// ID stops following the name so a hand-chosen ID is never overwritten.
let _contextIdEdited = false;

async function openContextManager() {
  _contextModalOpener = document.activeElement;
  document.getElementById('context-modal').classList.add('visible');
  document.getElementById('context-editor').style.display = 'none';
  await _refreshContextList();
  setTimeout(() => document.querySelector('#context-modal .btn.primary')?.focus(), 50);
}

function closeContextManager() {
  if (!document.getElementById('context-modal').classList.contains('visible')) return;
  const editor = document.getElementById('context-editor');
  if (editor && editor.style.display !== 'none' && _contextEditorDirty) {
    showConfirm(
      'Discard changes?',
      'You have unsaved changes in the context editor. Close without saving?',
      'Discard',
      () => { _contextEditorDirty = false; _doCloseContextManager(); },
      true,
    );
    return;
  }
  _doCloseContextManager();
}

function _doCloseContextManager() {
  document.getElementById('context-modal').classList.remove('visible');
  const opener = _contextModalOpener;
  _contextModalOpener = null;
  if (opener?.focus) opener.focus();
}

async function _refreshContextList() {
  AppState.contexts = await fetch('/api/contexts').then(r => r.json()).catch(() => []);
  const el = document.getElementById('context-list-items');
  if (!AppState.contexts.length) {
    el.innerHTML = '<div style="color:var(--muted);font-size:12px;padding:4px 0">No contexts yet - create one.</div>';
    return;
  }
  el.innerHTML = AppState.contexts.map(c => `
    <button type="button" style="display:flex;align-items:center;gap:6px;padding:7px 10px;border:1px solid var(--border);border-radius:6px;cursor:pointer;background:none;color:var(--text);font:inherit;text-align:left;width:100%"
         data-edit-ctx="${escHtml(c.context_id)}">
      <span style="font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1">${escHtml(c.display_name || c.context_id)}</span>
      ${c.builtin ? '<span style="font-size:10px;color:var(--muted);background:var(--border);border-radius:3px;padding:1px 5px;flex-shrink:0;pointer-events:none" title="Shipped starter content - edit it to fit your game, or use it as a base for a copy">Template</span>' : ''}
    </button>`).join('');
  el.onclick = e => {
    const item = e.target.closest('[data-edit-ctx]');
    if (item) editContext(item.dataset.editCtx);
  };
}

function openNewContext() {
  AppState.editingContextId = null;
  _contextEditorDirty = false;
  _contextIdEdited = false;
  ['ce-context-id','ce-display-name','ce-setting','ce-your-chars','ce-other-chars','ce-notes',
   'ce-weight-funny','ce-weight-dramatic','ce-weight-action'].forEach(id => {
    document.getElementById(id).value = '';
  });
  document.getElementById('ce-context-id').disabled = false;
  document.getElementById('btn-delete-context').style.display = 'none';
  document.getElementById('btn-reset-context').style.display = 'none';
  document.getElementById('btn-duplicate-context').style.display = 'none';
  cancelCharacterEdit();
  _updateCharacterSectionVisibility();
  document.getElementById('context-editor').style.display = 'flex';
  document.getElementById('ce-display-name').focus();
}

function editContext(context_id) {
  const ctx = AppState.contexts.find(c => c.context_id === context_id);
  if (!ctx) return;
  AppState.editingContextId = context_id;
  _contextEditorDirty = false;
  document.getElementById('ce-context-id').value            = ctx.context_id;
  document.getElementById('ce-context-id').disabled         = true;
  document.getElementById('ce-display-name').value    = ctx.display_name || '';
  document.getElementById('ce-setting').value         = ctx.setting || '';
  document.getElementById('ce-your-chars').value      = ctx.your_characters || '';
  document.getElementById('ce-other-chars').value     = ctx.other_characters || '';
  document.getElementById('ce-notes').value           = ctx.notes || '';
  document.getElementById('ce-weight-funny').value    = ctx.score_funny_weight    != null ? ctx.score_funny_weight    : '';
  document.getElementById('ce-weight-dramatic').value = ctx.score_dramatic_weight != null ? ctx.score_dramatic_weight : '';
  document.getElementById('ce-weight-action').value   = ctx.score_action_weight   != null ? ctx.score_action_weight   : '';
  // Templates are editable content, but only user-created contexts can be
  // deleted; templates get restore-safe actions instead (reset + duplicate).
  document.getElementById('btn-delete-context').style.display    = ctx.builtin ? 'none' : '';
  document.getElementById('btn-reset-context').style.display     = ctx.builtin ? '' : 'none';
  document.getElementById('btn-duplicate-context').style.display = ctx.builtin ? '' : 'none';
  cancelCharacterEdit();
  _updateCharacterSectionVisibility();
  _loadCharacters(context_id);
  document.getElementById('context-editor').style.display = 'flex';
}

function cancelContextEdit() {
  _contextEditorDirty = false;
  document.getElementById('context-editor').style.display = 'none';
}

// Keeps whatever is currently in the editor (including unsaved edits) and turns
// it into a new, unsaved context - the "tailor a template without losing it" path.
function duplicateContext() {
  const baseName = document.getElementById('ce-display-name').value.trim();
  const copyName = baseName ? `${baseName} copy` : '';
  AppState.editingContextId = null;
  _contextIdEdited = false;
  document.getElementById('ce-display-name').value  = copyName;
  document.getElementById('ce-context-id').disabled = false;
  document.getElementById('ce-context-id').value    = _deriveContextId(copyName);
  document.getElementById('btn-delete-context').style.display    = 'none';
  document.getElementById('btn-reset-context').style.display     = 'none';
  document.getElementById('btn-duplicate-context').style.display = 'none';
  cancelCharacterEdit();
  _updateCharacterSectionVisibility();
  _contextEditorDirty = true;
  document.getElementById('ce-display-name').focus();
}

function resetContextToTemplate() {
  if (!AppState.editingContextId) return;
  const ctx  = AppState.contexts.find(c => c.context_id === AppState.editingContextId);
  const name = ctx ? ctx.display_name : AppState.editingContextId;
  showConfirm(
    'Reset to template?',
    `Replace <strong>${escHtml(name)}</strong> with the original shipped content? Your edits to it will be lost.`,
    'Reset',
    _doResetContext,
    true,
  );
}

async function _doResetContext() {
  const res = await fetch(`/api/contexts/${encodeURIComponent(AppState.editingContextId)}/reset`, {method: 'POST'});
  if (!res.ok) {
    const e = await res.json().catch(() => ({}));
    showToast(formatApiError(e) || 'Reset failed', 'error');
    return;
  }
  _contextEditorDirty = false;
  await _refreshContextList();
  editContext(AppState.editingContextId);
  showToast('Template restored');
}

function _deriveContextId(name) {
  return name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60);
}

async function saveContext() {
  const context_id  = AppState.editingContextId || document.getElementById('ce-context-id').value.trim();
  const displayName = document.getElementById('ce-display-name').value.trim();
  if (!context_id)  { showToast('Context ID is required', 'warning'); return; }
  if (!displayName) { showToast('Display name is required', 'warning'); return; }
  const res = await fetch('/api/contexts', {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({
      context_id, display_name: displayName,
      setting:               document.getElementById('ce-setting').value,
      your_characters:       document.getElementById('ce-your-chars').value,
      other_characters:      document.getElementById('ce-other-chars').value,
      notes:                 document.getElementById('ce-notes').value,
      score_funny_weight:    _parseWeight('ce-weight-funny'),
      score_dramatic_weight: _parseWeight('ce-weight-dramatic'),
      score_action_weight:   _parseWeight('ce-weight-action'),
    }),
  });
  if (!res.ok) {
    const e = await res.json().catch(() => ({}));
    showToast(formatApiError(e) || 'Save failed', 'error');
    return;
  }
  _contextEditorDirty = false;
  document.getElementById('context-editor').style.display = 'none';
  await _refreshContextList();
  showToast(`Context "${displayName}" saved`);
}

function deleteContext() {
  if (!AppState.editingContextId) return;
  const ctx  = AppState.contexts.find(c => c.context_id === AppState.editingContextId);
  const name = ctx ? ctx.display_name : AppState.editingContextId;
  showConfirm(
    'Delete context?',
    `Delete context <strong>${escHtml(name)}</strong>?<br><br>` +
    `Recordings already assigned to it will keep the Context ID - you can re-create the context to restore it.`,
    'Delete',
    () => _doDeleteContext(name),
    true,
  );
}

async function _doDeleteContext(name) {
  const res = await fetch(`/api/contexts/${encodeURIComponent(AppState.editingContextId)}`, {method: 'DELETE'});
  if (!res.ok) {
    const e = await res.json().catch(() => ({}));
    showToast(formatApiError(e) || 'Delete failed', 'error');
    return;
  }
  document.getElementById('context-editor').style.display = 'none';
  await _refreshContextList();
  showToast(`Context "${name}" deleted`);
}

// ── characters (structured, per-context lore + score boost) ───────────────────
// Characters are a DB-backed overlay keyed to this context by slug. They only exist
// for a SAVED context (a slug the API knows), so the section shows a "save first" note
// while editing an unsaved/new context. Each save/delete hits the API immediately -
// independent of the context field save - so edits here never touch _contextEditorDirty.
let _currentCharacters = [];
let _editingCharacterId = null;

function _boostPct(boost) { return Math.round((boost || 0) * 100) + '%'; }

function _updateCharBoostLabel() {
  document.getElementById('ce-char-boost-label').textContent =
    _boostPct(parseFloat(document.getElementById('ce-char-boost').value));
}

function _updateCharacterSectionVisibility() {
  const saved = !!AppState.editingContextId;
  document.getElementById('ce-characters-note').style.display = saved ? 'none' : '';
  document.getElementById('ce-characters-list').style.display = saved ? 'flex' : 'none';
  document.getElementById('ce-add-character-btn').style.display = saved ? '' : 'none';
  if (!saved) document.getElementById('ce-character-form').style.display = 'none';
}

async function _loadCharacters(slug) {
  _currentCharacters = await fetch(`/api/contexts/${encodeURIComponent(slug)}/characters`)
    .then(r => r.json()).catch(() => []);
  _renderCharacterList();
}

function _renderCharacterList() {
  const el = document.getElementById('ce-characters-list');
  if (!_currentCharacters.length) {
    el.innerHTML = '<div style="color:var(--muted);font-size:12px">No characters yet.</div>';
    return;
  }
  el.innerHTML = _currentCharacters.map(c => `
    <div style="display:flex;align-items:center;gap:8px;border:1px solid var(--border);border-radius:6px;padding:6px 10px">
      <span style="flex:1;font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escHtml(c.name)}</span>
      ${c.score_boost > 0 ? `<span style="font-size:11px;color:var(--muted)" title="Scoring boost fed to the LLM">boost ${_boostPct(c.score_boost)}</span>` : ''}
      <button type="button" class="btn" style="padding:2px 8px;font-size:12px" data-edit-char="${c.id}">Edit</button>
      <button type="button" class="btn danger" style="padding:2px 8px;font-size:12px" data-del-char="${c.id}">Remove</button>
    </div>`).join('');
  el.onclick = e => {
    const edit = e.target.closest('[data-edit-char]');
    const del  = e.target.closest('[data-del-char]');
    if (edit) openCharacterForm(parseInt(edit.dataset.editChar, 10));
    else if (del) deleteCharacter(parseInt(del.dataset.delChar, 10));
  };
}

function openCharacterForm(charId = null) {
  _editingCharacterId = charId;
  const char = charId != null ? _currentCharacters.find(c => c.id === charId) : null;
  document.getElementById('ce-char-name').value  = char ? char.name : '';
  document.getElementById('ce-char-lore').value  = char ? (char.lore || '') : '';
  document.getElementById('ce-char-boost').value = char ? (char.score_boost || 0) : 0;
  _updateCharBoostLabel();
  document.getElementById('ce-character-form').style.display = 'flex';
  document.getElementById('ce-add-character-btn').style.display = 'none';
  document.getElementById('ce-char-name').focus();
}

function cancelCharacterEdit() {
  _editingCharacterId = null;
  document.getElementById('ce-character-form').style.display = 'none';
  document.getElementById('ce-add-character-btn').style.display = '';
}

async function saveCharacter() {
  const slug = AppState.editingContextId;
  if (!slug) return;
  const name = document.getElementById('ce-char-name').value.trim();
  if (!name) { showToast('Character name is required', 'warning'); return; }
  const payload = {
    name,
    lore: document.getElementById('ce-char-lore').value,
    score_boost: parseFloat(document.getElementById('ce-char-boost').value) || 0,
  };
  const url = _editingCharacterId != null
    ? `/api/characters/${_editingCharacterId}`
    : `/api/contexts/${encodeURIComponent(slug)}/characters`;
  const res = await fetch(url, {
    method: _editingCharacterId != null ? 'PUT' : 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify(payload),
  });
  if (!res.ok) {
    const e = await res.json().catch(() => ({}));
    showToast(formatApiError(e) || 'Save failed', 'error');
    return;
  }
  cancelCharacterEdit();
  await _loadCharacters(slug);
  showToast(`Character "${name}" saved`);
}

function deleteCharacter(charId) {
  const char = _currentCharacters.find(c => c.id === charId);
  if (!char) return;
  showConfirm(
    'Remove character?',
    `Remove <strong>${escHtml(char.name)}</strong>? Any Person linked to it will be unlinked - their name and voice are not affected.`,
    'Remove',
    async () => {
      const res = await fetch(`/api/characters/${charId}`, {method: 'DELETE'});
      if (!res.ok) {
        const e = await res.json().catch(() => ({}));
        showToast(formatApiError(e) || 'Remove failed', 'error');
        return;
      }
      await _loadCharacters(AppState.editingContextId);
      showToast(`Character "${char.name}" removed`);
    },
    true,
  );
}

// ── video context assignment ──────────────────────────────────────────────────
async function addVideoContext(videoId, context_id) {
  if (!context_id) return;
  const video   = AppState.videos.find(v => v.id === videoId);
  const current = video ? [...(video.context_names || [])] : [];
  if (!current.includes(context_id)) current.push(context_id);
  await _saveVideoContexts(videoId, current);
}

async function removeVideoContext(videoId, context_id) {
  const video   = AppState.videos.find(v => v.id === videoId);
  const current = (video ? video.context_names || [] : []).filter(s => s !== context_id);
  await _saveVideoContexts(videoId, current);
}

async function _saveVideoContexts(videoId, context_ids) {
  const res = await fetch(`/api/videos/${videoId}/contexts`, {
    method: 'PATCH', headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({context_names: context_ids}),
  });
  if (!res.ok) { showToast('Failed to update contexts', 'error'); return; }
  const video = AppState.videos.find(v => v.id === videoId);
  if (video) {
    video.context_names = context_ids;
    if (AppState.activeVideoId === videoId) renderVideoDetail(video, null);
  }
}

// Global delegation for chip × buttons in the detail panel
document.addEventListener('click', e => {
  const rmBtn = e.target.closest('[data-rmctx]');
  if (rmBtn && AppState.activeVideoId) removeVideoContext(AppState.activeVideoId, rmBtn.dataset.rmctx);
});

// ── re-score mode picker (LLM-only vs full) ───────────────────────────────────
// Shared markup + reader so the per-recording dialog and the per-clip chooser
// offer the identical choice. "LLM only" (default) keeps the on-screen activity
// and laughter scores from the last analysis; "Full" recomputes every score.
function _rescoreModeRadios() {
  return `<div style="margin-top:12px;font-size:13px">
    <div style="margin-bottom:6px;color:var(--muted)">Re-score:</div>
    <label style="display:flex;align-items:center;gap:6px;margin-bottom:4px">
      <input type="radio" name="rescore-mode" value="llm" checked>
      LLM only - keep on-screen activity &amp; laughter scores
    </label>
    <label style="display:flex;align-items:center;gap:6px">
      <input type="radio" name="rescore-mode" value="full">
      Full - recompute every score
    </label>
  </div>`;
}

function _readRescoreMode() {
  const picked = document.querySelector('input[name="rescore-mode"]:checked');
  return !!picked && picked.value === 'full';
}

// ── re-score clips with context ───────────────────────────────────────────────
async function rescoreClips(videoId, btn) {
  const video = AppState.videos.find(v => v.id === videoId);
  const count = video ? video.clip_count : 0;
  let cap = {vision: false};
  try { cap = await fetch('/api/llm/capabilities').then(r => r.json()); } catch { /* offline */ }
  const framesRow = (window._visionEnabled && cap.vision)
    ? `<label style="display:flex;align-items:center;gap:6px;margin-top:10px;font-size:13px">
         <input type="checkbox" id="rescore-include-frames"> Include frame analysis (slower)
       </label>`
    : '';
  showConfirm(
    'Re-score clips with context?',
    `This will run LLM scoring on <strong>${plural(count, 'clip')}</strong>.<br>` +
    `GPU time varies with clip count - this may take several minutes.` + framesRow +
    _rescoreModeRadios(),
    'Re-score',
    () => {
      const inc = document.getElementById('rescore-include-frames');
      _doRescoreClips(videoId, btn, 'rescore-clips', !!(inc && inc.checked), _readRescoreMode());
    },
  );
}

function rescoreFailedClips(videoId, btn) {
  const video = AppState.videos.find(v => v.id === videoId);
  const count = video ? (video.clips_llm_error || 0) : 0;
  showConfirm(
    'Re-score failed clips?',
    `This will re-run LLM scoring only on the <strong>${plural(count, 'clip')}</strong> ` +
    `that failed last time. Successfully scored clips are left untouched.`,
    'Re-score',
    () => _doRescoreClips(videoId, btn, 'rescore-failed-clips'),
  );
}

function _doRescoreClips(videoId, btn, endpoint = 'rescore-clips', includeFrames = false, full = false) {
  if (_blockedByAnalyze('re-score clips')) return;
  const orig = btn?.textContent;
  if (btn) { btn.disabled = true; btn.textContent = 'Re-scoring…'; }
  openLog();
  _supersedeActiveStream();
  const resetBtn = () => { if (btn) { btn.disabled = false; btn.textContent = orig; } };
  let errorCount = 0;
  const params = new URLSearchParams();
  if (includeFrames) params.set('include_frames', '1');
  if (full) params.set('full', '1');
  const qs = params.toString();
  const handle = _openSSE(
    `/api/videos/${videoId}/${endpoint}${qs ? '?' + qs : ''}`,
    data => {
      if (typeof data === 'string' && data.startsWith('[Error')) errorCount++;
      appendLog(String(data));
    },
    () => {
      _clearActiveStream(handle);
      resetBtn();
      if (errorCount > 0) {
        showToast(`Re-scoring finished - ${plural(errorCount, 'clip')} failed (check log)`, 'error');
        SoundFx.play('error');
      } else {
        showToast('Re-scoring complete');
        SoundFx.play('rescore');
      }
      loadVideos().then(() => {
        if (AppState.activeVideoId === videoId) {
          const v = AppState.videos.find(v => v.id === videoId);
          if (v) renderVideoDetail(v, null);
          fetch(_clipsListUrl(videoId)).then(r => r.json()).then(clips => {
            AppState.clips = clips; _renderClips();
          });
        }
      });
    },
    errMsg => {
      _clearActiveStream(handle);
      resetBtn();
      showToast(`Re-scoring failed - ${errMsg}`, 'error');
      SoundFx.play('error');
    },
  );
  _setActiveStream(handle, resetBtn);
}

function rescoreAllClips(videoId, btn) {
  const video = AppState.videos.find(v => v.id === videoId);
  const count = video ? video.clip_count : 0;
  const hasContext = video && video.context_names && video.context_names.length > 0;
  const contextWarn = hasContext ? '' :
    `<div style="margin-top:8px;padding:6px 10px;background:color-mix(in srgb, var(--warning) 10%, transparent);border-left:3px solid var(--warning);border-radius:3px;font-size:12px">` +
    `No world context assigned - descriptions will be generic.</div>`;
  showConfirm(
    'Re-score all clips?',
    `Re-run LLM scoring on all <strong>${plural(count, 'clip')}</strong>. ` +
    `Scores and descriptions will be overwritten. This cannot be undone.` +
    contextWarn +
    _rescoreModeRadios() +
    `<div style="margin-top:8px;font-size:12px;color:var(--muted)">This may take several minutes.</div>`,
    'Re-score All',
    () => _doRescoreClips(videoId, btn, 'rescore-clips', false, _readRescoreMode()),
    true,
  );
}

function redescribeAllClips(videoId, btn) {
  const video = AppState.videos.find(v => v.id === videoId);
  const count = video ? video.clip_count : 0;
  const hasContext = video && video.context_names && video.context_names.length > 0;
  const contextWarn = hasContext ? '' :
    `<div style="margin-top:8px;padding:6px 10px;background:color-mix(in srgb, var(--warning) 10%, transparent);border-left:3px solid var(--warning);border-radius:3px;font-size:12px">` +
    `No world context assigned - descriptions will be generic.</div>`;
  showConfirm(
    'Re-describe all clips?',
    `Regenerate LLM descriptions for all <strong>${plural(count, 'clip')}</strong>. ` +
    `Scores will not change. Manually edited descriptions are preserved.` +
    contextWarn +
    `<div style="margin-top:8px;font-size:12px;color:var(--muted)">This may take several minutes.</div>`,
    'Re-describe All',
    () => _doRedescribeClips(videoId, btn),
    true,
  );
}

function _doRedescribeClips(videoId, btn) {
  if (_blockedByAnalyze('re-describe clips')) return;
  const orig = btn?.textContent;
  if (btn) { btn.disabled = true; btn.textContent = 'Re-describing…'; }
  openLog();
  _supersedeActiveStream();
  const resetBtn = () => { if (btn) { btn.disabled = false; btn.textContent = orig; } };
  let errorCount = 0;
  const handle = _openSSE(
    `/api/videos/${videoId}/redescribe-clips`,
    data => {
      if (typeof data === 'string' && data.startsWith('[Error')) errorCount++;
      appendLog(String(data));
    },
    () => {
      _clearActiveStream(handle);
      resetBtn();
      if (errorCount > 0) {
        showToast(`Re-describe finished - ${plural(errorCount, 'clip')} failed (check log)`, 'error');
      } else {
        showToast('Descriptions regenerated');
      }
      if (AppState.activeVideoId === videoId) {
        fetch(_clipsListUrl(videoId))
          .then(r => r.json())
          .then(clips => {
            AppState.clips = clips;
            _renderClips();
            if (AppState.activeClipId) selectClip(AppState.activeClipId);
          });
      }
    },
    errMsg => {
      _clearActiveStream(handle);
      resetBtn();
      showToast(`Re-describe failed - ${errMsg}`, 'error');
    },
  );
  _setActiveStream(handle, resetBtn);
}

// ── reset approvals ───────────────────────────────────────────────────────────
function resetApprovals(videoId) {
  const nonPending = AppState.clips.filter(c => c.status !== 'pending').length;
  if (!nonPending) { showToast('All clips are already Unreviewed', 'info'); return; }
  showConfirm(
    'Reset all approvals?',
    `Reset <strong>${plural(nonPending, 'clip')}</strong> back to Unreviewed for this recording. This cannot be undone.`,
    'Reset',
    () => _doResetApprovals(videoId),
    true,
  );
}

async function _doResetApprovals(videoId) {
  const res = await fetch(`/api/videos/${videoId}/reset-approvals`, {method: 'POST'});
  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    showToast(`Failed to reset approvals: ${formatApiError(err)}`, 'error');
    return;
  }
  const data = await res.json();
  AppState.clips = await fetch(_clipsListUrl(videoId)).then(r => r.json());
  _renderClips();
  showToast(`Reset ${plural(data.reset, 'clip')} to Unreviewed`);
}

// ── auto-approve ──────────────────────────────────────────────────────────────
let _autoApproveVideoId = null;
let _autoApproveOpener = null;

const _AUTO_APPROVE_FIELD_MAP = {
  overall:  'score_overall',
  funny:    'score_funny',
  dramatic: 'score_dramatic',
  action:   'score_action',
};

function openAutoApproveModal(videoId) {
  _autoApproveOpener = document.activeElement;
  _autoApproveVideoId = videoId;
  document.getElementById('auto-approve-slider').value = 0.6;
  document.getElementById('auto-approve-field').value = 'overall';
  updateAutoApprovePreview();
  document.getElementById('auto-approve-modal').classList.add('visible');
  setTimeout(() => document.getElementById('auto-approve-slider')?.focus(), 50);
}

function closeAutoApproveModal() {
  document.getElementById('auto-approve-modal').classList.remove('visible');
  const opener = _autoApproveOpener;
  _autoApproveOpener = null;
  if (opener?.focus) opener.focus();
}

function updateAutoApprovePreview() {
  const threshold = parseFloat(document.getElementById('auto-approve-slider').value);
  const field = document.getElementById('auto-approve-field').value;
  document.getElementById('auto-approve-threshold-label').textContent = Math.round(threshold*100) + '%';
  const scoreKey = _AUTO_APPROVE_FIELD_MAP[field] || 'score_overall';
  const pending = AppState.clips.filter(c => c.status === 'pending');
  const eligible = pending.filter(c => (c[scoreKey] || 0) >= threshold);
  const el = document.getElementById('auto-approve-preview');
  if (pending.length === 0) {
    el.textContent = 'No unreviewed clips.';
    document.getElementById('auto-approve-ok').disabled = true;
  } else if (eligible.length === 0) {
    el.textContent = `No unreviewed clips meet this threshold (${pending.length} unreviewed total).`;
    document.getElementById('auto-approve-ok').disabled = true;
  } else {
    el.textContent = `${eligible.length} of ${plural(pending.length, 'unreviewed clip')} will be approved.`;
    document.getElementById('auto-approve-ok').disabled = false;
  }
}

async function doAutoApprove() {
  const threshold = parseFloat(document.getElementById('auto-approve-slider').value);
  const score_field = document.getElementById('auto-approve-field').value;
  const videoId = _autoApproveVideoId;
  closeAutoApproveModal();
  const res = await fetch(`/api/videos/${videoId}/auto-approve`, {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({threshold, score_field}),
  });
  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    showToast(`Auto-approve failed: ${formatApiError(err)}`, 'error');
    return;
  }
  const data = await res.json();
  AppState.clips = await fetch(_clipsListUrl(videoId)).then(r => r.json());
  _renderClips();
  showToast(`Approved ${plural(data.approved, 'clip')}`);
}

// ── retranscribe ──────────────────────────────────────────────────────────────
let _retranscribeClipId = null;
let _retranscribeOpener = null;

async function _loadRetranscribeSpeakerDefault() {
  const box  = document.getElementById('retranscribe-speaker-labels');
  const note = document.getElementById('retranscribe-speaker-note');
  const readiness = await _diarizationReadiness();
  box.disabled = !readiness.ready;
  box.checked  = readiness.ready;  // on by default when fully set up
  if (!readiness.ready) {
    note.innerHTML = _diarizationNoteHtml(readiness.reason, 'closeRetranscribeModal();openSettings()');
  } else {
    note.textContent = '';
  }
}

function openRetranscribeModal(clipId) {
  _retranscribeOpener = document.activeElement;
  _retranscribeClipId = clipId;
  _loadRetranscribeSpeakerDefault();
  document.getElementById('retranscribe-modal').classList.add('visible');
  setTimeout(() => document.getElementById('retranscribe-model')?.focus(), 50);
}

function closeRetranscribeModal() {
  document.getElementById('retranscribe-modal').classList.remove('visible');
  const opener = _retranscribeOpener;
  _retranscribeOpener = null;
  if (opener?.focus) opener.focus();
}

function startRetranscribe() {
  if (!_retranscribeClipId) return;
  const model = document.getElementById('retranscribe-model').value;
  const speakerLabels = document.getElementById('retranscribe-speaker-labels').checked;
  closeRetranscribeModal();
  openLog();
  streamSSE(
    `/api/clips/${_retranscribeClipId}/retranscribe?model=${encodeURIComponent(model)}&speaker_labels=${speakerLabels}`,
    () => { selectClip(_retranscribeClipId); showToast('Retranscription complete'); },
    [{label: 'Transcribe', patterns: ['Retranscribing', 'OK']}],
    'Retranscribing',
  );
}

// ── re-score individual clip ──────────────────────────────────────────────────
// Offer the LLM-only vs full choice before running (kebab "Re-score"). The
// contextual quick actions (edited-captions note, manual clip creation) call
// rescoreClip directly and stay LLM-only.
function rescoreClipChoose(clipId) {
  showConfirm(
    'Re-score clip?',
    _rescoreModeRadios(),
    'Re-score',
    () => rescoreClip(clipId, _readRescoreMode()),
  );
}

function rescoreClip(clipId, full = false) {
  if (_blockedByAnalyze('re-score a clip')) return;
  _supersedeActiveStream();
  openLog();
  startJobUI(SCORE_STEPS, 'Re-scoring clip');
  const teardown = () => endJobUI();
  let hadError = false;
  const handle = _openSSE(
    `/api/clips/${clipId}/rescore${full ? '?full=1' : ''}`,
    msg => {
      updateJobUI(typeof msg === 'string' ? msg : JSON.stringify(msg));
      if (typeof msg === 'string' && msg.startsWith('[Error')) hadError = true;
      appendLog(String(msg));
    },
    async msg => {
      _clearActiveStream(handle);
      teardown();
      if (hadError) {
        showToast('Re-score failed - check log for details', 'error');
        SoundFx.play('error');
        selectClip(clipId);
        return;
      }
      const clip = await fetch(`/api/clips/${clipId}`).then(r => r.json()).catch(() => null);
      const descNew     = msg.description_new;
      const descLongNew = msg.description_long_new;
      if (descNew || descLongNew) {
        openDiffModal('Review Re-scored Descriptions', [
          {label: 'Description',       current: clip?.description_original      || clip?.description      || '', proposed: descNew     || ''},
          {label: 'Description (long)', current: clip?.description_long_original || clip?.description_long || '', proposed: descLongNew || ''},
        ], async (action, edited) => {
          await fetch(`/api/clips/${clipId}/fields`, {
            method: 'PATCH', headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({action, field: 'both', new_description: edited[0], new_description_long: edited[1]}),
          });
          selectClip(clipId);
        });
      } else {
        selectClip(clipId);
      }
      showToast('Clip re-scored');
      SoundFx.play('rescore');
    },
    errMsg => {
      _clearActiveStream(handle);
      teardown();
      showToast(`Re-score failed - ${errMsg}`, 'error');
      SoundFx.play('error');
    },
  );
  _setActiveStream(handle, teardown);
}

document.addEventListener('DOMContentLoaded', () => {
  const editor = document.getElementById('context-editor');
  if (editor) {
    // The Characters section saves independently via its own API calls, so typing
    // there must not flip the context-field dirty flag (it would wrongly prompt
    // "Discard changes?" on close). Everything else in the editor is dirty-tracked.
    const fromChars = e => !!e.target.closest('#ce-characters-section');
    editor.addEventListener('input',  e => { if (!fromChars(e)) _contextEditorDirty = true; });
    editor.addEventListener('change', e => { if (!fromChars(e)) _contextEditorDirty = true; });
  }
  const nameInput = document.getElementById('ce-display-name');
  const idInput   = document.getElementById('ce-context-id');
  if (nameInput && idInput) {
    nameInput.addEventListener('input', () => {
      if (!idInput.disabled && !_contextIdEdited) idInput.value = _deriveContextId(nameInput.value);
    });
    idInput.addEventListener('input', () => { _contextIdEdited = true; });
  }
});

// Public API - symbols referenced cross-module, by an inline handler, or by a
// test. Internal helpers above stay private to this module's closure.
Object.assign(window, {
  _loadContexts, ensureContexts, _parseWeight,
  _termContextOptions, _renderTermGroups,
  openContextManager, closeContextManager, openNewContext,
  saveContext, deleteContext, cancelContextEdit,
  duplicateContext, resetContextToTemplate, _deriveContextId,
  openCharacterForm, cancelCharacterEdit, saveCharacter, deleteCharacter,
  _updateCharBoostLabel, _updateCharacterSectionVisibility, _loadCharacters,
  addVideoContext,
  openAutoApproveModal, closeAutoApproveModal, doAutoApprove, updateAutoApprovePreview,
  openRetranscribeModal, closeRetranscribeModal, startRetranscribe,
  rescoreClip, rescoreClipChoose, rescoreClips, rescoreFailedClips, rescoreAllClips, redescribeAllClips, resetApprovals,
});
})();

//# sourceURL=settings.js
(function () {
// Feature-map - Settings panel (all sections; see the per-section banners below).
//   API: routes/config.py, llm.py, profiles.py, content_presets.py, export_presets.py · Tests: tests/ui/test_ui_settings.py
// ── settings panel ────────────────────────────────────────────────────────────
const _settingsFieldIds = [
  's-whisper-model','s-whisper-device','s-whisper-compute','s-whisper-language',
  's-ai-privacy-value',
  's-llm-enabled','s-llm-model-path','s-llm-vision-model-path','s-llm-mmproj-path','s-llm-use-gpu',
  's-vision-enabled','s-vision-frames',
  's-visual-auto-vision','s-visual-vision-topn',
  's-diarization-backend','s-speaker-match-threshold','s-speaker-cluster-threshold',
  's-project-voice-match-threshold',
  's-similarity-backend',
  's-energy-weight','s-scene-weight','s-llm-weight',
  's-laugh-weight','s-laugh-mode','s-laugh-model-id','s-lexicon-weight',
  's-speech-rate-weight','s-churn-weight','s-prosody-weight',
  's-funny-weight','s-dramatic-weight','s-action-weight','s-visual-weight',
  's-scene-mode','s-energy-mode','s-silence-ms','s-min-clip-ms','s-scene-generation',
  's-thermal-autopause','s-thermal-warn-c','s-thermal-pause-c',
  's-audio-event-enabled',
  's-timeline-interval','s-timeline-unit','s-autoplay','s-play-next','s-loop-clip','s-playback-rate',
  's-export-name-template',
  's-title-card-bg-color','s-title-card-font-color','s-title-card-scale',
  's-title-card-template','s-title-card-duration',
  's-caption-font-name','s-caption-font-size','s-caption-position',
  's-caption-word-highlight','s-caption-chunk-size',
];
// [element id, config key, default] - single source for apply + Reset to defaults.
const _weightFields = [
  ['s-energy-weight',   'scorer_energy_weight',   1.0],
  ['s-scene-weight',    'scorer_scene_weight',    0.5],
  ['s-llm-weight',      'scorer_llm_weight',      2.0],
  ['s-laugh-weight',    'scorer_laugh_weight',    1.5],
  ['s-lexicon-weight',  'scorer_lexicon_weight',  1.0],
  ['s-speech-rate-weight', 'scorer_speech_rate_weight', 0.5],
  ['s-churn-weight',       'scorer_churn_weight',       0.5],
  ['s-prosody-weight',     'scorer_prosody_weight',     0.5],
  ['s-audio-event-weight', 'scorer_audio_event_weight', 1.0],
  ['s-funny-weight',    'score_funny_weight',     1.0],
  ['s-dramatic-weight', 'score_dramatic_weight',  1.0],
  ['s-action-weight',   'score_action_weight',    1.0],
  ['s-visual-weight',   'score_visual_weight',    0.5],
];
let _settingsOriginal = {};
let _settingsOpener = null;

function _snapshotSettings() {
  _settingsOriginal = {};
  for (const id of _settingsFieldIds) {
    const el = document.getElementById(id);
    if (el) _settingsOriginal[id] = el.type === 'checkbox' ? el.checked : el.value;
  }
}

function _checkSettingsDirty() {
  let anyDirty = false;
  for (const id of _settingsFieldIds) {
    const el = document.getElementById(id);
    if (!el) continue;
    const current = el.type === 'checkbox' ? el.checked : el.value;
    const dirty = String(current) !== String(_settingsOriginal[id]);
    if (dirty) anyDirty = true;
    const row = el.closest('.settings-row') || el.closest('.settings-weight-row');
    if (row) row.classList.toggle('dirty', dirty);
  }
  if (window._soundSettingsDirty?.()) anyDirty = true;
  const btn = document.getElementById('btn-settings-save');
  if (btn) btn.disabled = !anyDirty;
}

function _scrollToSettingsSection(sectionId) {
  const panel = document.getElementById('settings-panel');
  const section = document.getElementById(sectionId);
  if (!section) return;
  const headerHeight = panel.querySelector('.settings-header')?.offsetHeight ?? 0;
  const smooth = !window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  panel.scrollTo({ top: section.offsetTop - headerHeight - 10, behavior: smooth ? 'smooth' : 'auto' });
}

async function openSettings() {
  _settingsOpener = document.activeElement;
  // Close the new-recording panel so it isn't left open behind the overlay.
  if (typeof _isNewRecordingPanelOpen === 'function' && _isNewRecordingPanelOpen()) {
    _doCloseNewRecordingPanel();
  }
  const panel = document.getElementById('settings-panel');
  panel.classList.add('visible');
  try {
    const cfg = await fetch('/api/config').then(r => r.json());
    await _ensureDefaults();  // so the Reset controls work without a per-click fetch
    await _ensureWhisperLanguageOptions();
    // Load the model catalog before _applySettingsToUI so the recommended-model
    // cards and the "currently using" summary reflect the saved active model.
    await _ensureModelCatalog();
    // Sound rows must be rendered (from saved state) before _applySettingsToUI
    // runs the dirty check, or a discarded prior edit would re-enable Save.
    await initSoundSettings();
    await initHotwordSettings();
    await initSensitiveTermSettings();
    await initExportPresetSettings();
    await initContentPresetSettings();
    _applySettingsToUI(cfg);
    // preventScroll: the panel should open at the top (showing the Capabilities
    // overview); a plain focus() scrolls this mid-panel control into view, yanking
    // the panel down - visibly so since Wave 4's taller Capabilities section.
    setTimeout(() => document.getElementById('s-whisper-model')?.focus({ preventScroll: true }), 50);
  } catch (e) {
    showToast('Failed to load settings', 'error');
  }
  const pathsEl = document.getElementById('s-paths-display');
  if (pathsEl) {
    const st = await fetch('/api/status').then(r => r.json()).catch(() => ({}));
    pathsEl.innerHTML = [
      ['Project folder', st.project_dir],
      ['Exports folder', st.export_dir],
      ['Database',       st.db_path],
    ].filter(([, v]) => v).map(([label, val]) =>
      `<div><span style="color:var(--text);min-width:130px;display:inline-block">${escHtml(label)}</span><code style="font-size:11px;color:var(--muted)">${escHtml(val)}</code></div>`
    ).join('') || '<div style="color:var(--muted)">Unavailable</div>';
  }
}

function closeSettings(onClosed) {
  if (!document.getElementById('settings-panel').classList.contains('visible')) { onClosed?.(); return; }
  const saveBtn = document.getElementById('btn-settings-save');
  if (saveBtn && !saveBtn.disabled) {
    showConfirm(
      'Discard settings changes?',
      'You have unsaved changes. Close without saving?',
      'Discard',
      () => _doCloseSettings(onClosed),
      true,
    );
    return;
  }
  _doCloseSettings(onClosed);
}

function _doCloseSettings(onClosed) {
  document.getElementById('settings-panel').classList.remove('visible');
  const opener = _settingsOpener;
  _settingsOpener = null;
  if (opener?.focus) opener.focus();
  onClosed?.();
}

// Populate the transcription-language select from the server's allowlist once,
// rendering English display names via Intl so the codes stay single-sourced in
// config.py. Falls back to the markup's Auto-detect-only option on fetch failure.
let _whisperLangsLoaded = false;
async function _ensureWhisperLanguageOptions() {
  if (_whisperLangsLoaded) return;
  const sel = document.getElementById('s-whisper-language');
  if (!sel) return;
  try {
    const { languages } = await fetch('/api/config/whisper-languages').then(r => r.json());
    let nameOf = code => code;
    try {
      const dn = new Intl.DisplayNames(['en'], { type: 'language' });
      nameOf = code => { try { return dn.of(code) || code; } catch { return code; } };
    } catch { /* Intl.DisplayNames unavailable - show raw codes */ }
    const named = languages
      .map(code => ({ code, name: nameOf(code) }))
      .sort((a, b) => a.name.localeCompare(b.name));
    sel.innerHTML = '<option value="">Auto-detect (recommended)</option>' +
      named.map(o => `<option value="${escHtml(o.code)}">${escHtml(o.name)}</option>`).join('');
    _whisperLangsLoaded = true;
  } catch { /* keep Auto-detect-only fallback */ }
}

// Selects whose option values are numeric strings (e.g. "1.0") won't match a
// JSON number reformatted by JS (1.0 -> "1") via plain .value assignment -
// match by parsed value instead so the saved scale selects the right option.
function _setSelectByNumber(id, num) {
  const el = document.getElementById(id);
  if (!el) return;
  const opt = Array.from(el.options).find(o => parseFloat(o.value) === num);
  if (opt) el.value = opt.value;
}

function _setFieldVal(id, val) { const el = document.getElementById(id); if (el) el.value = val; }
// A colour field is enhanced by ColorPicker into a hidden value-store; setting
// its .value alone won't refresh the swatch trigger, so dispatch input (which the
// picker listens for, and which re-runs the title-card preview via oninput).
function _setColorField(id, val) {
  const el = document.getElementById(id);
  if (!el) return;
  el.value = val;
  el.dispatchEvent(new Event('input', { bubbles: true }));
}
function _setFieldChk(id, val) { const el = document.getElementById(id); if (el) el.checked = val; }
function _setFieldTxt(id, val) { const el = document.getElementById(id); if (el) el.textContent = val; }

// Per-section field appliers - the single source for rendering a config into
// each section's controls, shared by the initial load (_applySettingsToUI) and
// the per-section / whole-panel "Reset to defaults" controls (revertSection).
// The `?? default` fallbacks handle a partial/legacy saved config on load;
// reverts pass a complete factory config from /api/config/defaults.
function _applySttFields(cfg) {
  _setFieldVal('s-whisper-model',  cfg.whisper_model   || 'base');
  _setFieldVal('s-whisper-device', cfg.whisper_device  || 'auto');
  _setFieldVal('s-whisper-compute',cfg.whisper_compute_type || 'int8');
  _setFieldVal('s-whisper-language', cfg.whisper_language || '');
}

function _applyLlmFields(cfg) {
  _setFieldChk('s-llm-enabled',  cfg.llm_enabled   !== false);
  _onLlmEnabledChange(cfg.llm_enabled !== false);
  _setFieldVal('s-llm-model-path', cfg.llm_model_path  || '');
  _setFieldVal('s-llm-vision-model-path', cfg.llm_vision_model_path || '');
  _setFieldVal('s-llm-mmproj-path', cfg.llm_mmproj_path || '');
  _setFieldChk('s-llm-use-gpu', cfg.llm_use_gpu !== false);
  _setFieldChk('s-vision-enabled', cfg.vision_enabled === true);
  _setFieldVal('s-vision-frames',  cfg.vision_frames_per_clip ?? 2);
  window._visionEnabled = cfg.vision_enabled === true;
  _setFieldChk('s-visual-auto-vision', cfg.visual_auto_vision_enabled === true);
  _setFieldVal('s-visual-vision-topn', cfg.visual_vision_topn ?? 8);
  _setFieldVal('s-similarity-backend', cfg.similarity_backend || 'embeddings');
  // Applies the privacy mode, which collapses the generative block when "none".
  _setPrivacyMode(cfg.ai_privacy_mode || 'local_only');
  _onSimilarityBackendChange(cfg.similarity_backend || 'embeddings');
  _updateLlmCapabilities();
  _renderCapabilityTiers();
}

function _applySpeakerFields(cfg) {
  const diarBackend = cfg.diarization_backend || 'speechbrain';
  _setFieldVal('s-diarization-backend', diarBackend);
  _onDiarizationBackendChange(diarBackend);
  _setFieldVal('s-speaker-match-threshold', (cfg.speaker_match_threshold ?? 0.75).toFixed(2));
  _setFieldVal('s-speaker-cluster-threshold', (cfg.speaker_cluster_threshold ?? 0.55).toFixed(2));
  _setFieldVal('s-project-voice-match-threshold', (cfg.project_voice_match_threshold ?? 0.80).toFixed(2));
}

function _applyWeightFields(cfg) {
  for (const [id, key, def] of _weightFields) {
    const weight = (cfg[key] ?? def).toFixed(1);
    _setFieldVal(id, weight);
    _setFieldTxt(`${id}-val`, weight);
  }
  _setFieldVal('s-laugh-mode',    cfg.scorer_laugh_mode     || 'transcript');
  _setFieldVal('s-laugh-model-id',cfg.scorer_laugh_model_id || 'MIT/ast-finetuned-audioset-10-10-0.4593');
  _onLaughModeChange(cfg.scorer_laugh_mode || 'transcript');
  _setFieldChk('s-audio-event-enabled', cfg.scorer_audio_event_enabled === true);
}

function _applyAnalysisFields(cfg) {
  _setFieldVal('s-scene-mode',    cfg.scene_detection_mode || 'fast');
  _setFieldVal('s-visual-mode',   cfg.visual_candidate_mode || 'gaps');
  _setFieldVal('s-energy-mode',   cfg.energy_mode          || 'fast');
  _setFieldVal('s-silence-ms',    cfg.silence_threshold_ms ?? 3000);
  _setFieldVal('s-min-clip-ms',   cfg.min_clip_ms          ?? 15000);
  _setFieldChk('s-scene-generation', cfg.scene_generation_enabled === true);
  const silenceEl = document.getElementById('s-silence-ms');
  const minClipEl = document.getElementById('s-min-clip-ms');
  const silenceHint = document.getElementById('s-silence-ms-hint');
  const minClipHint = document.getElementById('s-min-clip-ms-hint');
  if (silenceEl && silenceHint) silenceHint.textContent = (silenceEl.value / 1000).toFixed(1) + ' s';
  if (minClipEl && minClipHint) minClipHint.textContent = (minClipEl.value / 1000).toFixed(1) + ' s';
}

function _applyHardwareFields(cfg) {
  _setFieldChk('s-thermal-autopause', cfg.thermal_autopause_enabled !== false);
  _setFieldVal('s-thermal-warn-c',    cfg.thermal_warn_c  ?? 85);
  _setFieldVal('s-thermal-pause-c',   cfg.thermal_pause_c ?? 90);
}

// Timeline is a saved config field; the playback/theme prefs below it are
// browser-local (localStorage), applied by saveSettings, not the config PATCH.
function _applyUiFields(cfg) {
  const tlUnit = cfg.ui_timeline_interval_unit || 'minutes';
  const tlSec  = cfg.ui_timeline_interval_seconds ?? 900;
  const tlVal  = tlUnit === 'minutes' ? Math.round(tlSec / 60) : tlSec;
  _setFieldVal('s-timeline-interval', tlVal);
  _setFieldVal('s-timeline-unit',     tlUnit);
  _setFieldChk('s-autoplay', localStorage.getItem('yuuclip-autoplay') === 'true');
  _setFieldChk('s-play-next', localStorage.getItem('yuuclip-play-next') === 'true');
  _setFieldChk('s-loop-clip', localStorage.getItem('yuuclip-loop-clip') === 'true');
  _setFieldVal('s-playback-rate', String(playbackRatePref()));
  _setFieldVal('s-theme', localStorage.getItem('yuuclip-theme') || 'dark');
  _setFieldVal('s-accent', localStorage.getItem('yuuclip-accent') || 'default');
}

function _applyExportFields(cfg) {
  _setFieldVal('s-export-name-template', cfg.export_name_template || '{video}_clip{clip_id}_{start}');
  _updateExportNameTemplatePreview();
  _setColorField('s-title-card-bg-color', cfg.title_card_bg_color || '#000000');
  _setColorField('s-title-card-font-color', cfg.title_card_font_color || '#ffffff');
  _setSelectByNumber('s-title-card-scale', cfg.title_card_scale ?? 1.0);
  _setFieldVal('s-title-card-template', cfg.title_card_template ?? '{description}\n{start} · {duration}');
  _setFieldVal('s-title-card-duration', cfg.title_card_duration_s ?? 3.0);
  _updateTitleCardPreview();
  _setFieldVal('s-caption-font-name', cfg.caption_font_name || '');
  _setFieldVal('s-caption-font-size', cfg.caption_font_size ? cfg.caption_font_size : '');
  _setFieldVal('s-caption-position', cfg.caption_position || 'bottom');
  _setFieldChk('s-caption-word-highlight', cfg.caption_word_highlight === true);
  _setFieldVal('s-caption-chunk-size', cfg.caption_word_chunk_size ?? 4);
  _onSettingsWordHighlightChange(cfg.caption_word_highlight === true);
}

// The words-on-screen count only applies when word-highlight is on.
function _onSettingsWordHighlightChange(enabled) {
  const el = document.getElementById('s-caption-chunk-size');
  if (el) el.disabled = !enabled;
}

// section id -> the applier that renders that section's fields from a config.
const _SECTION_APPLIERS = {
  'settings-sec-stt':      _applySttFields,
  'settings-sec-llm':      _applyLlmFields,
  'settings-sec-speakers': _applySpeakerFields,
  'settings-sec-weights':  _applyWeightFields,
  'settings-sec-analysis': _applyAnalysisFields,
  'settings-sec-hardware': _applyHardwareFields,
  'settings-sec-ui':       _applyUiFields,
  'settings-sec-export':   _applyExportFields,
};

function _applySettingsToUI(cfg) {
  _applySttFields(cfg);
  _applyLlmFields(cfg);
  _applySpeakerFields(cfg);
  _applyWeightFields(cfg);
  _applyAnalysisFields(cfg);
  _applyHardwareFields(cfg);
  _applyUiFields(cfg);
  _applyExportFields(cfg);
  _snapshotSettings();
  _checkSettingsDirty();
  ['cuda-libs'].forEach(_refreshInstallStatus);
}

// Factory defaults, fetched once per session and reused by every reset control.
let _defaultsCfg = null;
async function _ensureDefaults() {
  if (_defaultsCfg) return _defaultsCfg;
  _defaultsCfg = await fetch('/api/config/defaults').then(r => r.json());
  return _defaultsCfg;
}

// The playback/theme prefs are browser-local, not in the config, so their
// defaults live here rather than in the backend defaults payload.
function _resetUiPrefsToDefaults() {
  _setFieldChk('s-autoplay', false);
  _setFieldChk('s-play-next', false);
  _setFieldChk('s-loop-clip', false);
  _setFieldVal('s-playback-rate', '1');
  _setFieldVal('s-theme', 'dark');
  applyTheme('dark');
  _setFieldVal('s-accent', 'default');
  applyAccent('default');
}

// Fill one section's controls with factory defaults, leaving every other
// section untouched. Stages into the form (flags dirty); nothing persists
// until the user clicks Save. Defaults are prefetched when Settings opens.
function revertSection(sectionId) {
  const applier = _SECTION_APPLIERS[sectionId];
  if (!applier || !_defaultsCfg) return;
  applier(_defaultsCfg);
  if (sectionId === 'settings-sec-ui') _resetUiPrefsToDefaults();
  _checkSettingsDirty();
}

function revertAllSettings() {
  if (!_defaultsCfg) return;
  showConfirm(
    'Reset all settings to defaults?',
    'Every setting will be replaced with its default value. Nothing is saved until you click Save, so you can cancel by closing Settings without saving.',
    'Reset all',
    () => {
      for (const applier of Object.values(_SECTION_APPLIERS)) applier(_defaultsCfg);
      _resetUiPrefsToDefaults();
      _checkSettingsDirty();
      showToast('Settings reset to defaults - review and click Save to apply', 'info');
    },
    true,
  );
}

// Applies instantly (outside the Save flow) so the user sees the theme while
// choosing it. Deliberately not in _settingsFieldIds - must not flag dirty.
// The inline <head> script in index.html reads the same key before first paint.
function applyTheme(theme) {
  if (theme === 'dark') delete document.documentElement.dataset.theme;
  else document.documentElement.dataset.theme = theme;
  localStorage.setItem('yuuclip-theme', theme);
}

// Accent colour is orthogonal to the base theme (see the data-accent blocks in
// app.css). Like the theme, it applies instantly and is browser-local; the inline
// <head> script in index.html reads the same key before first paint.
function applyAccent(accent) {
  if (accent === 'default') delete document.documentElement.dataset.accent;
  else document.documentElement.dataset.accent = accent;
  localStorage.setItem('yuuclip-accent', accent);
}

// ── LLM scoring section (enable toggle + backend selection) ──────────────────
// Everything below the master toggle is inert while LLM scoring is off -
// inert (not disabled) so the fields keep their values for the save payload.
function _onLlmEnabledChange(enabled) {
  const body = document.getElementById('s-llm-body');
  if (!body) return;
  body.classList.toggle('settings-dimmed', !enabled);
  body.inert = !enabled;
}

// ── AI privacy mode ─────────────────────────────────────────────────────────
// The UI mirror of the server-side trust guarantee. Collapsing the generative
// block is presentation only - enforcement lives in resolve_ai_permissions; these
// controls never *grant* a capability the server blocks.
function _currentPrivacyMode() {
  const checked = document.querySelector('input[name="s-ai-privacy"]:checked');
  return checked ? checked.value : (window._aiPrivacyMode || 'local_only');
}

function _onPrivacyModeChange(mode) {
  window._aiPrivacyMode = mode;
  const hidden = document.getElementById('s-ai-privacy-value');
  if (hidden) hidden.value = mode;
  const generativeOff = mode === 'none';
  const genBlock    = document.getElementById('s-llm-generative-block');
  const noneSummary = document.getElementById('s-privacy-none-summary');
  if (genBlock)    genBlock.style.display    = generativeOff ? 'none' : '';
  if (noneSummary) noneSummary.style.display = generativeOff ? '' : 'none';
  const simLlmOption = document.querySelector('#s-similarity-backend option[value="llm"]');
  if (simLlmOption) simLlmOption.hidden = simLlmOption.disabled = generativeOff;
}

function _setPrivacyMode(mode) {
  const radio = document.querySelector(`input[name="s-ai-privacy"][value="${mode}"]`);
  if (radio) radio.checked = true;
  _onPrivacyModeChange(mode);
  _checkSettingsDirty();
}

// ── speaker labels section (diarization backend) ─────────────────────────────
function _onDiarizationBackendChange(backend) {
  const speechbrainEl = document.getElementById('s-speechbrain-fields');
  const commonEl      = document.getElementById('s-diarization-common-fields');
  if (speechbrainEl) speechbrainEl.style.display = backend === 'speechbrain' ? '' : 'none';
  if (commonEl)      commonEl.style.display      = backend !== 'null'        ? '' : 'none';
  _updateDiarizationStatus();
}

// Show at a glance whether speaker labels will actually run (the SpeechBrain
// package present), rather than discovering it only when an analyze run fails.
async function _updateDiarizationStatus() {
  const el = document.getElementById('s-diarization-status');
  if (!el) return;
  const backend = document.getElementById('s-diarization-backend').value;
  if (backend === 'null') {
    el.style.display = 'none';
    return;
  }
  el.style.display = '';
  let installed = false;
  try {
    installed = !!(await fetch('/api/install/speechbrain').then(r => r.json())).installed;
  } catch { /* treat unknown as not installed */ }
  el.innerHTML = `<span>${installed ? '✓' : '○'} SpeechBrain installed - no token needed</span>`;
  el.style.color = installed ? 'var(--green)' : 'var(--muted)';
}

// ── scoring, similarity & playback section handlers ──────────────────────────
function _onLaughModeChange(mode) {
  const modelEl = document.getElementById('s-laugh-model-fields');
  if (modelEl) modelEl.style.display = mode === 'model' ? '' : 'none';
}

function _onSimilarityBackendChange(backend) {
  const fields = document.getElementById('s-similarity-embeddings-fields');
  if (fields) fields.style.display = backend === 'embeddings' ? '' : 'none';
}

// Play-next and loop-clip are mutually exclusive - looping a clip forever
// would make "play next" unreachable, so enabling one clears the other.
function _onPlayNextChange(enabled) {
  if (!enabled) return;
  const loopEl = document.getElementById('s-loop-clip');
  if (loopEl) loopEl.checked = false;
}

function _onLoopClipChange(enabled) {
  if (!enabled) return;
  const playNextEl = document.getElementById('s-play-next');
  if (playNextEl) playNextEl.checked = false;
}

// ── content-type presets (plan 12) ──────────────────────────────────────────
// A one-choice tuning applied on top of the weight sliders. Unlike the sliders
// (batched into Save), Apply is its own atomic server-side action: it copies the
// preset's dimension + laugh weights into config and, opt-in, inserts starter
// hot-words. The selected preset drives the LLM prompt flavor live server-side.
let _contentPresets = null;
let _activeContentPresetId = 'generic';

async function initContentPresetSettings() {
  const sel = document.getElementById('s-content-preset');
  if (!sel) return;
  try {
    const data = await fetch('/api/content-presets').then(r => r.json());
    _contentPresets = data.presets || [];
    _activeContentPresetId = data.active || 'generic';
    sel.innerHTML = _contentPresets.map(p =>
      `<option value="${escHtml(p.id)}">${escHtml(p.name)}</option>`).join('');
    sel.value = _activeContentPresetId;
  } catch { _contentPresets = []; }
  _renderContentPresetInfo();
}

function _renderContentPresetInfo() {
  const sel = document.getElementById('s-content-preset');
  const chosen = (_contentPresets || []).find(p => p.id === sel?.value);
  const active = (_contentPresets || []).find(p => p.id === _activeContentPresetId);
  const descEl = document.getElementById('s-content-preset-desc');
  const activeEl = document.getElementById('s-content-preset-active');
  if (descEl) descEl.textContent = chosen ? chosen.description : '';
  if (activeEl) activeEl.textContent = active ? `Currently active: ${active.name}` : '';
}

function _onContentPresetChange() { _renderContentPresetInfo(); }

async function applyContentPreset() {
  const sel = document.getElementById('s-content-preset');
  const chosen = (_contentPresets || []).find(p => p.id === sel?.value);
  if (!chosen) return;
  const addHotwords = document.getElementById('s-content-preset-hotwords')?.checked ?? true;
  const w = chosen.dimension_weights || {};
  const weightLine =
    `Funny ${(w.score_funny_weight ?? 1).toFixed(1)}, ` +
    `Dramatic ${(w.score_dramatic_weight ?? 1).toFixed(1)}, ` +
    `Action ${(w.score_action_weight ?? 1).toFixed(1)}, ` +
    `Laughs ${(chosen.laugh_weight ?? 1.5).toFixed(1)}`;
  const hotwordLine = (addHotwords && chosen.hotword_count)
    ? ` and adds up to ${plural(chosen.hotword_count, 'starter hot-word')} (existing hot-words are kept)`
    : '';
  showConfirm(
    `Apply "${chosen.name}"?`,
    `Sets scoring weights to ${weightLine}${hotwordLine}. You can fine-tune everything below afterwards.`,
    'Apply',
    () => _doApplyContentPreset(chosen.id, addHotwords),
  );
}

async function _doApplyContentPreset(id, addHotwords) {
  let res;
  try {
    res = await fetch('/api/content-presets/apply', {
      method: 'POST', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({id, add_hotwords: addHotwords}),
    });
  } catch { showToast('Could not apply content type', 'error'); return; }
  if (!res.ok) {
    const e = await res.json().catch(() => ({}));
    showToast(formatApiError(e) || 'Could not apply content type', 'error');
    return;
  }
  const body = await res.json();
  _activeContentPresetId = body.applied;
  _applyPresetWeightsToUI(body.weights);
  if (addHotwords && body.hotwords_added) await initHotwordSettings();
  _renderContentPresetInfo();
  const added = body.hotwords_added ? ` · ${plural(body.hotwords_added, 'hot-word')} added` : '';
  showToast(`Applied content type${added} - re-score to apply the new weighting`, 'success');
}

// The preset already persisted these weights server-side, so rebaseline the
// settings snapshot for the weight fields - otherwise the panel's dirty check
// would flag them and prompt a redundant "discard changes?" on close.
function _applyPresetWeightsToUI(weights) {
  if (!weights) return;
  const map = {
    score_funny_weight: 's-funny-weight',
    score_dramatic_weight: 's-dramatic-weight',
    score_action_weight: 's-action-weight',
    scorer_laugh_weight: 's-laugh-weight',
  };
  for (const [key, id] of Object.entries(map)) {
    if (weights[key] == null) continue;
    const el = document.getElementById(id);
    const valEl = document.getElementById(`${id}-val`);
    const v = Number(weights[key]).toFixed(1);
    if (valEl) valEl.textContent = v;
    // Baseline from the element's own read-back, not `v`: a range input
    // normalizes "1.0" to "1", so storing `v` would falsely read as dirty.
    if (el) { el.value = v; _settingsOriginal[id] = el.value; }
  }
  _checkSettingsDirty();
}

// Blank caption size means "renderer default", stored as 0. A non-numeric entry
// also collapses to 0 so the PATCH never sends NaN.
function _captionSizeValue(raw) {
  if (raw === null || raw.trim() === '') return 0;
  const n = parseInt(raw, 10);
  return Number.isNaN(n) ? 0 : n;
}

function _chunkSizeValue(raw) {
  if (raw === null || raw.trim() === '') return 4;
  const n = parseInt(raw, 10);
  if (Number.isNaN(n)) return 4;
  return Math.min(12, Math.max(1, n));
}

// ── save + dirty tracking ────────────────────────────────────────────────────
async function saveSettings() {
  const getVal = id => { const el = document.getElementById(id); return el ? el.value : null; };
  const getChk = id => { const el = document.getElementById(id); return el ? el.checked : null; };
  const getNum = (id, parse) => { const v = getVal(id); return v !== null ? parse(v) : null; };

  const tlUnit = getVal('s-timeline-unit');
  const tlRaw  = getVal('s-timeline-interval');
  const tlSec  = _parseIntervalS(tlRaw, tlUnit);
  if (tlRaw !== null && tlRaw.trim() !== '' && tlSec === null) {
    showToast('Timeline interval must be at least 10 seconds.', 'warning');
    document.getElementById('s-timeline-interval')?.focus();
    return;
  }

  const payload = {
    whisper_model:              getVal('s-whisper-model'),
    whisper_device:             getVal('s-whisper-device'),
    whisper_compute_type:       getVal('s-whisper-compute'),
    whisper_language:           getVal('s-whisper-language'),
    ai_privacy_mode:            _currentPrivacyMode(),
    llm_enabled:                getChk('s-llm-enabled'),
    llm_model_path:             getVal('s-llm-model-path'),
    llm_vision_model_path:      getVal('s-llm-vision-model-path'),
    llm_mmproj_path:            getVal('s-llm-mmproj-path'),
    llm_use_gpu:                getChk('s-llm-use-gpu'),
    vision_enabled:             getChk('s-vision-enabled'),
    vision_frames_per_clip:     getNum('s-vision-frames', v => parseInt(v, 10)),
    visual_auto_vision_enabled: getChk('s-visual-auto-vision'),
    visual_vision_topn:         getNum('s-visual-vision-topn', v => parseInt(v, 10)),
    scorer_energy_weight:       getNum('s-energy-weight', parseFloat),
    scorer_scene_weight:        getNum('s-scene-weight', parseFloat),
    scorer_llm_weight:          getNum('s-llm-weight', parseFloat),
    scorer_laugh_weight:        getNum('s-laugh-weight', parseFloat),
    scorer_laugh_mode:          getVal('s-laugh-mode'),
    scorer_laugh_model_id:      getVal('s-laugh-model-id'),
    scorer_lexicon_weight:      getNum('s-lexicon-weight', parseFloat),
    scorer_speech_rate_weight:  getNum('s-speech-rate-weight', parseFloat),
    scorer_churn_weight:        getNum('s-churn-weight', parseFloat),
    scorer_prosody_weight:      getNum('s-prosody-weight', parseFloat),
    scorer_audio_event_weight:  getNum('s-audio-event-weight', parseFloat),
    scorer_audio_event_enabled: getChk('s-audio-event-enabled'),
    similarity_backend:         getVal('s-similarity-backend'),
    score_funny_weight:         getNum('s-funny-weight', parseFloat),
    score_dramatic_weight:      getNum('s-dramatic-weight', parseFloat),
    score_action_weight:        getNum('s-action-weight', parseFloat),
    score_visual_weight:        getNum('s-visual-weight', parseFloat),
    diarization_backend:        getVal('s-diarization-backend'),
    speaker_match_threshold:    getNum('s-speaker-match-threshold', parseFloat),
    speaker_cluster_threshold:  getNum('s-speaker-cluster-threshold', parseFloat),
    project_voice_match_threshold: getNum('s-project-voice-match-threshold', parseFloat),
    scene_detection_mode:       getVal('s-scene-mode'),
    visual_candidate_mode:      getVal('s-visual-mode'),
    energy_mode:                getVal('s-energy-mode'),
    silence_threshold_ms:       getNum('s-silence-ms', parseInt),
    min_clip_ms:                getNum('s-min-clip-ms', parseInt),
    scene_generation_enabled:   getChk('s-scene-generation'),
    thermal_autopause_enabled:  getChk('s-thermal-autopause'),
    thermal_warn_c:             getNum('s-thermal-warn-c', parseInt),
    thermal_pause_c:            getNum('s-thermal-pause-c', parseInt),
    export_name_template:       getVal('s-export-name-template'),
    title_card_bg_color:        getVal('s-title-card-bg-color'),
    title_card_font_color:      getVal('s-title-card-font-color'),
    title_card_scale:           getNum('s-title-card-scale', parseFloat),
    title_card_template:        getVal('s-title-card-template'),
    title_card_duration_s:      getNum('s-title-card-duration', parseFloat),
    caption_font_name:          getVal('s-caption-font-name') ?? '',
    caption_font_size:          _captionSizeValue(getVal('s-caption-font-size')),
    caption_position:           getVal('s-caption-position'),
    caption_word_highlight:     getChk('s-caption-word-highlight'),
    caption_word_chunk_size:    _chunkSizeValue(getVal('s-caption-chunk-size')),
    ...(tlSec ? {ui_timeline_interval_seconds: tlSec, ui_timeline_interval_unit: tlUnit} : {}),
  };

  localStorage.setItem('yuuclip-autoplay', getChk('s-autoplay'));
  localStorage.setItem('yuuclip-play-next', getChk('s-play-next'));
  localStorage.setItem('yuuclip-loop-clip', getChk('s-loop-clip'));
  localStorage.setItem('yuuclip-playback-rate', getVal('s-playback-rate'));
  applyPlaybackRate(playbackRatePref());

  const btn = document.getElementById('btn-settings-save');
  if (btn) { btn.disabled = true; btn.textContent = 'Saving…'; }
  try {
    const res = await fetch('/api/config', {
      method: 'PATCH', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify(payload),
    });
    if (!res.ok) {
      const e = await res.json().catch(() => ({}));
      showToast(`Settings error: ${e.detail || 'save failed'}`, 'error');
      if (btn) { btn.disabled = false; btn.textContent = 'Save'; }
      return;
    }
    window.commitSoundSettings?.();
    _flashSettingsSaved();
    _snapshotSettings();
    _checkSettingsDirty();
    if (btn) btn.textContent = 'Save';
    _updateLlmCapabilities();
    _renderCapabilityTiers();
    refreshModelCatalog();
    // Re-sync boot-cached server state and its dependent surfaces (analyze prereq
    // banner, per-clip description chips, vision frames) so changing the model or
    // AI settings takes effect without a restart.
    if (window.refreshServerState) refreshServerState();
  } catch {
    showToast('Settings save failed', 'error');
    if (btn) { btn.disabled = false; btn.textContent = 'Save'; }
  }
}


// Native ".gguf" file picker beside each model-path field - Electron only. In
// browser-dev mode there's no electronAPI, so the buttons stay hidden and the
// text box remains the way to set a path. Reveals + wires every
// [data-browse-target] button on load.
function _wireModelBrowseButtons() {
  if (!window.electronAPI?.pickModelFile) return;
  document.querySelectorAll('.settings-browse-btn[data-browse-target]').forEach(btn => {
    btn.style.display = '';
    btn.addEventListener('click', async () => {
      const target = document.getElementById(btn.getAttribute('data-browse-target'));
      if (!target) return;
      let picked = null;
      try { picked = await window.electronAPI.pickModelFile(); } catch { picked = null; }
      if (!picked) return;  // cancelled - leave the field unchanged
      target.value = picked;
      _checkSettingsDirty();
    });
  });
}

function _flashSettingsSaved() {
  const badge = document.getElementById('settings-saved-badge');
  if (!badge) return;
  badge.classList.add('show');
  setTimeout(() => badge.classList.remove('show'), 2000);
}

// Dirty-state tracking: re-check on any input/change in the settings panel
document.addEventListener('DOMContentLoaded', () => {
  const panel = document.getElementById('settings-panel');
  if (panel) {
    panel.addEventListener('input',  _checkSettingsDirty);
    panel.addEventListener('change', _checkSettingsDirty);
  }

  // The settings panel is a fixed overlay pinned below the header (CSS reads
  // --header-height for `top`). The header grows/shrinks as badges appear (remote
  // LLM), the job-progress row shows during analyze, or buttons wrap - so keep the
  // token live rather than snapshotting it once, or a stale value lets the panel
  // ride up over the header buttons.
  const header = document.querySelector('header');
  if (header && typeof ResizeObserver !== 'undefined') {
    const syncHeaderHeight = () =>
      document.documentElement.style.setProperty('--header-height', header.offsetHeight + 'px');
    syncHeaderHeight();
    new ResizeObserver(syncHeaderHeight).observe(header);
  }

  // Show "Re-run Setup Wizard" in the hamburger only when running inside Electron.
  if (window.electronAPI) {
    const btn = document.getElementById('btn-setup-wizard');
    if (btn) btn.style.display = '';
  }

  _wireModelBrowseButtons();

  // Enhance the title-card colour inputs with the shared picker. They live in the
  // always-present Settings markup, so a one-time attach at load is enough.
  ['s-title-card-bg-color', 's-title-card-font-color'].forEach(id => {
    const el = document.getElementById(id);
    if (el) window.ColorPicker?.attach(el);
  });

  // The global Escape handler leaves Escape to typing surfaces, so the glossary
  // filter handles it itself: first press clears the filter, second closes.
  const glossaryFilter = document.getElementById('glossary-filter');
  if (glossaryFilter) {
    glossaryFilter.addEventListener('keydown', e => {
      if (e.key !== 'Escape') return;
      e.preventDefault();
      if (glossaryFilter.value) {
        glossaryFilter.value = '';
        _filterGlossary('');
      } else {
        closeGlossaryModal();
      }
    });
  }
});

// Public API - symbols referenced cross-module, by an inline handler, or by a
// test. Internal helpers above stay private to this module's closure.
Object.assign(window, {
  openSettings, closeSettings, saveSettings, applyTheme, applyAccent,
  _onLlmEnabledChange, _onDiarizationBackendChange, _onLaughModeChange,
  _onSimilarityBackendChange, _onPrivacyModeChange, _setPrivacyMode, _currentPrivacyMode,
  _onPlayNextChange, _onLoopClipChange, _onSettingsWordHighlightChange,
  _updateDiarizationStatus,
  _scrollToSettingsSection, revertSection, revertAllSettings, _checkSettingsDirty,
  applyContentPreset, _onContentPresetChange,
});
})();

//# sourceURL=settings-previews.js
(function () {
// Feature-map - Settings > Export live previews (filename template + title card).
//   API: routes/config.py · Tests: tests/ui/test_ui_settings.py
// ── export section (filename template preview) ───────────────────────────────
// Sample values for the export-filename-template live preview - a plausible
// clip, not real data. Mirrors export_naming.export_base_stem's placeholder
// set and sanitization so the preview matches what the server would produce.
const _EXPORT_PREVIEW_SAMPLE = {
  video: 'MyRecording', clip_id: 42, start: '15-30', end: '16-00', score: '0.8',
  date: new Date().toISOString().slice(0, 10), preset: 'youtube-1080p',
};

function _updateExportNameTemplatePreview() {
  const el = document.getElementById('export-name-template-preview');
  if (!el) return;
  const template = document.getElementById('s-export-name-template').value
    || '{video}_clip{clip_id}_{start}';
  let rendered;
  try {
    rendered = template.replace(/\{(\w*)\}/g, (m, key) => {
      if (!(key in _EXPORT_PREVIEW_SAMPLE)) throw new Error('unknown placeholder');
      return _EXPORT_PREVIEW_SAMPLE[key];
    });
  } catch (e) {
    el.textContent = 'Preview: (unknown placeholder in template)';
    return;
  }
  rendered = rendered.replace(/[\\/:*?"<>|]/g, '').replace(/\s+/g, ' ').trim();
  el.textContent = `Preview: ${rendered || '(empty - falls back to the default template)'}.mkv`;
}

// ── title card preview + contrast warning (Settings -> Export) ────────────────
// A pure-CSS/HTML mock, not an ffmpeg render - "approximate" is called out in
// the UI copy. Colors here are the user's own chosen values (like the
// score-gradient exception in utils.js), not UI chrome, so they're applied
// directly rather than through a theme token.
// Sample values for the title-card template live preview - mirrors the
// placeholder set and per-line truncation of reel.title_card_lines so the mock
// matches what ffmpeg would render.
const _TITLE_CARD_PREVIEW_SAMPLE = {
  description: 'Chaos erupts as the squad clutches a 1v4.',
  start: '2:15',
  duration: '0:22',
};
const _TITLE_CARD_DESC_MAX = 90;
const _TITLE_CARD_CONTRAST_WARN_THRESHOLD = 3;

function _renderTitleCardPreviewLines(template) {
  const unknown = [];
  const lines = [];
  for (const rawLine of template.split('\n')) {
    let rendered = rawLine.replace(/\{(\w*)\}/g, (match, key) => {
      if (!(key in _TITLE_CARD_PREVIEW_SAMPLE)) { unknown.push(key); return match; }
      return _TITLE_CARD_PREVIEW_SAMPLE[key];
    }).trim();
    if (rendered.length > _TITLE_CARD_DESC_MAX) {
      rendered = rendered.slice(0, _TITLE_CARD_DESC_MAX - 1).trimEnd() + '…';
    }
    if (rendered) lines.push(rendered);
  }
  return {lines, unknown};
}

function _hexLuminance(hex) {
  const m = /^#([0-9a-f]{6})$/i.exec(hex || '');
  if (!m) return null;
  const [r, g, b] = [0, 2, 4]
    .map(i => parseInt(m[1].slice(i, i + 2), 16) / 255)
    .map(v => v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4);
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

function _contrastRatio(hex1, hex2) {
  const l1 = _hexLuminance(hex1);
  const l2 = _hexLuminance(hex2);
  if (l1 === null || l2 === null) return null;
  return (Math.max(l1, l2) + 0.05) / (Math.min(l1, l2) + 0.05);
}

function _updateTitleCardPreview() {
  const bg = document.getElementById('s-title-card-bg-color')?.value || '#000000';
  const fg = document.getElementById('s-title-card-font-color')?.value || '#ffffff';
  const scale = parseFloat(document.getElementById('s-title-card-scale')?.value || '1') || 1;
  const template = document.getElementById('s-title-card-template')?.value ?? '';

  const box = document.getElementById('s-title-card-preview');
  if (box) {
    box.style.background = bg;
    box.textContent = '';
    const {lines, unknown} = _renderTitleCardPreviewLines(template);
    const shown = lines.length
      ? lines
      : [`${_TITLE_CARD_PREVIEW_SAMPLE.start}  ·  ${_TITLE_CARD_PREVIEW_SAMPLE.duration}`];
    shown.forEach((text, idx) => {
      const line = document.createElement('div');
      line.textContent = text;
      line.style.color = fg;
      line.style.overflowWrap = 'anywhere';
      if (idx === 0) {
        line.style.fontWeight = '600';
        line.style.fontSize = `${Math.round(15 * scale)}px`;
      } else {
        line.style.fontSize = `${Math.round(11 * scale)}px`;
        line.style.marginTop = '6px';
      }
      box.appendChild(line);
    });
    const placeholderWarn = document.getElementById('s-title-card-template-warning');
    if (placeholderWarn) {
      const bad = [...new Set(unknown)];
      placeholderWarn.style.display = bad.length ? '' : 'none';
      placeholderWarn.textContent = bad.length
        ? `⚠ Unknown placeholder: ${bad.map(u => `{${u}}`).join(', ')}`
        : '';
    }
  }

  const warningEl = document.getElementById('s-title-card-contrast-warning');
  if (warningEl) {
    const ratio = _contrastRatio(bg, fg);
    warningEl.style.display = (ratio !== null && ratio < _TITLE_CARD_CONTRAST_WARN_THRESHOLD) ? '' : 'none';
  }
}

// Public API - the two entry points are wired to field `oninput` handlers in
// index.html and called from settings.js's _applySettingsToUI. The sample
// constants and pure helpers stay private to this closure.
Object.assign(window, {
  _updateExportNameTemplatePreview, _updateTitleCardPreview,
});
})();

//# sourceURL=settings-installs.js
(function () {
// Feature-map - Settings optional-package install controls + remote-LLM badge.
//   API: routes/analyze.py (install status/POST) · Tests: tests/ui/test_ui_settings.py
// ── optional-package installs ────────────────────────────────────────────────
// Only two install actions remain (packaging-strategy overhaul, Wave 3): Pyannote
// (the advanced, token-gated alternative to the default SpeechBrain speaker-labels
// backend) and the CUDA libraries for GPU-accelerated transcription. Everything
// else the app needs is bundled by default - see the Capabilities overview
// (_renderCapabilityTiers) for their Ready / "fetches on first use" status.
async function _refreshInstallStatus(slug) {
  const btn    = document.getElementById(`btn-install-${slug}`);
  const status = document.getElementById(`install-status-${slug}`);
  if (!btn || !status) return;
  try {
    const resp = await fetch(`/api/install/${slug}`);
    if (!resp.ok) return;
    const { installed } = await resp.json();
    if (installed) {
      status.textContent = '✓ Installed';
      status.style.color = 'var(--green)';
      btn.textContent = 'Reinstall';
    }
  } catch { /* leave default "Install" label on network error */ }
}

async function installPackage(slug) {
  const btn    = document.getElementById(`btn-install-${slug}`);
  const status = document.getElementById(`install-status-${slug}`);
  const log    = document.getElementById(`install-log-${slug}`);
  btn.disabled = true;
  btn.textContent = 'Installing…';
  status.textContent = '';
  log.textContent = '';
  log.style.display = 'block';
  try {
    const resp = await fetch(`/api/install/${slug}`, { method: 'POST' });
    if (!resp.ok) { throw new Error(await resp.text()); }
    const reader = resp.body.getReader();
    const dec = new TextDecoder();
    let buf = '';
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buf += dec.decode(value, { stream: true });
      const lines = buf.split('\n');
      buf = lines.pop();
      for (const line of lines) {
        if (!line.startsWith('data: ')) continue;
        const msg = JSON.parse(line.slice(6));
        if (msg === '__DONE__') {
          status.textContent = '✓ Installed';
          status.style.color = 'var(--green)';
          btn.textContent = 'Reinstall';
          btn.disabled = false;
          return;
        }
        log.textContent += msg + '\n';
        log.scrollTop = log.scrollHeight;
      }
    }
  } catch (e) {
    status.textContent = '✗ Failed - check log above';
    status.style.color = 'var(--red)';
  }
  btn.textContent = 'Retry';
  btn.disabled = false;
}

// Public API - installPackage is wired to inline install-button handlers in
// index.html; _refreshInstallStatus is called from settings.js's
// _applySettingsToUI. _updateDiarizationStatus resolves through window (owned by
// settings.js core) at call time.
Object.assign(window, {
  _refreshInstallStatus, installPackage,
});
})();

//# sourceURL=settings-backup.js
(function () {
// Feature-map - Settings > Backup & Restore (code: backup)
//   API: routes/backup.py (/api/backup, /api/restore/inspect, /api/restore/apply)
//   Siblings: project_archive.py (archive + re-point core) · projects.js (switchProject reload pattern)
//   Tests: tests/ui/test_ui_backup.py

// Backup: ask the server to build the archive, then download the returned zip.
// Uses the browser download (an <a download>) rather than an Electron save dialog:
// it works identically in browser-dev and inside packaged Electron (Chromium shows
// a native save dialog), and keeps the archive off a server-chosen path.
async function backupProject() {
  const btn = document.getElementById('btn-backup-project');
  const original = btn ? btn.textContent : '';
  if (btn) { btn.disabled = true; btn.textContent = 'Backing up…'; }
  try {
    const res = await fetch('/api/backup', { method: 'POST' });
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      showToast(formatApiError(err) || 'Backup failed', 'error');
      return;
    }
    const blob = await res.blob();
    _downloadBlob(blob, _filenameFromResponse(res) || 'yuu-clip-backup.zip');
    showToast('Backup saved', 'success');
  } catch {
    showToast('Backup failed', 'error');
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = original; }
  }
}

function _filenameFromResponse(res) {
  const disposition = res.headers.get('content-disposition') || '';
  const match = /filename="?([^"]+)"?/.exec(disposition);
  return match ? match[1] : null;
}

function _downloadBlob(blob, filename) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

// Restore is a review-before-commit flow: pick a file, preview what's in it and
// which source-media folders no longer resolve here, choose a target folder (and
// re-map any missing folders), then apply.
let _restoreState = null;

function startRestore() {
  const input = document.getElementById('restore-file-input');
  if (!input) return;
  input.value = '';
  input.click();
}

async function _onRestoreFileChosen(file) {
  if (!file) return;
  const flow = document.getElementById('restore-flow');
  flow.style.display = '';
  flow.innerHTML = '<div class="settings-note">Reading backup…</div>';
  try {
    const bytes = await file.arrayBuffer();
    const res = await fetch('/api/restore/inspect', { method: 'POST', body: bytes });
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      _hideRestoreFlow();
      showToast(formatApiError(err) || 'That file is not a valid backup', 'error');
      return;
    }
    const data = await res.json();
    _restoreState = {
      stagingPath: data.staging_path,
      groups: data.groups || [],
      manifest: data.manifest || {},
    };
    _renderRestorePlan();
  } catch {
    _hideRestoreFlow();
    showToast('Could not read backup', 'error');
  }
}

function _hideRestoreFlow() {
  const flow = document.getElementById('restore-flow');
  flow.innerHTML = '';
  flow.style.display = 'none';
  _restoreState = null;
}

function _renderRestorePlan() {
  const flow = document.getElementById('restore-flow');
  const { manifest, groups } = _restoreState;
  const created = manifest.created_at ? manifest.created_at.slice(0, 10) : 'unknown date';
  const canBrowse = !!window.electronAPI?.pickProjectFolder;
  const browseBtn = (id) => canBrowse
    ? `<button type="button" class="btn ghost" data-browse-into="${id}">Choose…</button>` : '';

  const repointRows = groups.map((group, i) => {
    const samples = (group.sample_filenames || []).map(escHtml).join(', ');
    return `
      <div class="restore-repoint-row" style="border-top:1px solid var(--border);padding:10px 0">
        <div style="font-size:12px;color:var(--text)"><code>${escHtml(group.missing_dir)}</code></div>
        <div class="settings-note">${plural(group.file_count, 'file')}${samples ? ` - e.g. ${samples}` : ''}</div>
        <div style="display:flex;gap:8px;align-items:center;margin-top:6px">
          <input type="text" id="repoint-${i}" class="settings-input" style="flex:1"
                 placeholder="New location for these files (leave blank to skip)">
          ${browseBtn(`repoint-${i}`)}
        </div>
      </div>`;
  }).join('');

  const repointBlock = groups.length ? `
    <div style="margin-top:14px">
      <div class="settings-label">Some source videos are not where the backup expected</div>
      <div class="settings-note" style="margin-bottom:4px">Point each missing folder to its new location so the clips still play. Blank folders are left as missing.</div>
      ${repointRows}
    </div>` : '';

  flow.innerHTML = `
    <div class="settings-note" style="margin-bottom:10px">
      Backup of <strong>${escHtml(manifest.project_name || 'project')}</strong> - created ${escHtml(created)}.
    </div>
    <div class="settings-label" for="restore-target">Restore into folder</div>
    <div class="settings-note" style="margin-bottom:4px">Choose an empty or new folder. To replace the current project, enter its folder - a safety copy of its database is kept.</div>
    <div style="display:flex;gap:8px;align-items:center">
      <input type="text" id="restore-target" class="settings-input" style="flex:1" placeholder="Folder to restore into">
      ${browseBtn('restore-target')}
    </div>
    ${repointBlock}
    <div style="display:flex;gap:10px;margin-top:16px">
      <button type="button" class="btn primary" id="btn-restore-confirm">Restore</button>
      <button type="button" class="btn ghost" id="btn-restore-cancel">Cancel</button>
    </div>`;

  flow.querySelectorAll('[data-browse-into]').forEach(btn => {
    btn.onclick = () => _pickFolderInto(btn.getAttribute('data-browse-into'));
  });
  document.getElementById('btn-restore-confirm').onclick = () => _applyRestore(false);
  document.getElementById('btn-restore-cancel').onclick = _hideRestoreFlow;
}

async function _pickFolderInto(inputId) {
  if (!window.electronAPI?.pickProjectFolder) return;
  const dir = await window.electronAPI.pickProjectFolder();
  if (dir) document.getElementById(inputId).value = dir;
}

async function _applyRestore(overwrite) {
  if (!_restoreState) return;
  const target = document.getElementById('restore-target').value.trim();
  if (!target) { showToast('Choose a folder to restore into', 'error'); return; }
  const mapping = {};
  _restoreState.groups.forEach((group, i) => {
    const value = document.getElementById(`repoint-${i}`)?.value.trim();
    if (value) mapping[group.missing_dir] = value;
  });

  const btn = document.getElementById('btn-restore-confirm');
  if (btn) { btn.disabled = true; btn.textContent = 'Restoring…'; }
  let res;
  try {
    res = await fetch('/api/restore/apply', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ archive_path: _restoreState.stagingPath, target_dir: target, mapping, overwrite }),
    });
  } catch {
    showToast('Restore failed', 'error');
    _resetRestoreConfirm();
    return;
  }

  if (res.status === 409) {
    const err = await res.json().catch(() => ({}));
    const detail = err.detail;
    if (!overwrite && detail && typeof detail === 'object' && detail.code === 'project_exists') {
      _resetRestoreConfirm();
      showConfirm(
        'Replace the existing project?',
        'That folder already contains a project. Replacing it keeps a safety copy of its database (project.db.pre-restore). Continue?',
        'Replace',
        () => _applyRestore(true),
        true,
      );
      return;
    }
    showToast((detail && detail.message) || 'Restore is unavailable right now', 'error');
    _resetRestoreConfirm();
    return;
  }
  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    showToast(formatApiError(err) || 'Restore failed', 'error');
    _resetRestoreConfirm();
    return;
  }

  const data = await res.json();
  if (window.electronAPI?.projectChanged) window.electronAPI.projectChanged(data.current);
  const stillMissing = data.repoint?.still_missing || 0;
  const missingNote = stillMissing ? ` (${plural(stillMissing, 'video')} still missing)` : '';
  showToast(`Restored${missingNote} - reloading…`, 'success');
  setTimeout(() => location.reload(), 600);
}

function _resetRestoreConfirm() {
  const btn = document.getElementById('btn-restore-confirm');
  if (btn) { btn.disabled = false; btn.textContent = 'Restore'; }
}

document.addEventListener('DOMContentLoaded', () => {
  const input = document.getElementById('restore-file-input');
  if (input) input.addEventListener('change', () => _onRestoreFileChosen(input.files[0]));
});

Object.assign(window, { backupProject, startRestore });
})();

//# sourceURL=projects.js
// Feature-map - Project switcher (code: project_dir).
//   API: routes/projects.py · Tests: tests/ui/test_ui_projects.py
// ── Project switcher ──────────────────────────────────────────────────────────
// Header dropdown to switch the server to another project folder in place (no
// restart). On a successful switch the whole page reloads - AppState is bound to
// the old project's data and is not hot-swapped. See routes/projects.py.
(function () {
let _openProjectOpener = null;

function _projectDisplayName(pathStr) {
  // Basename of a Windows or POSIX path - the folder name is the project name (v1).
  const parts = String(pathStr).split(/[\\/]/).filter(Boolean);
  return parts.length ? parts[parts.length - 1] : pathStr;
}

async function initProjectSwitcher() {
  try {
    const data = await fetch('/api/projects').then(r => r.json());
    const btn = document.getElementById('btn-project-switcher');
    document.getElementById('project-current-name').textContent = _projectDisplayName(data.current);
    btn.title = `Current project: ${data.current}`;
    btn.style.display = '';
    _renderProjectMenu(data);
  } catch (e) {
    // Switcher stays hidden if the list can't load - the server is still usable.
  }
}

function _renderProjectMenu(data) {
  const menu = document.getElementById('project-menu');
  menu.innerHTML = '';
  const others = (data.known || []).filter(p => p.path !== data.current);

  if (others.length) {
    const heading = document.createElement('div');
    heading.className = 'section-title';
    heading.style.cssText = 'padding:6px 14px 2px;font-size:11px';
    heading.textContent = 'Recent projects';
    menu.appendChild(heading);
    for (const proj of others) {
      const item = document.createElement('button');
      item.type = 'button';
      item.className = 'hamburger-item';
      item.setAttribute('role', 'menuitem');
      item.disabled = !proj.exists;
      const name = document.createElement('span');
      name.textContent = _projectDisplayName(proj.path);
      name.style.cssText = 'overflow:hidden;text-overflow:ellipsis;white-space:nowrap';
      item.appendChild(name);
      item.title = proj.exists ? proj.path : `${proj.path} (folder not found)`;
      if (proj.exists) item.onclick = () => { closeProjectMenu(); switchProject(proj.path); };
      menu.appendChild(item);
    }
    const divider = document.createElement('div');
    divider.className = 'hamburger-divider';
    menu.appendChild(divider);
  }

  const openItem = document.createElement('button');
  openItem.type = 'button';
  openItem.className = 'hamburger-item';
  openItem.setAttribute('role', 'menuitem');
  openItem.innerHTML = '<span class="hamburger-icon" aria-hidden="true">&#128194;</span>Open another project…';
  openItem.onclick = () => { closeProjectMenu(); openOpenProjectModal(); };
  menu.appendChild(openItem);
}

function isProjectMenuOpen() {
  return document.getElementById('project-menu').classList.contains('open');
}
function toggleProjectMenu() {
  const menu = document.getElementById('project-menu');
  menu.classList.toggle('open');
  document.getElementById('btn-project-switcher').setAttribute('aria-expanded', menu.classList.contains('open'));
  if (menu.classList.contains('open')) menu.querySelector('.hamburger-item:not(:disabled)')?.focus();
}
function closeProjectMenu(refocusTrigger = false) {
  const menu = document.getElementById('project-menu');
  if (refocusTrigger || menu.contains(document.activeElement)) {
    document.getElementById('btn-project-switcher').focus();
  }
  menu.classList.remove('open');
  document.getElementById('btn-project-switcher').setAttribute('aria-expanded', 'false');
}
document.getElementById('project-menu').addEventListener('keydown', e => {
  _menuArrowKeydown(document.getElementById('project-menu'), e);
});
document.addEventListener('click', e => {
  if (!document.getElementById('project-switcher-wrap').contains(e.target)) closeProjectMenu();
});
// Close when focus leaves the switcher - covers a panel/modal (or its focus
// trap) opening while the menu is up, which would otherwise float over it.
document.getElementById('project-switcher-wrap').addEventListener('focusout', e => {
  if (!isProjectMenuOpen()) return;
  const wrap = document.getElementById('project-switcher-wrap');
  if (e.relatedTarget && wrap.contains(e.relatedTarget)) return;
  closeProjectMenu();
});

async function switchProject(path) {
  try {
    const res = await fetch('/api/projects/switch', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ path }),
    });
    if (!res.ok) {
      const detail = await res.json().then(d => d.detail).catch(() => null);
      showToast(detail || 'Could not switch project', 'error');
      return false;
    }
    const data = await res.json();
    if (window.electronAPI?.projectChanged) window.electronAPI.projectChanged(data.current);
    showToast('Switching project…');
    setTimeout(() => location.reload(), 300);
    return true;
  } catch (e) {
    showToast('Could not switch project', 'error');
    return false;
  }
}

// ── Open-another-project modal ────────────────────────────────────────────────
function openOpenProjectModal() {
  _openProjectOpener = document.activeElement;
  document.getElementById('open-project-path').value = '';
  document.getElementById('btn-project-browse').style.display =
    window.electronAPI?.pickProjectFolder ? '' : 'none';
  document.getElementById('open-project-modal').classList.add('visible');
  setTimeout(() => document.getElementById('open-project-path').focus(), 50);
}
function closeOpenProjectModal() {
  document.getElementById('open-project-modal').classList.remove('visible');
  const opener = _openProjectOpener;
  _openProjectOpener = null;
  if (opener?.focus) opener.focus();
}
function _openProjectConfirm() {
  const path = document.getElementById('open-project-path').value.trim();
  if (!path) { showToast('Enter a project folder path', 'error'); return; }
  closeOpenProjectModal();
  switchProject(path);
}
async function browseForProjectFolder() {
  if (!window.electronAPI?.pickProjectFolder) return;
  const dir = await window.electronAPI.pickProjectFolder();
  if (dir) document.getElementById('open-project-path').value = dir;
}

document.getElementById('open-project-path').addEventListener('keydown', e => {
  if (e.key === 'Enter') { e.preventDefault(); _openProjectConfirm(); }
});

Object.assign(window, {
  initProjectSwitcher, isProjectMenuOpen, toggleProjectMenu, closeProjectMenu,
  closeOpenProjectModal, _openProjectConfirm, browseForProjectFolder,
});
})();

//# sourceURL=sounds.js
(function () {
// Feature-map - Notification sounds (Settings → Notification sounds; state in localStorage).
//   API: routes/sounds.py · Tests: tests/ui/test_ui_sounds.py
// ── notification sounds ───────────────────────────────────────────────────────
// Plays a short audio cue when a long-running action finishes. All state lives
// in localStorage; the backend only lists/serves audio bytes. Every event is
// OFF by default - the user opts in per event from Settings.

const STORE_KEY = 'yuuclip-sounds';
const EVENTS = [
  {key: 'analysis', label: 'Analysis complete',   note: 'When analyzing a recording finishes',        def: 'Windows Notify.wav'},
  {key: 'rescore',  label: 'Re-score complete',   note: 'When re-scoring clips finishes',              def: 'Windows Ding.wav'},
  {key: 'reel',     label: 'Highlight reel ready', note: 'When a highlight reel finishes building',    def: 'tada.wav'},
  {key: 'export',   label: 'Export complete',     note: 'When a clip or batch export finishes',        def: 'Windows Default.wav'},
  {key: 'error',    label: 'Any job failed',      note: 'When a long-running job errors out',          def: 'Windows Error.wav'},
];

let _sounds = null;                // {builtin:[], custom:[]} from the server
const _player = new Audio();       // single shared element - one cue at a time
let _stopPill = null;

function _defaultState() {
  const events = {};
  for (const e of EVENTS) events[e.key] = {enabled: false, kind: 'builtin', name: e.def};
  return {version: 1, volume: 0.7, events};
}

function _loadState() {
  try {
    const raw = localStorage.getItem(STORE_KEY);
    if (!raw) return _defaultState();
    const parsed = JSON.parse(raw);
    const base = _defaultState();
    base.volume = typeof parsed.volume === 'number' ? parsed.volume : base.volume;
    for (const e of EVENTS) {
      if (parsed.events && parsed.events[e.key]) {
        base.events[e.key] = {...base.events[e.key], ...parsed.events[e.key]};
      }
    }
    return base;
  } catch {
    return _defaultState();
  }
}

function _saveState(state) {
  try { localStorage.setItem(STORE_KEY, JSON.stringify(state)); } catch { /* storage full/blocked - non-fatal */ }
}

function _urlFor(choice) {
  if (!choice || !choice.name) return null;
  return `/api/sounds/file?kind=${encodeURIComponent(choice.kind || 'builtin')}&name=${encodeURIComponent(choice.name)}`;
}

function _play(url, volume) {
  if (!url) return;
  try {
    _player.pause();
    _player.src = url;
    _player.volume = Math.max(0, Math.min(1, volume));
    _player.currentTime = 0;
    const started = _player.play();
    if (started && started.catch) started.catch(() => { /* autoplay/codec refusal - ignore */ });
    _showStopPill();
  } catch { /* never let a sound break the action it accompanies */ }
}

// Public: fire the configured cue for a finished action, if the user enabled it.
function playActionSound(eventKey) {
  const state = _loadState();
  const choice = state.events[eventKey];
  if (!choice || !choice.enabled) return;
  _play(_urlFor(choice), state.volume);
}

function stopActionSound() {
  try { _player.pause(); _player.currentTime = 0; } catch { /* nothing playing */ }
  _hideStopPill();
}

// A floating "Stop sound" affordance so a long custom clip (e.g. a full song)
// can always be silenced. Shown while audio plays, removed when it ends.
function _showStopPill() {
  if (!_stopPill) {
    _stopPill = document.createElement('button');
    _stopPill.className = 'sound-stop-pill';
    _stopPill.textContent = '⏹ Stop sound';
    _stopPill.setAttribute('aria-label', 'Stop notification sound');
    _stopPill.onclick = stopActionSound;
    document.body.appendChild(_stopPill);
    _player.addEventListener('ended', _hideStopPill);
    _player.addEventListener('pause', _hideStopPill);
  }
  _stopPill.style.display = '';
}

function _hideStopPill() {
  if (_stopPill) _stopPill.style.display = 'none';
}

// ── settings panel wiring ─────────────────────────────────────────────────────
// Sound choices follow the panel's standard dirty/Save model: interacting with
// the rows only changes the DOM; localStorage is written by
// commitSoundSettings(), called from saveSettings() on a successful save.
// Preview (▶) is the exception - it plays the pending UI selection immediately,
// since it's an inspection, not a setting.
async function initSoundSettings() {
  const state = _loadState();
  const volEl = document.getElementById('s-sound-volume');
  const volVal = document.getElementById('s-sound-volume-val');
  if (volEl) {
    volEl.value = Math.round(state.volume * 100);
    if (volVal) volVal.textContent = `${volEl.value}%`;
    volEl.oninput = () => { if (volVal) volVal.textContent = `${volEl.value}%`; };
  }
  if (!_sounds) {
    try {
      _sounds = await fetch('/api/sounds').then(r => r.json());
    } catch {
      _sounds = {builtin: [], custom: []};
    }
  }
  _renderSoundRows(state);
}

// Saved state overlaid with the current DOM values, or null before the rows
// have rendered (settings.js runs its dirty check during panel open).
function _uiSoundState() {
  const host = document.getElementById('s-sound-rows');
  if (!host || !host.querySelector('.settings-row')) return null;
  const state = _loadState();
  const volEl = document.getElementById('s-sound-volume');
  if (volEl) state.volume = (parseInt(volEl.value, 10) || 0) / 100;
  for (const e of EVENTS) {
    const enabledEl = host.querySelector(`.s-sound-enabled[data-key="${e.key}"]`);
    const selectEl  = host.querySelector(`.s-sound-select[data-key="${e.key}"]`);
    if (!enabledEl || !selectEl) continue;
    const [kind, ...rest] = selectEl.value.split(':');
    state.events[e.key] = {enabled: enabledEl.checked, kind, name: rest.join(':')};
  }
  return state;
}

// Called from settings.js _checkSettingsDirty - also maintains the per-row
// dirty markers, mirroring what _checkSettingsDirty does for its own fields.
function _soundSettingsDirty() {
  const ui = _uiSoundState();
  if (!ui) return false;
  const saved = _loadState();
  let anyDirty = false;
  const volumeDirty = ui.volume !== saved.volume;
  if (volumeDirty) anyDirty = true;
  document.getElementById('s-sound-volume')?.closest('.settings-row')
    ?.classList.toggle('dirty', volumeDirty);
  const host = document.getElementById('s-sound-rows');
  for (const e of EVENTS) {
    const a = ui.events[e.key], b = saved.events[e.key];
    const dirty = a.enabled !== b.enabled || a.kind !== b.kind || a.name !== b.name;
    if (dirty) anyDirty = true;
    host.querySelector(`.s-sound-enabled[data-key="${e.key}"]`)
      ?.closest('.settings-row')?.classList.toggle('dirty', dirty);
  }
  return anyDirty;
}

function commitSoundSettings() {
  const ui = _uiSoundState();
  if (ui) _saveState(ui);
}

function _optionsHtml(selected) {
  const opt = (kind, name, label) => {
    const isSel = selected && selected.kind === kind && selected.name === name;
    const value = `${kind}:${name}`;
    return `<option value="${escHtml(value)}"${isSel ? ' selected' : ''}>${escHtml(label)}</option>`;
  };
  let html = '<optgroup label="Windows sounds">';
  html += (_sounds.builtin || []).map(s => opt('builtin', s.name, s.label)).join('');
  html += '</optgroup>';
  if ((_sounds.custom || []).length) {
    html += '<optgroup label="Your sounds">';
    html += _sounds.custom.map(s => opt('custom', s.name, s.name)).join('');
    html += '</optgroup>';
  }
  return html;
}

function _renderSoundRows(state) {
  const host = document.getElementById('s-sound-rows');
  if (!host) return;
  host.innerHTML = EVENTS.map(e => {
    const choice = state.events[e.key];
    return `
      <div class="settings-row">
        <div class="settings-col">
          <div class="settings-label">${escHtml(e.label)}</div>
          <div class="settings-note">${escHtml(e.note)}</div>
        </div>
        <div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;justify-content:flex-end">
          <label class="settings-checkbox" style="margin-right:4px">
            <input type="checkbox" class="s-sound-enabled" data-key="${escHtml(e.key)}"${choice.enabled ? ' checked' : ''}>
            <span style="font-size:13px">On</span>
          </label>
          <select class="settings-select s-sound-select" data-key="${escHtml(e.key)}" style="max-width:190px"${choice.enabled ? '' : ' disabled'}>
            ${_optionsHtml(choice)}
          </select>
          <button type="button" class="btn ghost s-sound-preview" data-key="${escHtml(e.key)}" title="Preview this sound" style="font-size:13px;padding:2px 8px">&#9654;</button>
        </div>
      </div>`;
  }).join('');

  host.querySelectorAll('.s-sound-enabled').forEach(el => {
    el.onchange = () => {
      const sel = host.querySelector(`.s-sound-select[data-key="${el.dataset.key}"]`);
      if (sel) sel.disabled = !el.checked;
    };
  });
  host.querySelectorAll('.s-sound-preview').forEach(el => {
    el.onclick = () => {
      const s = _uiSoundState() || _loadState();
      _play(_urlFor(s.events[el.dataset.key]), s.volume);
    };
  });
}

async function _onSoundUpload(input) {
  const file = input.files && input.files[0];
  if (!file) return;
  const status = document.getElementById('s-sound-upload-status');
  if (status) { status.textContent = 'Uploading…'; status.style.color = 'var(--muted)'; }
  try {
    const res = await fetch(`/api/sounds/upload?name=${encodeURIComponent(file.name)}`, {method: 'POST', body: file});
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      throw new Error(err.detail || `Upload failed (${res.status})`);
    }
    const pending = _uiSoundState() || _loadState();
    _sounds = await fetch('/api/sounds').then(r => r.json());
    _renderSoundRows(pending);
    if (status) { status.textContent = `✓ Added "${file.name}" - pick it in a dropdown above`; status.style.color = 'var(--green, #22c55e)'; }
  } catch (e) {
    if (status) { status.textContent = `✗ ${e.message}`; status.style.color = 'var(--red, #ef4444)'; }
  } finally {
    input.value = '';
  }
}

Object.assign(window, {
  SoundFx: {play: playActionSound, stop: stopActionSound},
  initSoundSettings, _onSoundUpload, _soundSettingsDirty, commitSoundSettings,
});
})();

//# sourceURL=hotwords.js
(function () {
// Feature-map - Hot-word (code: hot_words; Settings → Hot-words).
//   API: routes/hotwords.py · Tests: tests/ui/test_ui_hotwords.py
// ── hot-words settings ────────────────────────────────────────────────────────
// Server-backed CRUD (unlike the rest of the Settings panel, which batches into
// one Save): each row change persists immediately via POST/PUT/DELETE against
// /api/hotwords, mirroring the world-context manager's per-action save model.
// AppState.hotWords is the single cache - populated at boot (so the recording
// detail's Scan button can gate on it without an extra fetch) and refreshed here.

let _draftSeq = 0;

async function initHotwordSettings() {
  await Promise.all([ensureHotwordsCache(true), ensureContexts()]);
  _renderHotwordRows();
}

// force=true always refetches (Settings open); the boot-time call only fetches
// once, since AppState.hotWords starts as [] and boot doesn't need to be fresh-er
// than "whatever existed when the page loaded".
async function ensureHotwordsCache(force = false) {
  if (!force && AppState._hotWordsLoaded) return;
  try {
    AppState.hotWords = await fetch('/api/hotwords').then(r => r.json());
  } catch {
    AppState.hotWords = AppState.hotWords || [];
  }
  AppState._hotWordsLoaded = true;
}

function hasEnabledSemanticHotwords() {
  return (AppState.hotWords || []).some(hw => hw.enabled && hw.match_mode === 'semantic');
}

function _rowValues(rowEl) {
  return {
    phrase: rowEl.querySelector('.hw-phrase').value.trim(),
    match_mode: rowEl.querySelector('.hw-mode').value,
    boost: parseFloat(rowEl.querySelector('.hw-boost').value) || 0,
    target: rowEl.querySelector('.hw-target').value,
    enabled: rowEl.querySelector('.hw-enabled').checked,
    context_slug: rowEl.querySelector('.hw-context').value || null,
  };
}

async function _saveHotwordRow(rowEl) {
  const key = rowEl.dataset.hotwordRow;
  const isDraft = key.startsWith('draft-');
  const body = _rowValues(rowEl);
  if (isDraft && !body.phrase) return; // wait for a phrase before creating anything
  const res = await fetch(isDraft ? '/api/hotwords' : `/api/hotwords/${key}`, {
    method: isDraft ? 'POST' : 'PUT',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify(body),
  });
  if (!res.ok) {
    const e = await res.json().catch(() => ({}));
    showToast(formatApiError(e) || 'Could not save hot-word', 'error');
    return;
  }
  const saved = await res.json();
  const idx = AppState.hotWords.findIndex(hw => String(hw.id ?? hw._draftKey) === key);
  if (idx !== -1) AppState.hotWords[idx] = saved;
  else AppState.hotWords.push(saved);
  _renderHotwordRows();
  _notifyHotwordSaved();
}

async function _deleteHotwordRow(rowEl) {
  const key = rowEl.dataset.hotwordRow;
  if (key.startsWith('draft-')) {
    AppState.hotWords = AppState.hotWords.filter(hw => hw._draftKey !== key);
    _renderHotwordRows();
    return;
  }
  const res = await fetch(`/api/hotwords/${key}`, {method: 'DELETE'});
  if (!res.ok) {
    const e = await res.json().catch(() => ({}));
    showToast(formatApiError(e) || 'Could not delete hot-word', 'error');
    return;
  }
  AppState.hotWords = AppState.hotWords.filter(hw => String(hw.id) !== key);
  _renderHotwordRows();
  _notifyHotwordSaved();
}

function addHotwordRow() {
  AppState.hotWords.push({_draftKey: `draft-${++_draftSeq}`, phrase: '', match_mode: 'exact', boost: 0.1, target: 'overall', enabled: true, context_slug: null});
  _renderHotwordRows();
  const host = document.getElementById('s-hotword-rows');
  host?.querySelector('[data-hotword-row^="draft-"]:last-of-type .hw-phrase')?.focus();
}

// A hot-word save affects scores only after a rescan - surface a one-click path
// to refresh the currently open recording without forcing every video to rescan.
function _notifyHotwordSaved() {
  const videoId = window.AppState?.activeVideoId;
  if (!videoId) { showToast('Hot-word saved'); return; }
  showToast('Hot-word saved', 'success', {
    action: {label: 'Rescan current recording', onClick: () => _rescanHotwords(videoId)},
  });
}

async function _rescanHotwords(videoId) {
  const res = await fetch(`/api/videos/${videoId}/hotword-rescan`, {method: 'POST'});
  if (!res.ok) {
    const e = await res.json().catch(() => ({}));
    showToast(formatApiError(e) || 'Rescan failed', 'error');
    return;
  }
  const {clips_changed} = await res.json();
  showToast(clips_changed ? `Rescan complete - ${plural(clips_changed, 'clip')} updated` : 'Rescan complete - no changes');
  await _refreshActiveVideoClips(videoId);
}

async function _refreshActiveVideoClips(videoId) {
  if (window.AppState?.activeVideoId !== videoId) return;
  const clips = await fetch(_clipsListUrl(videoId)).then(r => r.json()).catch(() => null);
  if (clips) { AppState.clips = clips; _renderClips(); if (AppState.activeClipId) selectClip(AppState.activeClipId); }
}

// ── LLM-semantic scan (Stage 2) ─────────────────────────────────────────────────
// "Scan for Hot-words" lives in the recording detail's Additional Actions modal
// (videos.js openVideoActionsModal), gated on hasEnabledSemanticHotwords().
function scanHotwordsForVideo(videoId, btn) {
  const orig = btn?.textContent;
  if (btn) { btn.disabled = true; btn.textContent = 'Scanning…'; }
  openLog();
  _supersedeActiveStream();
  const resetBtn = () => { if (btn) { btn.disabled = false; btn.textContent = orig; } };
  let errorCount = 0;
  const handle = _openSSE(
    `/api/videos/${videoId}/hotword-scan`,
    data => {
      if (typeof data === 'string' && data.startsWith('[Error')) errorCount++;
      appendLog(String(data));
    },
    async () => {
      _clearActiveStream(handle);
      resetBtn();
      if (errorCount > 0) {
        showToast(`Scan finished - ${plural(errorCount, 'clip')} failed (check log)`, 'error');
      } else {
        showToast('Hot-word scan complete');
      }
      await _refreshActiveVideoClips(videoId);
    },
    errMsg => {
      _clearActiveStream(handle);
      resetBtn();
      showToast(`Scan failed - ${errMsg}`, 'error');
    },
  );
  _setActiveStream(handle, resetBtn);
}

function confirmScanHotwordsForVideo(videoId, btn) {
  showConfirm(
    'Scan for hot-words?',
    'Checks every clip\'s transcript against your "Meaning" hot-words using the ' +
    'Similarity engine. Recordings with many clips may take a moment.',
    'Scan',
    () => scanHotwordsForVideo(videoId, btn),
  );
}

function _hotwordRowKey(hw) { return String(hw.id ?? hw._draftKey); }

function _hotwordRowHtml(hw) {
  return `
    <div class="settings-row" data-hotword-row="${_hotwordRowKey(hw)}" style="align-items:center;gap:6px;flex-wrap:wrap">
      <input type="text" class="settings-input hw-phrase" value="${escHtml(hw.phrase)}" maxlength="200"
             placeholder="Phrase" style="flex:1;min-width:110px" aria-label="Phrase">
      <select class="settings-select hw-mode" style="max-width:150px" aria-label="Match mode">
        <option value="exact"${hw.match_mode === 'exact' ? ' selected' : ''}>Exact</option>
        <option value="case_insensitive"${hw.match_mode === 'case_insensitive' ? ' selected' : ''}>Ignore case</option>
        <option value="semantic"${hw.match_mode === 'semantic' ? ' selected' : ''}>Meaning</option>
      </select>
      <input type="number" class="settings-input hw-boost" value="${hw.boost}" step="0.05" min="-0.5" max="0.5"
             style="max-width:76px" aria-label="Score boost" title="Score boost, -0.5 to +0.5">
      <select class="settings-select hw-target" style="max-width:105px" aria-label="Boosted score">
        <option value="overall"${hw.target === 'overall' ? ' selected' : ''}>Overall</option>
        <option value="funny"${hw.target === 'funny' ? ' selected' : ''}>Funny</option>
        <option value="dramatic"${hw.target === 'dramatic' ? ' selected' : ''}>Dramatic</option>
        <option value="action"${hw.target === 'action' ? ' selected' : ''}>Action</option>
      </select>
      <select class="settings-select hw-context" style="max-width:150px" aria-label="Applies to">
        ${_termContextOptions(hw.context_slug)}
      </select>
      <label class="settings-checkbox" title="Apply this hot-word">
        <input type="checkbox" class="hw-enabled"${hw.enabled ? ' checked' : ''}>
        <span style="font-size:13px">On</span>
      </label>
      <button type="button" class="btn ghost hw-delete" title="Delete hot-word"
              aria-label="Delete hot-word ${escHtml(hw.phrase || 'draft')}" style="font-size:13px;padding:2px 8px">&times;</button>
      ${hw.match_mode === 'semantic' ? '<div style="width:100%;font-size:10px;color:var(--muted)">Matches by concept via the Similarity engine (set under Settings → LLM scoring). Applies only via the recording\'s "Scan for Hot-words" action.</div>' : ''}
    </div>`;
}

function _renderHotwordRows() {
  const host = document.getElementById('s-hotword-rows');
  if (!host) return;
  const hotWords = AppState.hotWords || [];
  if (!hotWords.length) {
    host.innerHTML = '<div style="color:var(--muted);font-size:12px;padding:4px 0 8px">No hot-words yet - add one below.</div>';
    return;
  }
  host.innerHTML = _renderTermGroups(hotWords, _hotwordRowHtml);
}

document.addEventListener('DOMContentLoaded', () => {
  const host = document.getElementById('s-hotword-rows');
  if (!host) return;
  host.addEventListener('change', e => {
    const row = e.target.closest('[data-hotword-row]');
    if (row) _saveHotwordRow(row);
  });
  host.addEventListener('click', e => {
    const del = e.target.closest('.hw-delete');
    const row = del?.closest('[data-hotword-row]');
    if (row) _deleteHotwordRow(row);
  });
});

Object.assign(window, {
  initHotwordSettings, addHotwordRow, ensureHotwordsCache, hasEnabledSemanticHotwords,
  confirmScanHotwordsForVideo, scanHotwordsForVideo,
});
})();

//# sourceURL=exportpresets.js
(function () {
// Feature-map - Export preset (code: ExportPreset; Settings → Export editor).
//   API: routes/export_presets.py · Tests: tests/integration/test_export_presets.py, tests/ui/test_ui_settings.py
// ── Export presets (Plan 07) ────────────────────────────────────────────────
// Custom presets are a global-config preference (Config.export_presets), not
// per-project DB rows like hot-words - but the Settings editor follows the
// same server-backed-per-row-save table pattern (hotwords.js) against
// /api/export-presets instead of /api/hotwords. AppState.exportPresets caches
// {builtins, custom} - populated at boot so the export options picker never
// needs an extra round trip, refreshed here when Settings opens.

let _draftSeq = 0;

async function ensureExportPresetsCache(force = false) {
  if (!force && AppState._exportPresetsLoaded) return;
  try {
    AppState.exportPresets = await fetch('/api/export-presets').then(r => r.json());
  } catch {
    AppState.exportPresets = AppState.exportPresets || {builtins: [], custom: []};
  }
  AppState._exportPresetsLoaded = true;
}

function _allExportPresets() {
  const presets = AppState.exportPresets || {builtins: [], custom: []};
  return [...(presets.builtins || []), ...(presets.custom || [])];
}

function exportPresetLabel(name) {
  if (!name || name === 'default') return 'Original quality';
  return _allExportPresets().find(p => p.name === name)?.label || name;
}

function exportPresetIsVertical(name) {
  if (!name || name === 'default') return false;
  return !!_allExportPresets().find(p => p.name === name)?.vertical;
}

// The size cap (MB) a preset targets, or null for a quality/CRF preset. Used by
// the export dialog's tight-cap warning to spot a long clip squeezed too small.
function exportPresetTargetSizeMb(name) {
  if (!name || name === 'default') return null;
  return _allExportPresets().find(p => p.name === name)?.target_size_mb ?? null;
}

// Renders the <option>s for the export options modal's preset picker.
async function populateExportPresetSelect(selectedName = '') {
  await ensureExportPresetsCache();
  const sel = document.getElementById('export-preset');
  if (!sel) return;
  const presets = AppState.exportPresets || {builtins: [], custom: []};
  const opt = (value, label) => `<option value="${escHtml(value)}"${selectedName === value ? ' selected' : ''}>${escHtml(label)}</option>`;
  sel.innerHTML = [
    opt('', 'Original quality (default)'),
    ...(presets.builtins || []).map(p => opt(p.name, p.label)),
    ...(presets.custom || []).map(p => opt(p.name, p.label)),
  ].join('');
}

// ── Settings: custom-preset editor ──────────────────────────────────────────

async function initExportPresetSettings() {
  await ensureExportPresetsCache(true);
  _renderExportPresetRows();
}

function _presetRowKey(p) { return String(p.name ?? p._draftKey); }

function _builtinPresetRowHtml(p) {
  const quality = p.target_size_mb != null ? `Target ${p.target_size_mb} MB` : `CRF ${p.crf}`;
  return `
    <div class="settings-row" style="align-items:center;gap:10px;flex-wrap:wrap;opacity:.7">
      <span style="flex:1;min-width:110px">${escHtml(p.label)}</span>
      <span style="font-size:12px;color:var(--muted)">${escHtml(p.container.toUpperCase())} · ${p.height ? `&le;${p.height}p` : 'Source resolution'} · ${escHtml(quality)}</span>
      <span style="font-size:11px;color:var(--muted)">Built-in</span>
    </div>`;
}

function _customPresetRowHtml(p) {
  const key = _presetRowKey(p);
  const sizeMode = p.target_size_mb != null;
  return `
    <div class="settings-row" data-preset-row="${escHtml(key)}" style="flex-direction:column;align-items:stretch;gap:6px">
      <div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center">
        <input type="text" class="settings-input ep-label" value="${escHtml(p.label || '')}" maxlength="60"
               placeholder="Label" style="flex:1;min-width:120px" aria-label="Preset label">
        <select class="settings-select ep-container" style="max-width:90px" aria-label="Container">
          <option value="mp4"${p.container === 'mp4' ? ' selected' : ''}>MP4</option>
          <option value="mkv"${p.container === 'mkv' ? ' selected' : ''}>MKV</option>
        </select>
        <select class="settings-select ep-height" style="max-width:140px" aria-label="Resolution">
          <option value=""${!p.height ? ' selected' : ''}>Source resolution</option>
          <option value="720"${p.height === 720 ? ' selected' : ''}>&le;720p</option>
          <option value="1080"${p.height === 1080 ? ' selected' : ''}>&le;1080p</option>
          <option value="1440"${p.height === 1440 ? ' selected' : ''}>&le;1440p</option>
          <option value="2160"${p.height === 2160 ? ' selected' : ''}>&le;2160p</option>
        </select>
        <label style="display:flex;align-items:center;gap:4px;font-size:12px" title="Crop to a 9:16 column and scale to 1080x1920 for TikTok / Shorts">
          <input type="checkbox" class="ep-vertical"${p.vertical ? ' checked' : ''}> Vertical 9:16
        </label>
        <button type="button" class="btn ghost ep-delete" title="Delete preset"
                aria-label="Delete preset ${escHtml(p.label || 'draft')}" style="font-size:13px;padding:2px 8px">&times;</button>
      </div>
      <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;padding-left:4px;font-size:12px">
        <label style="display:flex;align-items:center;gap:4px">
          <input type="radio" name="ep-mode-${escHtml(key)}" class="ep-mode-crf"${!sizeMode ? ' checked' : ''}> Quality (CRF)
        </label>
        <input type="number" class="settings-input ep-crf" min="0" max="51" value="${p.crf ?? 20}"
               style="max-width:60px" aria-label="CRF value"${sizeMode ? ' disabled' : ''}>
        <label style="display:flex;align-items:center;gap:4px">
          <input type="radio" name="ep-mode-${escHtml(key)}" class="ep-mode-size"${sizeMode ? ' checked' : ''}> Target size (MB)
        </label>
        <input type="number" class="settings-input ep-size" min="1" step="0.5" value="${p.target_size_mb ?? 10}"
               style="max-width:70px" aria-label="Target size in MB"${!sizeMode ? ' disabled' : ''}>
        <label style="display:flex;align-items:center;gap:4px">Audio
          <input type="number" class="settings-input ep-audio" min="32" max="320" value="${p.audio_kbps ?? 128}"
                 style="max-width:60px" aria-label="Audio bitrate kbps"> kbps
        </label>
      </div>
    </div>`;
}

function _renderExportPresetRows() {
  const host = document.getElementById('s-export-preset-rows');
  if (!host) return;
  const presets = AppState.exportPresets || {builtins: [], custom: []};
  const builtinRows = (presets.builtins || []).map(_builtinPresetRowHtml).join('');
  const customRows = (presets.custom || []).length
    ? presets.custom.map(_customPresetRowHtml).join('')
    : '<div style="color:var(--muted);font-size:12px;padding:4px 0 8px">No custom presets yet - add one below.</div>';
  host.innerHTML = builtinRows + customRows;
}

function _presetModeInputs(rowEl) {
  const crfRadio = rowEl.querySelector('.ep-mode-crf');
  const sizeRadio = rowEl.querySelector('.ep-mode-size');
  const crfInput = rowEl.querySelector('.ep-crf');
  const sizeInput = rowEl.querySelector('.ep-size');
  crfInput.disabled = !crfRadio.checked;
  sizeInput.disabled = !sizeRadio.checked;
}

function _presetRowValues(rowEl) {
  const sizeMode = rowEl.querySelector('.ep-mode-size').checked;
  const height = rowEl.querySelector('.ep-height').value;
  return {
    label: rowEl.querySelector('.ep-label').value.trim(),
    container: rowEl.querySelector('.ep-container').value,
    height: height ? parseInt(height, 10) : null,
    crf: sizeMode ? null : parseInt(rowEl.querySelector('.ep-crf').value, 10),
    target_size_mb: sizeMode ? parseFloat(rowEl.querySelector('.ep-size').value) : null,
    audio_kbps: parseInt(rowEl.querySelector('.ep-audio').value, 10) || 128,
    vertical: rowEl.querySelector('.ep-vertical').checked,
  };
}

async function _saveExportPresetRow(rowEl) {
  const key = rowEl.dataset.presetRow;
  const isDraft = key.startsWith('draft-');
  const body = _presetRowValues(rowEl);
  if (isDraft && !body.label) return; // wait for a label before creating anything
  const res = await fetch(isDraft ? '/api/export-presets' : `/api/export-presets/${encodeURIComponent(key)}`, {
    method: isDraft ? 'POST' : 'PUT',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify(body),
  });
  if (!res.ok) {
    const e = await res.json().catch(() => ({}));
    showToast(formatApiError(e) || 'Could not save export preset', 'error');
    return;
  }
  const saved = await res.json();
  const customs = AppState.exportPresets.custom;
  const idx = customs.findIndex(p => String(p.name ?? p._draftKey) === key);
  if (idx !== -1) customs[idx] = saved;
  else customs.push(saved);
  _renderExportPresetRows();
  showToast('Export preset saved');
}

async function _deleteExportPresetRow(rowEl) {
  const key = rowEl.dataset.presetRow;
  if (key.startsWith('draft-')) {
    AppState.exportPresets.custom = AppState.exportPresets.custom.filter(p => p._draftKey !== key);
    _renderExportPresetRows();
    return;
  }
  const res = await fetch(`/api/export-presets/${encodeURIComponent(key)}`, {method: 'DELETE'});
  if (!res.ok) {
    const e = await res.json().catch(() => ({}));
    showToast(formatApiError(e) || 'Could not delete export preset', 'error');
    return;
  }
  AppState.exportPresets.custom = AppState.exportPresets.custom.filter(p => p.name !== key);
  _renderExportPresetRows();
  showToast('Export preset deleted');
}

function addExportPresetRow() {
  AppState.exportPresets = AppState.exportPresets || {builtins: [], custom: []};
  AppState.exportPresets.custom.push({
    _draftKey: `draft-${++_draftSeq}`, label: '', container: 'mp4',
    height: null, crf: 20, target_size_mb: null, audio_kbps: 128, vertical: false,
  });
  _renderExportPresetRows();
  const host = document.getElementById('s-export-preset-rows');
  host?.querySelector('[data-preset-row^="draft-"]:last-of-type .ep-label')?.focus();
}

document.addEventListener('DOMContentLoaded', () => {
  const host = document.getElementById('s-export-preset-rows');
  if (!host) return;
  host.addEventListener('change', e => {
    const row = e.target.closest('[data-preset-row]');
    if (!row) return;
    if (e.target.classList.contains('ep-mode-crf') || e.target.classList.contains('ep-mode-size')) {
      _presetModeInputs(row);
    }
    _saveExportPresetRow(row);
  });
  host.addEventListener('click', e => {
    const del = e.target.closest('.ep-delete');
    const row = del?.closest('[data-preset-row]');
    if (row) _deleteExportPresetRow(row);
  });
});

Object.assign(window, {
  ensureExportPresetsCache, exportPresetLabel, exportPresetIsVertical,
  exportPresetTargetSizeMb,
  populateExportPresetSelect, initExportPresetSettings, addExportPresetRow,
});
})();

//# sourceURL=sensitive.js
(function () {
// Feature-map - Sensitive Terms (Privacy Terms + Censor Words; code: sensitive_terms).
//   API: routes/sensitive.py · Tests: tests/ui/test_ui_sensitive.py
// ── sensitive-content settings ──────────────────────────────────────────────
// Server-backed CRUD, same per-row-save model as hot-words (hotwords.js). The
// key difference: every save/delete triggers an immediate project-wide rescan
// server-side (routes/sensitive.py - text-only, synchronous), so there's no
// separate "Rescan current recording" follow-up action here - the toast just
// reports how many clips are flagged after the edit.
// AppState.sensitiveTerms is the single cache, populated at Settings-open time.

let _draftSeq = 0;
const FUZZY_MIN_TERM_LENGTH = 4;

async function initSensitiveTermSettings() {
  await Promise.all([ensureSensitiveTermsCache(true), ensureContexts()]);
  _renderSensitiveTermRows();
}

async function ensureSensitiveTermsCache(force = false) {
  if (!force && AppState._sensitiveTermsLoaded) return;
  try {
    AppState.sensitiveTerms = await fetch('/api/sensitive-terms').then(r => r.json());
  } catch {
    AppState.sensitiveTerms = AppState.sensitiveTerms || [];
  }
  AppState._sensitiveTermsLoaded = true;
}

function _sensitiveRowValues(rowEl) {
  return {
    term: rowEl.querySelector('.st-term').value.trim(),
    category: rowEl.querySelector('.st-category').value,
    match_mode: rowEl.querySelector('.st-mode').value,
    enabled: rowEl.querySelector('.st-enabled').checked,
    context_slug: rowEl.querySelector('.st-context').value || null,
  };
}

// Blocks "Close spelling" for a too-short term client-side, before it ever
// reaches the server (which would 400 anyway) - matches the mode dropdown's
// own inline explanation rather than a round-trip error toast.
function _sensitiveFuzzyGuardTripped(rowEl) {
  const body = _sensitiveRowValues(rowEl);
  const warnEl = rowEl.querySelector('.st-fuzzy-warning');
  const tripped = body.match_mode === 'fuzzy' && body.term.length < FUZZY_MIN_TERM_LENGTH;
  if (warnEl) warnEl.style.display = tripped ? '' : 'none';
  return tripped;
}

async function _saveSensitiveTermRow(rowEl) {
  const key = rowEl.dataset.sensitiveRow;
  const isDraft = key.startsWith('draft-');
  const body = _sensitiveRowValues(rowEl);
  if (isDraft && !body.term) return; // wait for a term before creating anything
  if (_sensitiveFuzzyGuardTripped(rowEl)) return;
  const res = await fetch(isDraft ? '/api/sensitive-terms' : `/api/sensitive-terms/${key}`, {
    method: isDraft ? 'POST' : 'PUT',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify(body),
  });
  if (!res.ok) {
    const e = await res.json().catch(() => ({}));
    showToast(formatApiError(e) || 'Could not save sensitive term', 'error');
    return;
  }
  const saved = await res.json();
  const idx = AppState.sensitiveTerms.findIndex(t => String(t.id ?? t._draftKey) === key);
  if (idx !== -1) AppState.sensitiveTerms[idx] = saved;
  else AppState.sensitiveTerms.push(saved);
  _renderSensitiveTermRows();
  showToast(`Sensitive term saved - ${plural(saved.clips_flagged, 'clip')} flagged`);
  _refreshActiveVideoClipsForSensitive();
}

async function _deleteSensitiveTermRow(rowEl) {
  const key = rowEl.dataset.sensitiveRow;
  if (key.startsWith('draft-')) {
    AppState.sensitiveTerms = AppState.sensitiveTerms.filter(t => t._draftKey !== key);
    _renderSensitiveTermRows();
    return;
  }
  const res = await fetch(`/api/sensitive-terms/${key}`, {method: 'DELETE'});
  if (!res.ok) {
    const e = await res.json().catch(() => ({}));
    showToast(formatApiError(e) || 'Could not delete sensitive term', 'error');
    return;
  }
  const {clips_flagged} = await res.json();
  AppState.sensitiveTerms = AppState.sensitiveTerms.filter(t => String(t.id) !== key);
  _renderSensitiveTermRows();
  showToast(`Sensitive term deleted - ${plural(clips_flagged, 'clip')} flagged`);
  _refreshActiveVideoClipsForSensitive();
}

function addSensitiveTermRow() {
  AppState.sensitiveTerms.push({
    _draftKey: `draft-${++_draftSeq}`, term: '', category: 'privacy', match_mode: 'exact', enabled: true, context_slug: null,
  });
  _renderSensitiveTermRows();
  const host = document.getElementById('s-sensitive-rows');
  host?.querySelector('[data-sensitive-row^="draft-"]:last-of-type .st-term')?.focus();
}

// The CRUD routes already rescan the whole project - this just refreshes the
// currently open recording's clip list so its badges/Flagged tab reflect it
// without the user having to reselect the recording.
async function _refreshActiveVideoClipsForSensitive() {
  const videoId = window.AppState?.activeVideoId;
  if (!videoId) return;
  const clips = await fetch(_clipsListUrl(videoId)).then(r => r.json()).catch(() => null);
  if (clips) { AppState.clips = clips; _renderClips(); if (AppState.activeClipId) selectClip(AppState.activeClipId); }
}

function _sensitiveRowKey(t) { return String(t.id ?? t._draftKey); }

const _CATEGORY_LABELS = {privacy: 'Privacy Term', censor: 'Censor Word'};
const _MODE_LABELS = {exact: 'Exact', case_insensitive: 'Ignore case', fuzzy: 'Close spelling'};

function _sensitiveRowHtml(t) {
  return `
    <div class="settings-row" data-sensitive-row="${_sensitiveRowKey(t)}" style="align-items:center;gap:6px;flex-wrap:wrap">
      <input type="text" class="settings-input st-term" value="${escHtml(t.term)}" maxlength="200"
             placeholder="Term" style="flex:1;min-width:110px" aria-label="Term">
      <select class="settings-select st-category" style="max-width:130px" aria-label="Category">
        <option value="privacy"${t.category === 'privacy' ? ' selected' : ''}>${_CATEGORY_LABELS.privacy}</option>
        <option value="censor"${t.category === 'censor' ? ' selected' : ''}>${_CATEGORY_LABELS.censor}</option>
      </select>
      <select class="settings-select st-mode" style="max-width:130px" aria-label="Match mode">
        <option value="exact"${t.match_mode === 'exact' ? ' selected' : ''}>Exact</option>
        <option value="case_insensitive"${t.match_mode === 'case_insensitive' ? ' selected' : ''}>Ignore case</option>
        <option value="fuzzy"${t.match_mode === 'fuzzy' ? ' selected' : ''}>Close spelling</option>
      </select>
      <select class="settings-select st-context" style="max-width:150px" aria-label="Applies to">
        ${_termContextOptions(t.context_slug)}
      </select>
      <label class="settings-checkbox" title="Apply this sensitive term">
        <input type="checkbox" class="st-enabled"${t.enabled ? ' checked' : ''}>
        <span style="font-size:13px">On</span>
      </label>
      <button type="button" class="btn ghost st-delete" title="Delete sensitive term"
              aria-label="Delete sensitive term ${escHtml(t.term || 'draft')}" style="font-size:13px;padding:2px 8px">&times;</button>
      <div class="st-fuzzy-warning" style="display:none;width:100%;font-size:10px;color:var(--warning)">
        Close spelling needs a term of at least ${FUZZY_MIN_TERM_LENGTH} characters - shorter terms match too many unrelated words.
      </div>
    </div>`;
}

function _renderSensitiveTermRows() {
  const host = document.getElementById('s-sensitive-rows');
  if (!host) return;
  const terms = AppState.sensitiveTerms || [];
  if (!terms.length) {
    host.innerHTML = '<div style="color:var(--muted);font-size:12px;padding:4px 0 8px">No sensitive terms yet - add one below.</div>';
    return;
  }
  host.innerHTML = _renderTermGroups(terms, _sensitiveRowHtml);
}

document.addEventListener('DOMContentLoaded', () => {
  const host = document.getElementById('s-sensitive-rows');
  if (!host) return;
  host.addEventListener('change', e => {
    const row = e.target.closest('[data-sensitive-row]');
    if (row) _saveSensitiveTermRow(row);
  });
  host.addEventListener('click', e => {
    const del = e.target.closest('.st-delete');
    const row = del?.closest('[data-sensitive-row]');
    if (row) _deleteSensitiveTermRow(row);
  });
});

Object.assign(window, {
  initSensitiveTermSettings, addSensitiveTermRow, ensureSensitiveTermsCache,
});
})();

//# sourceURL=split.js
// Feature-map - Split recording into segments (code: segment / segment_start_s).
//   API: routes/videos.py (split) · Tests: tests/ui/test_ui_split.py, tests/integration/test_segments.py
// ── shared live split-editor state ────────────────────────────────────────────
// Read cross-file: videos.js checks _splitPoints for the "has splits" badge,
// analyze.js reads the segment plan, index.html's zoom buttons read _splitZoom,
// and an inline onchange writes _splitNames[i]. Kept at top level, outside the
// IIFE below, so the global lexical binding stays live - an Object.assign export
// would snapshot the value and inline handlers / readers would go stale.
let _splitDurationS = 0;
let _splitPoints    = [];  // sorted list of seconds
let _splitNames     = [];  // auto-names, editable
let _splitIgnored   = new Set();  // indices of segments to skip
let _splitZoom      = 1;

// Suggestion-pin inputs/outputs. Not read by other production modules, but the
// _computeSuggestionPins tests seed _splitEnergyFlat and read _suggestionPins
// directly via page.evaluate (global lexical scope) - so they too stay outside
// the IIFE rather than becoming closure-private.
let _splitEnergyFlat = [];   // [{second, rms_db}, …] merged across tracks
let _suggestionPins  = [];    // [sec, …]

(function () {
// ── split editor ─────────────────────────────────────────────────────────────
let _splitVideoId   = null;

// Overlay data fetched once when the editor opens
let _splitSceneMs    = [];   // [ms, …] scene boundary timecodes
let _splitClipRanges = [];   // [{start_ms, end_ms}, …] existing clips

// Drag state
let _dragMarkerSec  = null;
let _dragActive     = false;

// Timeline zoom (main split editor only): 1 = fit whole recording, higher =
// wider bar inside a horizontal-scroll container. All overlay layers are
// %-positioned so they scale for free; only the waveform canvas needs a redraw.
// (_splitZoom itself is hoisted to top level above - an inline zoom-button
// handler in index.html reads it.)
const _SPLIT_ZOOM_MIN = 1;
const _SPLIT_ZOOM_MAX = 50;

const _SUGGESTION_MIN_GAP_S = 30;
const _SUGGESTION_COUNT     = 8;

// One instruction string for both editors (L6-3); the main editor appends its
// extra affordances. Scripts load at the end of <body>, so the elements exist.
const SPLIT_BAR_INSTRUCTIONS =
  'Click the bar to place a split point. Drag a marker to move it; hover over it and click its × to remove it.';
document.getElementById('pre-split-instructions').textContent = SPLIT_BAR_INSTRUCTIONS;
document.getElementById('split-instructions').textContent =
  `${SPLIT_BAR_INSTRUCTIONS} Click a marker to jump the preview there. Each segment can be analyzed independently after confirming.`;

// Ctrl/⌘+wheel over the timeline zooms; passive:false so preventDefault sticks.
document.getElementById('split-timeline-scroll')
  ?.addEventListener('wheel', _onSplitZoomWheel, { passive: false });

function isSplitEditorOpen() {
  return PanelNav.isOpen('split-editor');
}

async function openSplitEditor(videoId) {
  const video = AppState.videos.find(v => v.id === videoId);
  if (!video) return;

  _splitVideoId   = videoId;
  _splitDurationS = (video.duration_ms || 0) / 1000;
  _splitPoints    = [];
  _splitNames     = [];
  _splitIgnored   = new Set();
  _splitEnergyFlat = [];
  _splitSceneMs    = [];
  _splitClipRanges = [];
  _suggestionPins  = [];

  PanelNav.open({
    id: 'split-editor',
    title: `Split: ${video.filename}`,
    render: container => _mountSplitEditorPanel(container, videoId),
    isDirty: () => _splitPoints.length > 0,
    onClose: _teardownSplitEditor,
  });

  await _loadSplitEditorOverlays(videoId);
}

function _mountSplitEditorPanel(container, videoId) {
  const panel = document.getElementById('split-editor-panel');
  container.appendChild(panel);
  panel.style.display = 'flex';

  const video = AppState.videos.find(v => v.id === videoId);
  document.getElementById('split-preview-wrap').style.display = 'block';
  setupRecordingPreview(
    document.getElementById('split-preview-video'),
    document.getElementById('split-preview-badge'),
    videoId,
    { autoBuild: true, isCurrent: () => _splitVideoId === videoId, sourcePath: video?.source_path },
  );

  document.getElementById('split-waveform-notice').style.display = 'none';

  // A destructive re-analyze choice must not persist into the next session.
  document.querySelector('input[name="split-action"][value="partition"]').checked = true;

  _resetSplitZoom();
  _renderSplitEditor();
}

async function _loadSplitEditorOverlays(videoId) {
  // Fetch overlay data in parallel; render progressively
  const [energyRes, sceneRes, clipsRes] = await Promise.allSettled([
    fetch(`/api/videos/${videoId}/energy`).then(r => r.ok ? r.json() : null),
    fetch(`/api/videos/${videoId}/scene-boundaries`).then(r => r.ok ? r.json() : null),
    fetch(`/api/videos/${videoId}/clips`).then(r => r.ok ? r.json() : null),
  ]);

  let hasEnergy = false;
  if (energyRes.status === 'fulfilled' && energyRes.value?.tracks?.length) {
    const bySecond = new Map();
    for (const track of energyRes.value.tracks) {
      for (const s of track.samples) {
        const prev = bySecond.get(s.second);
        if (prev === undefined || s.rms_db > prev) bySecond.set(s.second, s.rms_db);
      }
    }
    if (bySecond.size > 0) {
      hasEnergy = true;
      _splitEnergyFlat = Array.from(bySecond.entries())
        .sort((a, b) => a[0] - b[0])
        .map(([second, rms_db]) => ({ second, rms_db }));
      _computeSuggestionPins();
      _drawWaveform();
    }
  }

  if (!hasEnergy) {
    document.getElementById('split-waveform-notice').style.display = 'flex';
  }

  if (sceneRes.status === 'fulfilled' && sceneRes.value?.boundaries_ms) {
    _splitSceneMs = sceneRes.value.boundaries_ms;
    _renderSceneLayer();
  }

  if (clipsRes.status === 'fulfilled' && clipsRes.value?.length) {
    _splitClipRanges = clipsRes.value.map(c => ({
      start_ms: c.start_ms,
      end_ms: c.end_ms,
    }));
    _renderClipsLayer();
  }

  _renderSuggestionLayer();
}

// Force-closes the panel (bypasses PanelNav's dirty gate) - used by callers
// that already ran their own confirm (e.g. switching recordings) and by the
// split editor's own post-confirm success paths.
function closeSplitEditor() {
  PanelNav.forceClose();
}

function _teardownSplitEditor() {
  const previewEl = document.getElementById('split-preview-video');
  previewEl.pause();
  previewEl.src = '';
  document.getElementById('split-preview-wrap').style.display = 'none';
  const badge = document.getElementById('split-preview-badge');
  if (badge) badge.style.display = 'none';
  const panel = document.getElementById('split-editor-panel');
  panel.style.display = 'none';
  // PanelNav removes its container (and everything still inside it) right
  // after onClose() runs - move the panel's static markup back out first so
  // it survives to be reparented into the next PanelNav container on reopen.
  document.getElementById('panelnav-root').insertAdjacentElement('afterend', panel);
  document.getElementById('split-waveform-notice').style.display = 'none';
  _splitVideoId   = null;
  _dragActive     = false;
  _dragMarkerSec  = null;
}

function _splitSeekTo(sec) {
  const v = document.getElementById('split-preview-video');
  if (v && v.src) {
    v.currentTime = sec;
    v.play().catch(() => {});
  }
}

// Preview proxy (720p, fast scrubbing) is handled by the shared
// setupRecordingPreview() in utils.js - see openSplitEditor.

async function _generateWaveform() {
  const btn = document.querySelector('#split-waveform-notice button');
  if (btn) { btn.disabled = true; btn.textContent = 'Generating…'; }
  const notice = document.getElementById('split-waveform-notice');

  streamSSE(
    `/api/videos/${_splitVideoId}/compute-waveform`,
    async () => {
      // Reload energy data and redraw
      const res = await fetch(`/api/videos/${_splitVideoId}/energy`).then(r => r.ok ? r.json() : null);
      if (res?.tracks?.length) {
        const bySecond = new Map();
        for (const track of res.tracks) {
          for (const s of track.samples) {
            const prev = bySecond.get(s.second);
            if (prev === undefined || s.rms_db > prev) bySecond.set(s.second, s.rms_db);
          }
        }
        if (bySecond.size > 0) {
          _splitEnergyFlat = Array.from(bySecond.entries())
            .sort((a, b) => a[0] - b[0])
            .map(([second, rms_db]) => ({ second, rms_db }));
          _computeSuggestionPins();
          _drawWaveform();
          notice.style.display = 'none';
          return;
        }
      }
      if (btn) { btn.disabled = false; btn.textContent = 'Generate Waveform'; }
    },
    null,
    'Waveform',
    false,
  );
}

// ── suggestion pins ──────────────────────────────────────────────────────────

function _computeSuggestionPins() {
  if (!_splitEnergyFlat.length || !_splitDurationS) return;

  // Work with normalised linear energy (not dB) for valley detection
  const minDb = Math.min(..._splitEnergyFlat.map(s => s.rms_db));
  const maxDb = Math.max(..._splitEnergyFlat.map(s => s.rms_db));
  const range  = maxDb - minDb || 1;

  // Score each second: 1 = quietest, 0 = loudest
  const scored = _splitEnergyFlat.map(s => ({
    sec:   s.second,
    score: 1 - (s.rms_db - minDb) / range,
  }));

  // Greedy pick: take the highest-scoring second not within gap of a chosen pin
  const sorted = [...scored].sort((a, b) => b.score - a.score);
  const pins = [];
  for (const { sec } of sorted) {
    if (pins.length >= _SUGGESTION_COUNT) break;
    if (sec <= 0 || sec >= _splitDurationS) continue;
    if (pins.some(p => Math.abs(p - sec) < _SUGGESTION_MIN_GAP_S)) continue;
    pins.push(sec);
  }
  _suggestionPins = pins.sort((a, b) => a - b);
}

// ── timeline zoom ─────────────────────────────────────────────────────────────

function _fmtZoom(z) {
  return (z >= 9.95 ? Math.round(z) : Math.round(z * 10) / 10) + '×';
}

function _resetSplitZoom() {
  _splitZoom = 1;
  const bar    = document.getElementById('split-timeline-bar');
  const scroll = document.getElementById('split-timeline-scroll');
  const label  = document.getElementById('split-zoom-label');
  if (bar)    bar.style.width = '100%';
  if (scroll) scroll.scrollLeft = 0;
  if (label)  label.textContent = _fmtZoom(1);
  _updateSplitZoomButtons();
}

function _updateSplitZoomButtons() {
  const out = document.getElementById('split-zoom-out');
  const inb = document.getElementById('split-zoom-in');
  if (out) out.disabled = _splitZoom <= _SPLIT_ZOOM_MIN + 1e-6;
  if (inb) inb.disabled = _splitZoom >= _SPLIT_ZOOM_MAX - 1e-6;
}

// Set the zoom factor, keeping the timeline point under *anchorClientX* fixed on
// screen (falls back to the viewport centre for button clicks).
function _setSplitZoom(zoom, anchorClientX) {
  const bar    = document.getElementById('split-timeline-bar');
  const scroll = document.getElementById('split-timeline-scroll');
  const label  = document.getElementById('split-zoom-label');
  if (!bar || !scroll) return;

  const newZoom = Math.max(_SPLIT_ZOOM_MIN, Math.min(_SPLIT_ZOOM_MAX, zoom));
  const oldW    = bar.offsetWidth || scroll.clientWidth;
  const anchorX = anchorClientX != null
    ? anchorClientX - scroll.getBoundingClientRect().left
    : scroll.clientWidth / 2;
  const anchorFrac = oldW ? (scroll.scrollLeft + anchorX) / oldW : 0;

  _splitZoom = newZoom;
  bar.style.width = (newZoom * 100) + '%';
  if (label) label.textContent = _fmtZoom(newZoom);

  _drawWaveform();                       // redraw at the new pixel width
  scroll.scrollLeft = anchorFrac * bar.offsetWidth - anchorX;
  _updateSplitZoomButtons();
}

function _onSplitZoomWheel(e) {
  if (!(e.ctrlKey || e.metaKey)) return;  // plain wheel keeps scrolling/panning
  e.preventDefault();
  _setSplitZoom(_splitZoom * (e.deltaY < 0 ? 1.25 : 1 / 1.25), e.clientX);
}

// ── canvas waveform ──────────────────────────────────────────────────────────

function _drawWaveform() {
  const canvas = document.getElementById('split-waveform-canvas');
  if (!canvas || !_splitEnergyFlat.length || !_splitDurationS) return;

  // Use layout size, not CSS pixel size. Clamp the bitmap width so a deep zoom
  // on a multi-hour recording can't exceed the browser's max canvas dimension;
  // CSS stretches the (soft, semi-transparent) waveform over any excess.
  const W = Math.min(canvas.offsetWidth || 800, 16000);
  const H = canvas.offsetHeight || 60;
  canvas.width  = W;
  canvas.height = H;

  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, W, H);

  const minDb = Math.min(..._splitEnergyFlat.map(s => s.rms_db));
  const maxDb = Math.max(..._splitEnergyFlat.map(s => s.rms_db));
  const range  = maxDb - minDb || 1;

  // Downsample to one bar per CSS pixel bucket
  const buckets = new Float32Array(W);
  const counts  = new Uint16Array(W);
  for (const { second, rms_db } of _splitEnergyFlat) {
    const x = Math.floor((second / _splitDurationS) * W);
    if (x >= 0 && x < W) {
      buckets[x] += rms_db;
      counts[x]++;
    }
  }

  // Filled path from bottom, centred vertically
  ctx.beginPath();
  ctx.moveTo(0, H);
  for (let x = 0; x < W; x++) {
    const avg = counts[x] ? buckets[x] / counts[x] : minDb;
    const norm = (avg - minDb) / range;            // 0..1
    const barH = Math.max(2, norm * H * 0.85);
    ctx.lineTo(x, H - barH);
  }
  ctx.lineTo(W, H);
  ctx.closePath();

  // Use CSS variable for accent with low opacity
  const style = getComputedStyle(document.documentElement);
  const accent = style.getPropertyValue('--accent').trim() || '#6c8ebf';
  ctx.fillStyle = accent + '55';   // ~33 % opacity
  ctx.fill();
}

// ── scene boundary layer ─────────────────────────────────────────────────────

function _renderSceneLayer() {
  const el = document.getElementById('split-scene-layer');
  if (!el || !_splitDurationS) return;

  el.innerHTML = _splitSceneMs.map(ms => {
    const pct = (ms / 1000 / _splitDurationS * 100).toFixed(3);
    return `<div style="position:absolute;left:${pct}%;top:0;bottom:0;width:1px;background:color-mix(in srgb, var(--text) 30%, transparent)" title="Scene cut at ${_fmtSplitTime(ms / 1000)}"></div>`;
  }).join('');
}

// ── suggestion pin layer ─────────────────────────────────────────────────────

function _renderSuggestionLayer() {
  const el = document.getElementById('split-suggestion-layer');
  if (!el || !_splitDurationS) return;

  el.innerHTML = _suggestionPins.map(sec => {
    // Hide if already a real marker
    if (_splitPoints.some(p => Math.abs(p - sec) < 1)) return '';
    const pct = (sec / _splitDurationS * 100).toFixed(3);
    return `<div data-pin="${sec}" class="split-suggestion-pin"
                 style="position:absolute;left:${pct}%;top:0;bottom:0;width:14px;transform:translateX(-50%);cursor:pointer;pointer-events:auto;display:flex;justify-content:center"
                 title="Quiet valley at ${_fmtSplitTime(sec)} - click to place a split point here"
                 onclick="event.stopPropagation();_promoteSuggestionPin(${sec})">
               <div style="width:0;border-left:1.5px dashed color-mix(in srgb, var(--text) 40%, transparent)"></div>
             </div>`;
  }).join('');
}

function _promoteSuggestionPin(sec) {
  if (_splitPoints.some(p => Math.abs(p - sec) < 0.5)) return;
  _splitPoints.push(sec);
  _splitPoints.sort((a, b) => a - b);
  _rebuildSplitNames();
  _renderSplitEditor();
}

// ── existing clips dot layer ─────────────────────────────────────────────────

function _renderClipsLayer() {
  const el = document.getElementById('split-clips-layer');
  if (!el || !_splitDurationS) return;

  el.innerHTML = _splitClipRanges.map(({ start_ms, end_ms }) => {
    const leftPct  = (start_ms / 1000 / _splitDurationS * 100).toFixed(3);
    const widthPct = ((end_ms - start_ms) / 1000 / _splitDurationS * 100).toFixed(3);
    return `<div style="position:absolute;left:${leftPct}%;width:${widthPct}%;top:50%;transform:translateY(-50%);height:4px;background:color-mix(in srgb, var(--text) 22%, transparent);border-radius:2px" title="Existing clip ${_fmtSplitTime(start_ms/1000)}–${_fmtSplitTime(end_ms/1000)}"></div>`;
  }).join('');
}

// ── drag-to-reposition markers ────────────────────────────────────────────────

function _splitMarkerPointerDown(e, sec) {
  e.stopPropagation();
  e.preventDefault();
  _dragMarkerSec = sec;
  _dragActive    = true;
  let moved      = false;

  const bar = document.getElementById('split-timeline-bar');

  function onMove(ev) {
    if (!_dragActive) return;
    moved = true;
    const rect = bar.getBoundingClientRect();
    const frac = Math.max(0, Math.min(1, (ev.clientX - rect.left) / rect.width));
    const newSec = Math.round(frac * _splitDurationS * 10) / 10;
    if (newSec <= 0 || newSec >= _splitDurationS) return;

    const idx = _splitPoints.indexOf(_dragMarkerSec);
    if (idx !== -1) {
      _splitPoints[idx] = newSec;
      _dragMarkerSec = newSec;
      _splitPoints.sort((a, b) => a - b);
      _renderSplitEditor();
    }
  }

  function onUp() {
    _dragActive    = false;
    if (!moved) _splitSeekTo(sec);
    _dragMarkerSec = null;
    window.removeEventListener('pointermove', onMove);
    window.removeEventListener('pointerup',   onUp);
    _rebuildSplitNames();
    _renderSplitEditor();
  }

  window.addEventListener('pointermove', onMove);
  window.addEventListener('pointerup',   onUp);
}

// ── main click handler ───────────────────────────────────────────────────────

function splitTimelineClick(e) {
  if (!_splitDurationS || _dragActive) return;
  const bar  = document.getElementById('split-timeline-bar');
  const rect = bar.getBoundingClientRect();
  const frac = (e.clientX - rect.left) / rect.width;
  const sec  = Math.round(frac * _splitDurationS * 10) / 10;

  if (sec <= 0 || sec >= _splitDurationS) return;

  // Too close to an existing marker - ignore rather than stack a near-duplicate
  // (removal is via the marker's × button).
  const threshold = _splitDurationS * 0.005;
  if (_splitPoints.some(p => Math.abs(p - sec) <= threshold)) return;

  _splitPoints.push(sec);
  _splitPoints.sort((a, b) => a - b);
  _rebuildSplitNames();
  _renderSplitEditor();
}

function _removeSplitPoint(sec, isPreSplit) {
  const idx = _splitPoints.indexOf(sec);
  if (idx === -1) return;
  _splitPoints.splice(idx, 1);
  if (isPreSplit) {
    _rebuildPreSplitNames();
    _renderPreSplitEditor();
  } else {
    _rebuildSplitNames();
    _renderSplitEditor();
  }
}

// ── render ───────────────────────────────────────────────────────────────────

function _rebuildSplitNames() {
  if (!_splitVideoId) return;
  const video = AppState.videos.find(v => v.id === _splitVideoId);
  const stem  = video ? video.filename.replace(/\.[^.]+$/, '') : 'Recording';
  const count = _splitPoints.length + 1;
  _splitNames = Array.from({length: count}, (_, i) => `${stem} - Part ${i + 1}`);
}

function _renderSplitEditor() {
  _renderSplitTimeline();
  _updateSplitConfirmState();  // also re-renders the segment list
}

function _updateSplitConfirmState() {
  const btn = document.getElementById('btn-split-confirm');
  const action = document.querySelector('input[name="split-action"]:checked')?.value || 'partition';
  btn.classList.toggle('danger', action !== 'partition');
  btn.classList.toggle('primary', action === 'partition');
  const noPoints = _splitPoints.length === 0;
  btn.disabled = noPoints;
  btn.title = noPoints ? 'Place at least one split point first' : '';
  _renderSplitSegmentList();
}

function _renderSplitTimeline() {
  const bar      = document.getElementById('split-timeline-bar');
  const markers  = document.getElementById('split-markers-layer');
  const segments = document.getElementById('split-segments-layer');
  if (!bar) return;

  // Redraw waveform canvas in case width changed
  _drawWaveform();

  // Re-render overlay layers that depend on user markers (suggestion pins hide when near a marker)
  _renderSuggestionLayer();

  // Segment colour bands
  const pts = [0, ..._splitPoints, _splitDurationS];
  const palette = ['var(--accent)', 'var(--warning)', 'var(--green)', 'var(--red)'];
  segments.innerHTML = pts.slice(0, -1).map((start, i) => {
    const end      = pts[i + 1];
    const widthPct = ((end - start) / _splitDurationS * 100).toFixed(3);
    const col      = _splitIgnored.has(i) ? 'var(--muted)' : palette[i % palette.length];
    const opacity  = _splitIgnored.has(i) ? '0.08' : '0.12';
    return `<div style="height:100%;width:${widthPct}%;background:${col};opacity:${opacity};border-right:1px solid ${col}"></div>`;
  }).join('');

  // User-placed markers with drag handles
  markers.innerHTML = _splitPoints.map(p => {
    const pct = (p / _splitDurationS * 100).toFixed(3);
    const timeLabel = _fmtSplitTime(p);
    return `<div class="split-marker" style="position:absolute;left:${pct}%;top:0;bottom:0;width:10px;transform:translateX(-50%);cursor:ew-resize;pointer-events:auto;display:flex;align-items:stretch;justify-content:center"
                 title="${timeLabel} - drag to move, click to preview from here"
                 onpointerdown="event.stopPropagation();_splitMarkerPointerDown(event,${p})">
               <div style="width:2px;background:var(--accent);border-radius:1px"></div>
               <button type="button" class="split-marker-x" title="Remove split point"
                       aria-label="Remove split point at ${timeLabel}"
                       onpointerdown="event.stopPropagation()"
                       onclick="event.stopPropagation();_removeSplitPoint(${p},false)">&#215;</button>
             </div>`;
  }).join('');
}

function _parseSplitTime(str) {
  const parts = str.trim().split(':').map(Number);
  if (parts.some(isNaN)) return null;
  if (parts.length === 3) return parts[0] * 3600 + parts[1] * 60 + parts[2];
  if (parts.length === 2) return parts[0] * 60 + parts[1];
  if (parts.length === 1) return parts[0];
  return null;
}

function _updateSplitPoint(idx, timeStr, onRerender) {
  const sec = _parseSplitTime(timeStr);
  if (sec === null) {
    showToast(`Couldn't read "${timeStr}" - use h:mm:ss or m:ss`, 'error');
    onRerender();
    return;
  }
  if (sec <= 0 || sec >= _splitDurationS) {
    showToast(`Split point must be between 0:00 and ${_fmtSplitTime(_splitDurationS)}`, 'error');
    onRerender();
    return;
  }
  _splitPoints[idx] = sec;
  _splitPoints.sort((a, b) => a - b);
  if (_splitVideoId) _rebuildSplitNames(); else _rebuildPreSplitNames();
  onRerender();
}

function _renderSegmentList(listId, onRerender, showPlayBtn, showIgnore = true) {
  const list = document.getElementById(listId);
  if (!list || !_splitDurationS) return;
  const pts = [0, ..._splitPoints, _splitDurationS];

  list.innerHTML = pts.slice(0, -1).map((start, i) => {
    const end      = pts[i + 1];
    const ignored  = _splitIgnored.has(i);
    const name     = escHtml(_splitNames[i] || `Part ${i + 1}`);
    const startStr = escHtml(_fmtSplitTime(start));
    const endStr   = escHtml(_fmtSplitTime(end));
    const onUpdate = `_updateSplitPoint(%idx%, this.value, ${onRerender.name})`;
    const dimStyle = ignored ? 'opacity:0.45;' : '';
    const startEl  = i === 0
      ? `<span style="font-size:12px;color:var(--muted);min-width:58px">${startStr}</span>`
      : `<input type="text" value="${startStr}"
               style="font-size:12px;color:var(--muted);background:transparent;border:none;border-bottom:1px dashed var(--muted);width:58px;text-align:center;padding:1px 2px"
               title="Edit split point (h:mm:ss or m:ss)"
               onchange="${onUpdate.replace('%idx%', i - 1)}"
               aria-label="Segment ${i + 1} start time">`;
    const endEl    = i === pts.length - 2
      ? `<span style="font-size:12px;color:var(--muted);min-width:58px">${endStr}</span>`
      : `<input type="text" value="${endStr}"
               style="font-size:12px;color:var(--muted);background:transparent;border:none;border-bottom:1px dashed var(--muted);width:58px;text-align:center;padding:1px 2px"
               title="Edit split point (h:mm:ss or m:ss)"
               onchange="${onUpdate.replace('%idx%', i)}"
               aria-label="Segment ${i + 1} end time">`;
    const playBtn  = showPlayBtn
      ? `<button class="btn ghost" style="padding:2px 7px;font-size:12px;flex-shrink:0" title="Play from ${startStr}" onclick="_splitSeekTo(${start})">&#9654;</button>`
      : '';
    const ignoreChk = showIgnore ? `<label style="display:flex;align-items:center;gap:4px;font-size:12px;color:var(--muted);white-space:nowrap;cursor:pointer;flex-shrink:0" title="Ignore this segment - it will be split off but not analyzed">
        <input type="checkbox" ${ignored ? 'checked' : ''} onchange="_toggleIgnored(${i}, ${onRerender.name})"> Ignore
      </label>` : '';
    return `
      <div style="display:flex;align-items:center;gap:10px;padding:6px 10px;background:var(--surface);border:1px solid var(--border);border-radius:6px;${ignored ? 'opacity:0.5' : ''}">
        ${playBtn}
        <div style="display:flex;align-items:center;gap:4px;white-space:nowrap;${dimStyle}">${startEl}<span style="font-size:12px;color:var(--muted)">–</span>${endEl}</div>
        <input type="text" value="${name}"
               style="flex:1;padding:4px 8px;background:var(--bg);border:1px solid var(--border);border-radius:4px;color:var(--text);font-size:13px"
               onchange="_splitNames[${i}] = this.value"
               ${ignored ? 'disabled' : ''}
               aria-label="Segment ${i + 1} name">
        ${ignoreChk}
      </div>`;
  }).join('');
}

function _toggleIgnored(idx, onRerender) {
  if (_splitIgnored.has(idx)) _splitIgnored.delete(idx);
  else _splitIgnored.add(idx);
  onRerender();
}

function _renderSplitSegmentList() {
  const action = document.querySelector('input[name="split-action"]:checked')?.value || 'partition';
  // Ignore only matters when segments get reanalyzed independently - meaningless
  // for a plain partition, where every segment keeps whatever clips land in it.
  _renderSegmentList('split-segment-list', _renderSplitEditor, true, action !== 'partition');
}

function _fmtSplitTime(sec) {
  const s  = Math.round(sec);
  const h  = Math.floor(s / 3600);
  const m  = Math.floor((s % 3600) / 60);
  const ss = s % 60;
  if (h) return `${h}:${String(m).padStart(2,'0')}:${String(ss).padStart(2,'0')}`;
  return `${m}:${String(ss).padStart(2,'0')}`;
}

// ── confirm ───────────────────────────────────────────────────────────────────

function confirmSplit() {
  const action = document.querySelector('input[name="split-action"]:checked')?.value || 'partition';
  if (action === 'partition') {
    _doSplitPartitionOnly();
    return;
  }
  const keepExported     = action === 'reanalyze-keep';
  const video            = AppState.videos.find(v => v.id === _splitVideoId);
  const clipCount        = video?.clip_count ?? _splitClipRanges.length;
  const exportedCount    = video?.exported ?? 0;
  const analyzedSegments = _splitPoints.length + 1 - _splitIgnored.size;
  const consequence = keepExported
    ? `This deletes ${plural(Math.max(0, clipCount - exportedCount), 'unexported clip')} (keeping ${plural(exportedCount, 'exported clip')}) and runs analysis fresh on ${plural(analyzedSegments, 'segment')}.`
    : `This deletes all ${plural(clipCount, 'existing clip')} and runs analysis fresh on ${plural(analyzedSegments, 'segment')}.`;
  showConfirm(
    'Delete clips and re-analyze?',
    consequence,
    'Delete & Re-analyze',
    () => _doSplitAndReanalyze(keepExported),
    true,
  );
}

async function _doSplitPartitionOnly() {
  if (!_splitVideoId) return;

  const btn = document.getElementById('btn-split-confirm');
  btn.disabled = true;
  btn.textContent = 'Splitting…';

  try {
    const res = await fetch(`/api/videos/${_splitVideoId}/split`, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({split_points: _splitPoints, segment_names: _splitNames, migrate_clips: true}),
    });
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      throw new Error(formatApiError(err));
    }
    const data = await res.json();
    showToast(
      `Recording split into ${plural(data.segment_ids.length, 'segment')} ` +
      ` -  ${plural(data.migrated_clips, 'clip')} moved over`
    );
    closeSplitEditor();
    await loadVideos();
  } catch (err) {
    showToast(`Split failed: ${err.message}`, 'error');
  } finally {
    btn.disabled = false;
    btn.textContent = 'Confirm';
  }
}

async function _doSplitAndReanalyze(keepExported) {
  if (!_splitVideoId) return;

  const parentVideo     = AppState.videos.find(v => v.id === _splitVideoId);
  const reanalyzeParams = await _reanalyzeParams(parentVideo);

  const btn = document.getElementById('btn-split-confirm');
  btn.disabled = true;
  btn.textContent = 'Splitting…';

  let segmentIds;
  try {
    const splitRes = await fetch(`/api/videos/${_splitVideoId}/split`, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({split_points: _splitPoints, segment_names: _splitNames}),
    });
    if (!splitRes.ok) {
      const err = await splitRes.json().catch(() => ({}));
      throw new Error(formatApiError(err));
    }
    segmentIds = (await splitRes.json()).segment_ids;
  } catch (err) {
    showToast(`Split failed: ${err.message}`, 'error');
    btn.disabled = false;
    btn.textContent = 'Confirm';
    return;
  }

  // Filter out ignored segments - they are split off but not analyzed
  const activeIds = segmentIds.filter((_, i) => !_splitIgnored.has(i));

  // Clear existing clips on each active segment before reanalyzing
  for (const segId of activeIds) {
    const clearRes = await fetch(`/api/videos/${segId}/clips/clear`, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({keep_exported: keepExported}),
    });
    if (!clearRes.ok) {
      showToast(`Failed to clear clips on segment ${segId}`, 'error');
      btn.disabled = false;
      btn.textContent = 'Confirm';
      return;
    }
  }

  closeSplitEditor();
  openLog();
  _reanalyzeSegmentsSequentially(activeIds, 0, reanalyzeParams);
}

async function _reanalyzeSegmentsSequentially(segmentIds, index, params) {
  if (index >= segmentIds.length) {
    loadVideos().then(() =>
      showToast(`Reanalysis complete - ${plural(segmentIds.length, 'segment')}`)
    );
    return;
  }
  await _waitWhileAnalyzePaused();
  const segId = segmentIds[index];
  fetch('/api/analyze/start', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({video_id: segId, ...params}),
  }).then(res => {
    if (!res.ok) {
      res.json().catch(() => ({})).then(err => {
        showToast(formatApiError(err) || `Failed to start analysis for segment ${segId}`, 'error');
      });
      return;
    }
    appendLog(`Analyzing segment ${index + 1}/${segmentIds.length}…`);
    streamSSE(
      '/api/analyze/events',
      () => { loadVideos(); _reanalyzeSegmentsSequentially(segmentIds, index + 1, params); },
      INGEST_STEPS,
      `Segment ${index + 1}/${segmentIds.length}`,
      false,
      null,
      true,
    );
  }).catch(err => showToast(netErrMsg(err), 'error'));
}

// ── pre-analysis split editor (inline in New Recording panel) ─────────────────

function onPreSplitToggle(checked) {
  if (checked && _splitDurationS > 0) {
    _openPreSplitEditor();
  } else {
    _closePreSplitEditor();
  }
}

function initPreSplitDuration(durationS) {
  _splitDurationS = durationS;
  _splitPoints    = [];
  _splitNames     = [];
  const section = document.getElementById('pre-split-section');
  if (section) section.style.display = '';
  const toggle = document.getElementById('pre-split-toggle');
  if (toggle && toggle.checked) _openPreSplitEditor();
}

function hidePreSplitSection() {
  _splitDurationS = 0;
  _splitPoints    = [];
  _splitNames     = [];
  const section = document.getElementById('pre-split-section');
  if (section) section.style.display = 'none';
  _closePreSplitEditor();
  const toggle = document.getElementById('pre-split-toggle');
  if (toggle) toggle.checked = false;
}

function _openPreSplitEditor() {
  _splitPoints = [];
  _splitNames  = [];
  const ed = document.getElementById('pre-split-editor');
  if (ed) ed.style.display = 'flex';
  _renderPreSplitEditor();
}

function _closePreSplitEditor() {
  const ed = document.getElementById('pre-split-editor');
  if (ed) ed.style.display = 'none';
}

function _rebuildPreSplitNames() {
  const count = _splitPoints.length + 1;
  _splitNames = Array.from({length: count}, (_, i) => `Part ${i + 1}`);
}

function _renderPreSplitEditor() {
  _renderPreSplitTimeline();
  _renderPreSplitSegmentList();
}

function _renderPreSplitTimeline() {
  const markers  = document.getElementById('pre-split-markers-layer');
  const segments = document.getElementById('pre-split-segments-layer');
  if (!markers || !_splitDurationS) return;

  const pts     = [0, ..._splitPoints, _splitDurationS];
  const palette = ['var(--accent)', 'var(--warning)', 'var(--green)', 'var(--red)'];
  segments.innerHTML = pts.slice(0, -1).map((start, i) => {
    const end      = pts[i + 1];
    const widthPct = ((end - start) / _splitDurationS * 100).toFixed(3);
    const col      = palette[i % palette.length];
    return `<div style="height:100%;width:${widthPct}%;background:${col};opacity:0.12;border-right:1px solid ${col}"></div>`;
  }).join('');

  markers.innerHTML = _splitPoints.map(p => {
    const pct = (p / _splitDurationS * 100).toFixed(3);
    const timeLabel = _fmtSplitTime(p);
    return `<div class="split-marker" style="position:absolute;left:${pct}%;top:0;bottom:0;width:10px;transform:translateX(-50%);cursor:ew-resize;pointer-events:auto;display:flex;align-items:stretch;justify-content:center"
                 title="${timeLabel} - drag to move"
                 onpointerdown="event.stopPropagation();_preSplitMarkerPointerDown(event,${p})">
               <div style="width:2px;background:var(--accent);border-radius:1px"></div>
               <button type="button" class="split-marker-x" title="Remove split point"
                       aria-label="Remove split point at ${timeLabel}"
                       onpointerdown="event.stopPropagation()"
                       onclick="event.stopPropagation();_removeSplitPoint(${p},true)">&#215;</button>
             </div>`;
  }).join('');
}

function _renderPreSplitSegmentList() {
  _renderSegmentList('pre-split-segment-list', _renderPreSplitEditor, false);
}

function preSplitTimelineClick(e) {
  if (!_splitDurationS || _dragActive) return;
  const bar  = document.getElementById('pre-split-timeline-bar');
  const rect = bar.getBoundingClientRect();
  const frac = (e.clientX - rect.left) / rect.width;
  const sec  = Math.round(frac * _splitDurationS * 10) / 10;

  if (sec <= 0 || sec >= _splitDurationS) return;

  const threshold = _splitDurationS * 0.005;
  if (_splitPoints.some(p => Math.abs(p - sec) <= threshold)) return;

  _splitPoints.push(sec);
  _splitPoints.sort((a, b) => a - b);
  _rebuildPreSplitNames();
  _renderPreSplitEditor();
}

function _preSplitMarkerPointerDown(e, sec) {
  e.stopPropagation();
  e.preventDefault();
  _dragMarkerSec = sec;
  _dragActive    = true;

  const bar = document.getElementById('pre-split-timeline-bar');

  function onMove(ev) {
    if (!_dragActive) return;
    const rect   = bar.getBoundingClientRect();
    const frac   = Math.max(0, Math.min(1, (ev.clientX - rect.left) / rect.width));
    const newSec = Math.round(frac * _splitDurationS * 10) / 10;
    if (newSec <= 0 || newSec >= _splitDurationS) return;
    const idx = _splitPoints.indexOf(_dragMarkerSec);
    if (idx !== -1) {
      _splitPoints[idx] = newSec;
      _dragMarkerSec    = newSec;
      _splitPoints.sort((a, b) => a - b);
      _renderPreSplitEditor();
    }
  }

  function onUp() {
    _dragActive    = false;
    _dragMarkerSec = null;
    window.removeEventListener('pointermove', onMove);
    window.removeEventListener('pointerup',   onUp);
    _rebuildPreSplitNames();
    _renderPreSplitEditor();
  }

  window.addEventListener('pointermove', onMove);
  window.addEventListener('pointerup',   onUp);
}

Object.assign(window, {
  isSplitEditorOpen, openSplitEditor, closeSplitEditor, _teardownSplitEditor,
  _splitSeekTo, _generateWaveform, _computeSuggestionPins, _setSplitZoom,
  _promoteSuggestionPin, _splitMarkerPointerDown, splitTimelineClick,
  _removeSplitPoint, _updateSplitPoint, _updateSplitConfirmState, _parseSplitTime,
  _toggleIgnored, _fmtSplitTime, _renderSplitEditor, _renderPreSplitEditor,
  confirmSplit, onPreSplitToggle, initPreSplitDuration, hidePreSplitSection,
  preSplitTimelineClick, _preSplitMarkerPointerDown,
});
})();

//# sourceURL=speakers.js
(function () {
// Feature-map - Speaker naming (code: Speaker; UI "Speakers" card).
//   API: routes/speakers.py · Tests: tests/ui/test_ui_speakers.py
// ── speaker naming ────────────────────────────────────────────────────────────
// Renders the "Speakers" card in the recording detail view and saves names.
// The card only appears when the recording has diarized speakers.

let _currentVideoId = null;

async function loadSpeakers(videoId) {
  const section = document.getElementById('speakers-section');
  if (!section) return;
  _currentVideoId = videoId;
  let speakers = [];
  try {
    speakers = await fetch(`/api/videos/${videoId}/speakers`).then(r => r.json());
  } catch (_) {
    speakers = [];
  }
  if (!Array.isArray(speakers) || speakers.length === 0) {
    section.innerHTML = '';
    return;
  }
  section.innerHTML = _renderSpeakersCard(speakers);
  section.querySelectorAll('.speaker-color-input').forEach(el => window.ColorPicker?.attach(el));
}

// A speaker with an inferred name the user hasn't accepted yet. Its name stays out of
// captions/excerpts (server gates display_name on `confirmed`) until accepted here.
function _isSuggestion(s) {
  return s.source === 'inferred' && !s.confirmed && !!s.name;
}

function _renderSpeakersCard(speakers) {
  const rows = speakers.map(s => {
    const play = (s.sample_start_ms !== null && s.sample_start_ms !== undefined)
      ? `<button class="speaker-play" data-sample-ms="${s.sample_start_ms}" data-sample-end-ms="${s.sample_end_ms === null ? '' : s.sample_end_ms}"
                 title="Play a sample of this voice" aria-label="Play a sample of Speaker ${s.display_index}">&#9654;</button>`
      : '';
    const sample = s.sample_text
      ? `<span class="speaker-sample" title="${escHtml(s.sample_text)}">&ldquo;${escHtml(truncate(s.sample_text, 60))}&rdquo;</span>`
      : '';
    // An unconfirmed suggestion keeps the input empty (so it doesn't look accepted)
    // and shows an Accept/Dismiss prompt instead.
    const inputValue = _isSuggestion(s) ? '' : escHtml(s.name || '');
    const suggestion = _isSuggestion(s)
      ? `<span class="speaker-suggestion" title="Suggested from how others address this voice - accept to apply it">
           Suggested: <strong>${escHtml(s.name)}</strong>
           <button class="speaker-accept" data-speaker-id="${s.id}" data-name="${escHtml(s.name)}"
                   title="Use this name">Accept</button>
           <button class="speaker-dismiss" data-speaker-id="${s.id}"
                   title="Discard this suggestion">Dismiss</button>
         </span>`
      : '';
    // A borderline voiceprint near-miss: this new voice was close to an existing
    // speaker but under the re-attach threshold, so we ask instead of guessing.
    const voiceMatch = (s.suggested_match_id && s.suggested_match_name)
      ? `<span class="speaker-voicematch" title="This voice is close to an existing speaker - confirm if it's the same person">
           Might be <strong>${escHtml(s.suggested_match_name)}</strong>
           (${Math.round((s.suggested_match_score || 0) * 100)}% voice match)
           <button class="speaker-samevoice" data-speaker-id="${s.id}" data-match-name="${escHtml(s.suggested_match_name)}"
                   title="Merge into ${escHtml(s.suggested_match_name)}">Same voice</button>
           <button class="speaker-diffvoice" data-speaker-id="${s.id}"
                   title="Keep as a separate speaker">Different voice</button>
         </span>`
      : '';
    // Project-wide identity (Person). A confirmed link shows a read-only line into the
    // People view; a named-but-unlinked speaker can be promoted; a cross-recording
    // near-miss offers a confirm/dismiss chip (mirrors the same-recording voiceMatch).
    // Promote only a CONFIRMED name: an unconfirmed inferred suggestion (s.name set,
    // s.confirmed false) would mint an unnamed Person, since the server carries only a
    // confirmed name across. Accept the suggestion first.
    const person = s.global_voice_id
      ? `<span class="speaker-person" title="This voice is part of a Person - one name across recordings">
           Person: <strong>${escHtml(s.person_name)}</strong>
           <button class="speaker-open-people" title="Manage people">Manage</button>
         </span>`
      : ((s.name && s.confirmed)
          ? `<button class="btn ghost speaker-promote" data-speaker-id="${s.id}"
                     title="Use this name across every recording of this voice">Promote to Person</button>`
          : '');
    const personMatch = (s.suggested_voice_id && s.suggested_voice_name)
      ? `<span class="speaker-voicematch" title="This voice matches a person from another recording - confirm if it's the same person">
           Might be <strong>${escHtml(s.suggested_voice_name)}</strong> from another recording
           (${Math.round((s.suggested_voice_score || 0) * 100)}% voice match)
           <button class="speaker-sameperson" data-speaker-id="${s.id}" data-match-name="${escHtml(s.suggested_voice_name)}"
                   title="Confirm this is the same person">Same person</button>
           <button class="speaker-diffperson" data-speaker-id="${s.id}"
                   title="Keep as a separate person">Not them</button>
         </span>`
      : '';
    return `
      <div class="speaker-row">
        ${play}
        <span class="speaker-tag">Speaker ${s.display_index}</span>
        <input class="speaker-color-input" type="color" data-speaker-id="${s.id}"
               value="${escHtml(s.color)}" title="Subtitle color for this speaker"
               aria-label="Subtitle color for Speaker ${s.display_index}">
        <input class="speaker-name-input" type="text" data-speaker-id="${s.id}"
               value="${inputValue}" placeholder="Add a name&hellip;"
               aria-label="Name for Speaker ${s.display_index}" maxlength="60">
        ${_speakerMergeHtml(s, speakers)}
        ${suggestion}
        ${voiceMatch}
        ${person}
        ${personMatch}
        ${sample}
      </div>`;
  }).join('');
  return collapsibleCard('speakers',
        `<span class="detail-card-title">Speakers</span>`, `
      <div class="speaker-list">${rows}</div>
      <div class="speaker-hint">Names show up in clip transcripts and captions. They stick even if you re-analyze this recording.</div>`,
      { actions: `<button class="btn ghost speaker-new-btn"
                title="Add a speaker diarization missed or merged, then move lines onto it from the transcript.">+ New speaker</button>
              <button class="btn ghost speaker-suggest-btn"
                title="Use the LLM to suggest names from how speakers address each other. Suggestions are never applied until you accept them.">Suggest names</button>` });
}

// A per-row "Merge into..." picker (whole-speaker merge). Only shown when there is at
// least one other speaker to merge into.
function _speakerMergeHtml(speaker, speakers) {
  const others = speakers.filter(o => o.id !== speaker.id);
  if (!others.length) return '';
  const opts = others.map(o =>
    `<option value="${o.id}">${escHtml(o.display_name)}</option>`).join('');
  return `<select class="speaker-merge-select" data-speaker-id="${speaker.id}"
                  aria-label="Merge Speaker ${speaker.display_index} into another speaker">
            <option value="">Merge into&hellip;</option>${opts}</select>`;
}

// Streams the LLM inference job as SSE (the transcript pass can be slow). Mirrors
// _doRegenSummaryAuto: log lines while it runs, then reload the card so the fresh
// suggestions render. The __DONE__ sentinel carries how many were applied.
function _suggestSpeakerNames() {
  if (!_currentVideoId) return;
  if (_blockedByAnalyze('suggest speaker names')) return;
  const videoId = _currentVideoId;
  const btn = document.querySelector('.speaker-suggest-btn');
  if (btn && btn.disabled) return;
  if (btn) { btn.disabled = true; btn.textContent = 'Suggesting…'; }
  openLog();
  _supersedeActiveStream();
  const resetBtn = () => {
    if (btn && document.body.contains(btn)) { btn.disabled = false; btn.textContent = 'Suggest names'; }
  };
  let hadError = false;
  const handle = _openSSE(
    `/api/videos/${videoId}/infer-speaker-names`,
    data => {
      if (typeof data === 'string' && data.startsWith('[Error')) hadError = true;
      appendLog(String(data));
    },
    async msg => {
      _clearActiveStream(handle);
      resetBtn();
      if (hadError) { showToast('Name suggestion failed - check log for details', 'error'); return; }
      const n = (msg && typeof msg === 'object' && msg.suggested) || 0;
      showToast(n > 0
        ? `${plural(n, 'name suggestion')} - review and accept`
        : 'No names could be inferred from the transcript');
      await loadSpeakers(videoId);
    },
    errMsg => {
      _clearActiveStream(handle);
      resetBtn();
      showToast(`Name suggestion failed - ${errMsg}`, 'error');
    },
  );
  _setActiveStream(handle, resetBtn);
}

// Play a short sample of a speaker's voice by seeking the recording's own video
// player - no separate audio route needed. Stops after the sample segment (capped
// at 6s so a long turn doesn't play in full).
let _sampleStopTimer = null;
function _playSpeakerSample(startMs, endMs) {
  const video = document.querySelector('#player-area video');
  if (!video) return;
  if (_sampleStopTimer) { clearTimeout(_sampleStopTimer); _sampleStopTimer = null; }
  video.currentTime = (startMs || 0) / 1000;
  const playAttempt = video.play();
  if (playAttempt && playAttempt.catch) playAttempt.catch(() => {});
  const spanMs = (endMs ? endMs - startMs : 4000);
  const durationMs = Math.min(6000, Math.max(1500, spanMs));
  _sampleStopTimer = setTimeout(() => { video.pause(); _sampleStopTimer = null; }, durationMs);
}

async function _saveSpeakerName(speakerId, name) {
  try {
    const res = await fetch(`/api/speakers/${speakerId}`, {
      method: 'PUT',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({name}),
    });
    if (!res.ok) {
      showToast('Could not save speaker name', 'error');
      return;
    }
    const updated = await res.json();
    const input = document.querySelector(`.speaker-name-input[data-speaker-id="${speakerId}"]`);
    if (input && !updated.is_named) input.value = '';
    showToast(updated.is_named ? `Speaker named ${updated.display_name}` : 'Name cleared');
    // Refresh the open clip so its transcript reflects the new name, and the
    // recording's full-transcript panel if it's expanded.
    if (AppState.activeClipId) selectClip(AppState.activeClipId);
    if (_currentVideoId) reloadVideoTranscriptIfOpen(_currentVideoId);
  } catch (_) {
    showToast('Could not save speaker name', 'error');
  }
}

async function _saveSpeakerColor(speakerId, color) {
  try {
    const res = await fetch(`/api/speakers/${speakerId}`, {
      method: 'PUT',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({color}),
    });
    if (!res.ok) {
      showToast('Could not save speaker color', 'error');
      return;
    }
    // Refresh the open clip's transcript so its speaker labels pick up the new color.
    if (AppState.activeClipId) selectClip(AppState.activeClipId);
    if (_currentVideoId) reloadVideoTranscriptIfOpen(_currentVideoId);
  } catch (_) {
    showToast('Could not save speaker color', 'error');
  }
}

// Accept (name = the suggestion) or dismiss (name = "") an inferred suggestion.
// Both confirm the speaker server-side, so the suggestion prompt clears on reload.
async function _resolveSuggestion(speakerId, name) {
  try {
    const res = await fetch(`/api/speakers/${speakerId}`, {
      method: 'PUT',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({name}),
    });
    if (!res.ok) { showToast('Could not update speaker', 'error'); return; }
    const updated = await res.json();
    showToast(updated.is_named ? `Speaker named ${updated.display_name}` : 'Suggestion dismissed');
    if (_currentVideoId) await loadSpeakers(_currentVideoId);
    if (AppState.activeClipId) selectClip(AppState.activeClipId);
    if (_currentVideoId) reloadVideoTranscriptIfOpen(_currentVideoId);
  } catch (_) {
    showToast('Could not update speaker', 'error');
  }
}

// Confirm ("Same voice" → merge into the suggested speaker) or dismiss
// ("Different voice" → keep separate) a borderline voiceprint suggestion.
async function _resolveVoiceMatch(speakerId, sameVoice, matchName) {
  const endpoint = sameVoice ? 'confirm-match' : 'reject-match';
  try {
    const res = await fetch(`/api/speakers/${speakerId}/${endpoint}`, { method: 'POST' });
    if (!res.ok) { showToast('Could not update speaker', 'error'); return; }
    showToast(sameVoice
      ? `Merged into ${matchName || 'the suggested speaker'}`
      : 'Kept as a separate speaker');
    if (_currentVideoId) await loadSpeakers(_currentVideoId);
    if (AppState.activeClipId) selectClip(AppState.activeClipId);
    if (_currentVideoId) reloadVideoTranscriptIfOpen(_currentVideoId);
  } catch (_) {
    showToast('Could not update speaker', 'error');
  }
}

// Add a fresh unnamed speaker to this recording, for a voice diarization missed or
// merged. Lines are moved onto it from the transcript or via "Merge into...".
async function _createSpeaker() {
  if (!_currentVideoId) return;
  try {
    const res = await fetch(`/api/videos/${_currentVideoId}/speakers`, {
      method: 'POST', headers: {'Content-Type': 'application/json'}, body: '{}',
    });
    if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))));
    const speaker = await res.json();
    showToast(`Added ${speaker.display_name} - name it or move lines onto it`);
    await loadSpeakers(_currentVideoId);
  } catch (err) {
    showToast(`Could not add a speaker: ${err.message}`, 'error');
  }
}

// Whole-speaker merge: move every line of one speaker onto another. Confirmed first
// because it deletes the source speaker.
async function _mergeSpeakerInto(sourceId, targetId, targetName) {
  showConfirm(
    'Merge speakers?',
    `Move all of this speaker's lines onto ${targetName || 'the other speaker'}? `
      + 'The merged speaker is removed. This affects clip transcripts and exports.',
    'Merge',
    async () => {
      try {
        const res = await fetch(`/api/speakers/${sourceId}/merge-into/${targetId}`, {method: 'POST'});
        if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))));
        showToast(`Merged into ${targetName || 'the other speaker'}`);
        if (_currentVideoId) await loadSpeakers(_currentVideoId);
        if (AppState.activeClipId) selectClip(AppState.activeClipId);
        if (_currentVideoId) reloadVideoTranscriptIfOpen(_currentVideoId);
      } catch (err) {
        showToast(`Could not merge: ${err.message}`, 'error');
      }
    },
  );
  if (_currentVideoId) await loadSpeakers(_currentVideoId);  // reset the select either way
}

// Promote a named speaker into a project-wide Person so the name applies across every
// recording of this voice. Reloads the card so the "Person: X" line appears.
async function _promoteToPerson(speakerId) {
  try {
    const res = await fetch('/api/voices', {
      method: 'POST', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({speaker_id: speakerId}),
    });
    if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))));
    const voice = await res.json();
    showToast(`${voice.display_name} is now a Person - name applies across recordings`);
    if (_currentVideoId) await loadSpeakers(_currentVideoId);
  } catch (err) {
    showToast(`Could not promote to Person: ${err.message}`, 'error');
  }
}

// Confirm ("Same person" -> confirm-voice) or dismiss ("Not them" -> reject-voice) a
// cross-recording Person suggestion. Confirming links this recording's voice to the
// Person, so its captions/excerpts pick up the Person's name.
async function _resolvePersonMatch(speakerId, samePerson, matchName) {
  const endpoint = samePerson ? 'confirm-voice' : 'reject-voice';
  try {
    const res = await fetch(`/api/speakers/${speakerId}/${endpoint}`, {method: 'POST'});
    if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))));
    showToast(samePerson
      ? `Linked to ${matchName || 'that person'}`
      : 'Kept as a separate person');
    if (_currentVideoId) await loadSpeakers(_currentVideoId);
    if (AppState.activeClipId) selectClip(AppState.activeClipId);
    if (_currentVideoId) reloadVideoTranscriptIfOpen(_currentVideoId);
  } catch (err) {
    showToast(`Could not update: ${err.message}`, 'error');
  }
}

// Event delegation on the persistent #detail element (its innerHTML is replaced
// each render, so per-row handlers would be lost - the container listener isn't).
document.addEventListener('DOMContentLoaded', () => {
  const detail = document.getElementById('detail');
  if (!detail) return;
  detail.addEventListener('click', e => {
    const playBtn = e.target.closest && e.target.closest('.speaker-play');
    if (playBtn) {
      const endRaw = playBtn.dataset.sampleEndMs;
      _playSpeakerSample(
        parseInt(playBtn.dataset.sampleMs, 10),
        endRaw ? parseInt(endRaw, 10) : null,
      );
      return;
    }
    if (e.target.closest && e.target.closest('.speaker-suggest-btn')) {
      _suggestSpeakerNames();
      return;
    }
    if (e.target.closest && e.target.closest('.speaker-new-btn')) {
      _createSpeaker();
      return;
    }
    const acceptBtn = e.target.closest && e.target.closest('.speaker-accept');
    if (acceptBtn) {
      _resolveSuggestion(parseInt(acceptBtn.dataset.speakerId, 10), acceptBtn.dataset.name);
      return;
    }
    const dismissBtn = e.target.closest && e.target.closest('.speaker-dismiss');
    if (dismissBtn) {
      _resolveSuggestion(parseInt(dismissBtn.dataset.speakerId, 10), '');
      return;
    }
    const sameVoiceBtn = e.target.closest && e.target.closest('.speaker-samevoice');
    if (sameVoiceBtn) {
      _resolveVoiceMatch(parseInt(sameVoiceBtn.dataset.speakerId, 10), true, sameVoiceBtn.dataset.matchName);
      return;
    }
    const diffVoiceBtn = e.target.closest && e.target.closest('.speaker-diffvoice');
    if (diffVoiceBtn) {
      _resolveVoiceMatch(parseInt(diffVoiceBtn.dataset.speakerId, 10), false);
      return;
    }
    const promoteBtn = e.target.closest && e.target.closest('.speaker-promote');
    if (promoteBtn) {
      _promoteToPerson(parseInt(promoteBtn.dataset.speakerId, 10));
      return;
    }
    if (e.target.closest && e.target.closest('.speaker-open-people')) {
      if (window.openPeopleView) openPeopleView();
      return;
    }
    const samePersonBtn = e.target.closest && e.target.closest('.speaker-sameperson');
    if (samePersonBtn) {
      _resolvePersonMatch(parseInt(samePersonBtn.dataset.speakerId, 10), true, samePersonBtn.dataset.matchName);
      return;
    }
    const diffPersonBtn = e.target.closest && e.target.closest('.speaker-diffperson');
    if (diffPersonBtn) {
      _resolvePersonMatch(parseInt(diffPersonBtn.dataset.speakerId, 10), false);
    }
  });
  detail.addEventListener('change', e => {
    const nameInput = e.target.closest && e.target.closest('.speaker-name-input');
    if (nameInput) { _saveSpeakerName(parseInt(nameInput.dataset.speakerId, 10), nameInput.value.trim()); return; }
    const colorInput = e.target.closest && e.target.closest('.speaker-color-input');
    if (colorInput) { _saveSpeakerColor(parseInt(colorInput.dataset.speakerId, 10), colorInput.value); return; }
    const mergeSelect = e.target.closest && e.target.closest('.speaker-merge-select');
    if (mergeSelect && mergeSelect.value) {
      _mergeSpeakerInto(parseInt(mergeSelect.dataset.speakerId, 10), parseInt(mergeSelect.value, 10),
                        mergeSelect.options[mergeSelect.selectedIndex].text);
    }
  });
  detail.addEventListener('keydown', e => {
    const input = e.target.closest && e.target.closest('.speaker-name-input');
    if (input && e.key === 'Enter') { e.preventDefault(); input.blur(); }
  });
});

Object.assign(window, { loadSpeakers });
})();

//# sourceURL=voices.js
(function () {
// Feature-map - People / project-wide speaker identity (code: ProjectVoice; UI "Person"/"People").
//   API: routes/voices.py · Tests: tests/ui/test_ui_voices.py
// ── People view (PanelNav takeover) ────────────────────────────────────────────
// A project-level view listing every Person (a voice named once, applied across all
// recordings). Lists each Person's member recordings, pending cross-recording
// suggestions (confirm/dismiss inline), and rename/recolor/merge/split. Naming a
// Person here flows to every linked recording's captions/excerpts/exports because the
// server resolves display_name through the linked voice.

function isPeopleOpen() {
  return PanelNav.isOpen('people');
}

function openPeopleView() {
  PanelNav.open({
    id: 'people',
    title: 'People',
    render: container => _peopleMount(container),
    isDirty: () => false,
    onClose: () => {},
  });
}

function _peopleMount(container) {
  container.innerHTML = `
    <div class="people-header">
      <p class="people-intro">A <strong>Person</strong> is one voice named once and applied across
        every recording. Name a Person here and the name shows up wherever that voice speaks.</p>
      <button class="btn ghost" id="people-backfill-btn"
              title="Group the speakers you have already named across recordings into people. Nothing is renamed - results appear here for you to review.">Find people across recordings</button>
    </div>
    <div id="people-list"><div class="transcript-empty">Loading&hellip;</div></div>`;
  container.addEventListener('click', _onPeopleClick);
  container.addEventListener('change', _onPeopleChange);
  _loadPeople();
}

let _peopleCache = [];
let _charactersCache = [];

async function _loadPeople() {
  const list = document.getElementById('people-list');
  if (!list) return;
  try {
    const [voices, chars] = await Promise.all([
      fetch('/api/voices').then(r => r.json()),
      fetch('/api/characters').then(r => r.json()).catch(() => []),
    ]);
    _peopleCache = Array.isArray(voices) ? voices : [];
    _charactersCache = Array.isArray(chars) ? chars : [];
    _renderPeople();
  } catch (_) {
    list.innerHTML = '<div class="transcript-empty">Could not load people.</div>';
  }
}

function _renderPeople() {
  const list = document.getElementById('people-list');
  if (!list) return;
  if (!_peopleCache.length) {
    list.innerHTML = `<div class="transcript-empty">No people yet. Open a recording's
      <strong>Speakers</strong> panel and choose <strong>Promote to Person</strong> on a named
      speaker to start.</div>`;
    return;
  }
  list.innerHTML = _peopleCache.map(_personCardHtml).join('');
  list.querySelectorAll('.voice-color-input').forEach(el => window.ColorPicker?.attach(el));
}

function _personCardHtml(voice) {
  return `
    <div class="person-card" data-voice-id="${voice.id}">
      <div class="person-head">
        <input class="voice-color-input" type="color" data-voice-id="${voice.id}"
               value="${escHtml(voice.color)}" title="Caption color for this person"
               aria-label="Caption color for ${escHtml(voice.display_name)}">
        <input class="voice-name-input" type="text" data-voice-id="${voice.id}"
               value="${escHtml(voice.name || '')}" placeholder="Name this person&hellip;"
               aria-label="Name for ${escHtml(voice.display_name)}" maxlength="60">
        <span class="person-count">${plural(voice.member_count, 'recording')}</span>
        ${_mergeControlHtml(voice)}
      </div>
      ${_membersHtml(voice)}
      ${_characterControlHtml(voice)}
      ${_suggestionsHtml(voice)}
    </div>`;
}

// Optional overlay: link this Person to a world-context Character (lore + scoring
// boost). A project with no characters and no existing link shows no picker at all,
// so a zero-context workflow is visually unchanged.
function _characterControlHtml(voice) {
  const linkedId = voice.character ? voice.character.id : null;
  if (!_charactersCache.length && linkedId == null) return '';
  return `
    <div class="person-character">
      <label class="person-character-label" for="voice-char-${voice.id}">Character</label>
      <select class="voice-character-select" id="voice-char-${voice.id}" data-voice-id="${voice.id}"
              aria-label="World-context character for ${escHtml(voice.display_name)}">
        ${_characterOptions(voice.character)}
      </select>
    </div>`;
}

function _characterOptions(linked) {
  const selectedId = linked ? linked.id : null;
  const byContext = new Map();
  for (const c of _charactersCache) {
    const key = c.context_name || c.context_slug;
    if (!byContext.has(key)) byContext.set(key, []);
    byContext.get(key).push(c);
  }
  let html = `<option value="">No character</option>`;
  // If the linked character isn't in the loaded list (e.g. /api/characters failed to
  // load), still render it as the selected option from the Person's own data - otherwise
  // an existing link shows as "No character", which a subsequent save would clear.
  if (selectedId != null && !_charactersCache.some(c => c.id === selectedId)) {
    html += `<option value="${selectedId}" selected>${escHtml(linked.name || 'Linked character')}</option>`;
  }
  for (const [ctxName, chars] of byContext) {
    html += `<optgroup label="${escHtml(ctxName)}">`
          + chars.map(c => `<option value="${c.id}"${c.id === selectedId ? ' selected' : ''}>${escHtml(c.name)}</option>`).join('')
          + `</optgroup>`;
  }
  return html;
}

function _mergeControlHtml(voice) {
  const others = _peopleCache.filter(v => v.id !== voice.id);
  if (!others.length) return '';
  const opts = others.map(v =>
    `<option value="${v.id}">${escHtml(v.display_name)}</option>`).join('');
  return `
    <select class="voice-merge-select" data-voice-id="${voice.id}"
            aria-label="Merge another person into ${escHtml(voice.display_name)}">
      <option value="">Merge in&hellip;</option>${opts}
    </select>`;
}

function _membersHtml(voice) {
  if (!voice.members.length) {
    return '<div class="person-empty">No recordings linked yet.</div>';
  }
  const rows = voice.members.map(m => `
    <div class="person-member">
      <span class="person-member-name">${escHtml(m.display_name)}</span>
      <span class="person-member-file" title="${escHtml(m.video_filename)}">${escHtml(m.video_filename)}</span>
      <button class="btn ghost voice-detach-btn" data-voice-id="${voice.id}" data-speaker-id="${m.speaker_id}"
              title="Remove this recording's voice from ${escHtml(voice.display_name)}">Remove</button>
    </div>`).join('');
  return `<div class="person-members">${rows}</div>`;
}

function _suggestionsHtml(voice) {
  if (!voice.suggestions || !voice.suggestions.length) return '';
  const rows = voice.suggestions.map(s => `
    <div class="person-suggestion">
      <span class="person-member-file" title="${escHtml(s.video_filename)}">${escHtml(s.video_filename)}</span>
      <span class="person-suggestion-score">${Math.round((s.score || 0) * 100)}% voice match</span>
      <button class="btn primary voice-confirm-btn" data-speaker-id="${s.speaker_id}"
              title="Confirm this recording's voice is ${escHtml(voice.display_name)}">Same person</button>
      <button class="btn ghost voice-reject-btn" data-speaker-id="${s.speaker_id}"
              title="Not the same person">Not them</button>
    </div>`).join('');
  return `
    <div class="person-suggestions">
      <div class="person-suggestions-head">Possible matches from other recordings</div>
      ${rows}
    </div>`;
}

function _onPeopleClick(e) {
  if (e.target.closest('#people-backfill-btn')) {
    _backfillPeople(e.target.closest('#people-backfill-btn'));
    return;
  }
  const detach = e.target.closest('.voice-detach-btn');
  if (detach) {
    _splitPerson(parseInt(detach.dataset.voiceId, 10), parseInt(detach.dataset.speakerId, 10));
    return;
  }
  const confirmBtn = e.target.closest('.voice-confirm-btn');
  if (confirmBtn) {
    _resolveSuggestion(parseInt(confirmBtn.dataset.speakerId, 10), true);
    return;
  }
  const rejectBtn = e.target.closest('.voice-reject-btn');
  if (rejectBtn) {
    _resolveSuggestion(parseInt(rejectBtn.dataset.speakerId, 10), false);
  }
}

function _onPeopleChange(e) {
  const nameInput = e.target.closest('.voice-name-input');
  if (nameInput) {
    _saveVoice(parseInt(nameInput.dataset.voiceId, 10), {name: nameInput.value.trim()});
    return;
  }
  const colorInput = e.target.closest('.voice-color-input');
  if (colorInput) {
    _saveVoice(parseInt(colorInput.dataset.voiceId, 10), {color: colorInput.value});
    return;
  }
  const mergeSelect = e.target.closest('.voice-merge-select');
  if (mergeSelect && mergeSelect.value) {
    _mergePerson(parseInt(mergeSelect.dataset.voiceId, 10), parseInt(mergeSelect.value, 10));
    return;
  }
  const charSelect = e.target.closest('.voice-character-select');
  if (charSelect) {
    _setPersonCharacter(parseInt(charSelect.dataset.voiceId, 10),
      charSelect.value ? parseInt(charSelect.value, 10) : null);
  }
}

async function _setPersonCharacter(voiceId, characterId) {
  try {
    const res = await fetch(`/api/voices/${voiceId}/character`, {
      method: 'POST', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({character_id: characterId}),
    });
    if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))));
    showToast(characterId ? 'Character linked' : 'Character unlinked');
    await _loadPeople();
  } catch (err) {
    showToast(`Could not update: ${err.message}`, 'error');
  }
}

async function _saveVoice(voiceId, body) {
  try {
    const res = await fetch(`/api/voices/${voiceId}`, {
      method: 'PUT', headers: {'Content-Type': 'application/json'}, body: JSON.stringify(body),
    });
    if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))));
    const updated = await res.json();
    if ('name' in body) showToast(updated.is_named ? `Named ${updated.display_name}` : 'Name cleared');
    await _loadPeople();
    _syncOpenRecording();
  } catch (err) {
    showToast(`Could not save: ${err.message}`, 'error');
  }
}

async function _mergePerson(targetId, otherId) {
  const other = _peopleCache.find(v => v.id === otherId);
  const target = _peopleCache.find(v => v.id === targetId);
  showConfirm(
    'Merge people?',
    `Merge ${other ? other.display_name : 'that person'} into ${target ? target.display_name : 'this person'}? `
      + 'Their recordings move over and the other person is removed.',
    'Merge',
    async () => {
      try {
        const res = await fetch(`/api/voices/${targetId}/merge`, {
          method: 'POST', headers: {'Content-Type': 'application/json'},
          body: JSON.stringify({other_id: otherId}),
        });
        if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))));
        showToast('People merged');
        await _loadPeople();
        _syncOpenRecording();
      } catch (err) {
        showToast(`Could not merge: ${err.message}`, 'error');
      }
    },
  );
  await _loadPeople();  // reset the select whether or not they confirm
}

async function _splitPerson(voiceId, speakerId) {
  try {
    const res = await fetch(`/api/voices/${voiceId}/split`, {
      method: 'POST', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({speaker_id: speakerId}),
    });
    if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))));
    showToast('Recording removed from this person');
    await _loadPeople();
    _syncOpenRecording();
  } catch (err) {
    showToast(`Could not update: ${err.message}`, 'error');
  }
}

async function _resolveSuggestion(speakerId, same) {
  const endpoint = same ? 'confirm-voice' : 'reject-voice';
  try {
    const res = await fetch(`/api/speakers/${speakerId}/${endpoint}`, {method: 'POST'});
    if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))));
    showToast(same ? 'Confirmed - same person' : 'Kept separate');
    await _loadPeople();
    _syncOpenRecording();
  } catch (err) {
    showToast(`Could not update: ${err.message}`, 'error');
  }
}

async function _backfillPeople(btn) {
  if (btn) { btn.disabled = true; btn.textContent = 'Finding…'; }
  try {
    const res = await fetch('/api/voices/backfill', {method: 'POST'});
    if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))));
    const data = await res.json();
    showToast(data.created
      ? `Found ${plural(data.created, 'person')} to review`
      : 'No new people found across your recordings');
    await _loadPeople();
    _syncOpenRecording();
  } catch (err) {
    showToast(`Could not find people: ${err.message}`, 'error');
  } finally {
    if (btn && document.body.contains(btn)) { btn.disabled = false; btn.textContent = 'Find people across recordings'; }
  }
}

// A People-view change can alter a display name in the currently open recording -
// refresh its Speakers card, transcript, and clip so it doesn't show a stale name.
function _syncOpenRecording() {
  const videoId = AppState.activeVideoId;
  if (videoId != null && window.loadSpeakers) loadSpeakers(videoId);
  if (videoId != null && window.reloadVideoTranscriptIfOpen) reloadVideoTranscriptIfOpen(videoId);
  if (AppState.activeClipId != null && window.selectClip) selectClip(AppState.activeClipId);
}

Object.assign(window, {openPeopleView, isPeopleOpen});
})();

//# sourceURL=transcript.js
(function () {
// Feature-map - Transcript views + click-to-edit captions (code: TranscriptSegment).
//   API: routes/videos.py, routes/scoring.py · Tests: tests/ui/test_ui_transcript.py, tests/integration/test_transcript_edit.py
// ── timed transcript views ────────────────────────────────────────────────────
// Per-line transcript for a clip (clip-relative time) and for a whole recording
// (absolute time), each line with a ▶ that seeks the visible player. Works for
// diarized transcripts (speaker name shown when it changes) and plain ones
// (each caption segment becomes its own line). Each line's text is click-to-edit
// so mis-heard names/jargon can be fixed before re-scoring.

function seekPlayerTo(seconds) {
  const video = document.querySelector('#player-area video');
  if (!video) return;
  video.currentTime = Math.max(0, seconds || 0);
  const attempt = video.play();
  if (attempt && attempt.catch) attempt.catch(() => {});
}

function _clock(ms) {
  const total = Math.max(0, Math.round((ms || 0) / 1000));
  const s = total % 60;
  const m = Math.floor(total / 60) % 60;
  const h = Math.floor(total / 3600);
  const mm = String(m).padStart(2, '0');
  const ss = String(s).padStart(2, '0');
  return h ? `${h}:${mm}:${ss}` : `${m}:${ss}`;
}

// opts.seekOffsetS is added to each line's play target - 0 for a clip (its player
// is trimmed to the clip) and the segment start for a split recording (whose player
// streams the untrimmed parent file). opts.videoId enables the per-line speaker
// control (rename / reassign); omit it to render a read-only transcript. opts.readOnly
// suppresses the click-to-edit-caption affordance even when a line carries a seg_id -
// used by the manual clip picker, where a line click selects a range instead.
function renderTranscriptLines(lines, opts) {
  opts = opts || {};
  const offsetS = opts.seekOffsetS || 0;
  const videoId = opts.videoId;
  const readOnly = !!opts.readOnly;
  if (!Array.isArray(lines) || !lines.length) {
    return '<div class="transcript-empty">No transcript available.</div>';
  }
  let prevSpeaker = null;
  const rows = lines.map(line => {
    const showSpeaker = line.speaker && line.speaker !== prevSpeaker;
    prevSpeaker = line.speaker;
    const colorAttr = line.color ? ` style="color:${escHtml(line.color)}"` : '';
    const speaker = showSpeaker
      ? `<div class="tline-speaker"${colorAttr}>${escHtml(line.speaker)}</div>`
      : '';
    const clock = _clock(line.start_ms);
    const seekS = (line.start_ms || 0) / 1000 + offsetS;
    const editable = !readOnly && line.seg_id != null;
    const editAttrs = editable
      ? ` data-seg-id="${line.seg_id}" role="button" tabindex="0" title="Click to edit caption"`
      : '';
    // display_color is always set server-side; var(--muted) is a defensive fallback so
    // no hardcoded hex ever ships (no-hardcoded-colors rule).
    const dotColor = line.color ? escHtml(line.color) : 'var(--muted)';
    const spkName = line.speaker ? escHtml(line.speaker) : 'this speaker';
    const spk = (videoId != null && line.speaker_id != null)
      ? `<button class="tline-spk${line.speaker_edited ? ' edited' : ''}"
                 data-seg-id="${line.seg_id}" data-speaker-id="${line.speaker_id}" data-video-id="${videoId}"
                 title="${line.speaker_edited ? 'Reassigned by you - ' : ''}${spkName} - click to change or rename"
                 aria-label="Change or rename speaker">
           <span class="tline-spk-dot" style="background:${dotColor}"></span></button>`
      : '';
    return `${speaker}<div class="tline" data-start-ms="${line.start_ms || 0}" data-end-ms="${line.end_ms || 0}"
      data-seg-id="${line.seg_id != null ? line.seg_id : ''}" data-speaker-id="${line.speaker_id != null ? line.speaker_id : ''}">
      <button class="tline-play" data-seek-s="${seekS}"
              title="Jump to ${clock}" aria-label="Play from ${clock}">&#9654;</button>
      <span class="tline-time">${clock}</span>
      ${spk}
      <span class="tline-text${editable ? ' editable' : ''}"${editAttrs}>${escHtml(line.text)}</span>
    </div>`;
  }).join('');
  return `<div class="transcript-lines">${rows}</div>`;
}

async function loadClipTranscript(clipId) {
  const el = document.getElementById('clip-transcript-view');
  if (!el) return;
  try {
    const data = await fetch(`/api/clips/${clipId}/transcript`).then(r => r.json());
    if (data.lines && data.lines.length) {
      el.innerHTML = renderTranscriptLines(data.lines, {videoId: AppState.activeVideoId});
    }
    // else: keep the plain excerpt already rendered as a fallback.
  } catch (_) {
    // Leave the excerpt fallback in place on error.
  }
}

let _videoTranscriptLoadedFor = null;
async function loadVideoTranscript(videoId) {
  const el = document.getElementById('video-transcript-view');
  if (!el) return;
  // Skip the fetch only when this video's transcript is still rendered. A bare
  // videoId match isn't enough: renderVideoDetail rebuilds #detail, leaving a
  // fresh empty #video-transcript-view while the flag still points here - that
  // combination is what left the panel silently blank on reopen.
  if (_videoTranscriptLoadedFor === videoId && el.childElementCount > 0) return;
  el.innerHTML = '<div class="transcript-empty">Loading…</div>';
  try {
    const data = await fetch(`/api/videos/${videoId}/transcript`).then(r => r.json());
    _resetLineSelect();
    const tools = (data.lines && data.lines.length) ? _lineMoveToolbar() : '';
    el.innerHTML = tools + renderTranscriptLines(data.lines, {seekOffsetS: data.seek_offset_s || 0, videoId});
    _videoTranscriptLoadedFor = videoId;
  } catch (_) {
    el.innerHTML = '<div class="transcript-empty">Could not load transcript.</div>';
  }
}

// ── multi-select "move lines to a speaker" (bulk split) ────────────────────────
// A selection mode on the full-recording transcript: pick several lines, then move
// them onto another speaker, a new one, or Unassigned in a single bulk call per source
// speaker (rebuilds excerpts + refreshes sidecars once). Only the recording transcript
// gets this - clip transcripts render without the toolbar.
const _lineMove = { videoId: null, active: false, selected: new Set() };

function _resetLineSelect() {
  _lineMove.active = false;
  _lineMove.selected = new Set();
}

function _lineMoveToolbar() {
  return `<div class="tx-move-bar" id="tx-move-bar">
    <button class="btn ghost tx-move-toggle" title="Select several lines and move them onto another speaker">Select lines to move</button>
  </div>`;
}

function _currentTranscriptVideoId() {
  const card = document.getElementById('video-transcript-details');
  return card ? parseInt(card.dataset.videoId, 10) : null;
}

async function _enterLineSelect() {
  _lineMove.videoId = _currentTranscriptVideoId();
  if (_lineMove.videoId == null) return;
  _lineMove.active = true;
  _lineMove.selected = new Set();
  document.getElementById('video-transcript-view')?.classList.add('select-mode');
  await _renderMoveBar();
}

function _exitLineSelect() {
  _resetLineSelect();
  const view = document.getElementById('video-transcript-view');
  if (view) {
    view.classList.remove('select-mode');
    view.querySelectorAll('.tline-selected').forEach(r => r.classList.remove('tline-selected'));
  }
  _renderMoveBar();
}

async function _renderMoveBar() {
  const bar = document.getElementById('tx-move-bar');
  if (!bar) return;
  if (!_lineMove.active) {
    bar.innerHTML = `<button class="btn ghost tx-move-toggle" title="Select several lines and move them onto another speaker">Select lines to move</button>`;
    return;
  }
  const speakers = await _getVideoSpeakers(_lineMove.videoId);
  const opts = speakers.map(s => `<option value="${s.id}">${escHtml(s.display_name)}</option>`).join('');
  bar.innerHTML = `
    <span class="tx-move-count">${plural(_lineMove.selected.size, 'line')} selected</span>
    <select class="tx-move-target" aria-label="Move selected lines to">
      <option value="">Move to&hellip;</option>${opts}
      <option value="__new__">+ New speaker</option>
      <option value="__none__">Unassigned</option>
    </select>
    <button class="btn ghost tx-move-cancel">Cancel</button>`;
}

function _toggleLineSelection(row) {
  const segId = parseInt(row.dataset.segId, 10);
  if (!segId || !row.dataset.speakerId) return;  // only attributed lines can be moved
  if (_lineMove.selected.has(segId)) {
    _lineMove.selected.delete(segId);
    row.classList.remove('tline-selected');
  } else {
    _lineMove.selected.add(segId);
    row.classList.add('tline-selected');
  }
  const count = document.querySelector('.tx-move-count');
  if (count) count.textContent = `${plural(_lineMove.selected.size, 'line')} selected`;
}

async function _moveSelectedLines(value) {
  const segIds = [..._lineMove.selected];
  const videoId = _lineMove.videoId;
  if (!segIds.length) { showToast('Select some lines first', 'warning'); await _renderMoveBar(); return; }
  try {
    const target = await _resolveMoveTarget(value, videoId);
    // The bulk endpoint moves lines of ONE source speaker, so group the selection by
    // each line's current speaker and call once per group.
    const groups = {};
    for (const segId of segIds) {
      const row = document.querySelector(`#video-transcript-view .tline[data-seg-id="${segId}"]`);
      const src = row && row.dataset.speakerId;
      if (src && parseInt(src, 10) !== target) (groups[src] = groups[src] || []).push(segId);
    }
    let moved = 0;
    for (const [src, ids] of Object.entries(groups)) {
      const res = await fetch(`/api/speakers/${src}/reassign-segments`, {
        method: 'PUT', headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({seg_ids: ids, target_speaker_id: target}),
      });
      if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))));
      moved += (await res.json()).reassigned;
    }
    showToast(moved ? `Moved ${plural(moved, 'line')}` : 'Those lines were already on that speaker');
    _exitLineSelect();
    _refreshAfterSpeakerChange(videoId, null);
  } catch (err) {
    showToast(`Could not move lines: ${err.message}`, 'error');
    await _renderMoveBar();
  }
}

async function _resolveMoveTarget(value, videoId) {
  if (value === '__none__') return null;
  if (value !== '__new__') return parseInt(value, 10);
  const res = await fetch(`/api/videos/${videoId}/speakers`, {
    method: 'POST', headers: {'Content-Type': 'application/json'}, body: '{}',
  });
  if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))));
  delete _videoSpeakersCache[videoId];
  return (await res.json()).id;
}

// Called after a speaker rename/recolor so the open recording transcript picks up
// the new label without a manual refresh. Clears the fetch-once cache and, if the
// full-transcript panel is expanded, reloads it in place.
function reloadVideoTranscriptIfOpen(videoId) {
  _videoTranscriptLoadedFor = null;
  const card = document.getElementById('video-transcript-details');
  if (card && !card.classList.contains('collapsed')) loadVideoTranscript(videoId);
}

// ── per-line speaker control (rename + reassign) ───────────────────────────────
// A transcript line's speaker dot opens a menu to reattribute that one line to a
// different speaker (or detach it) and to name the line's current speaker without
// leaving the transcript. Speaker lists are cached per video and invalidated on any
// change so a fresh menu always reflects renames.
const _videoSpeakersCache = {};

async function _getVideoSpeakers(videoId) {
  if (_videoSpeakersCache[videoId]) return _videoSpeakersCache[videoId];
  const list = await fetch(`/api/videos/${videoId}/speakers`).then(r => r.json()).catch(() => []);
  _videoSpeakersCache[videoId] = Array.isArray(list) ? list : [];
  return _videoSpeakersCache[videoId];
}

let _openSpkMenu = null;

function _closeSpeakerMenu() {
  if (_openSpkMenu) { _openSpkMenu.remove(); _openSpkMenu = null; }
  document.removeEventListener('click', _onDocClickSpkMenu, true);
  document.removeEventListener('keydown', _onKeydownSpkMenu, true);
}

function _onDocClickSpkMenu(e) {
  if (_openSpkMenu && !_openSpkMenu.contains(e.target)) _closeSpeakerMenu();
}

function _onKeydownSpkMenu(e) {
  if (e.key === 'Escape') { e.preventDefault(); _closeSpeakerMenu(); }
}

async function _openSpeakerMenu(chip) {
  _closeSpeakerMenu();
  const segId = parseInt(chip.dataset.segId, 10);
  const curId = chip.dataset.speakerId ? parseInt(chip.dataset.speakerId, 10) : null;
  const videoId = parseInt(chip.dataset.videoId, 10);
  if (!videoId) return;
  const speakers = await _getVideoSpeakers(videoId);
  const cur = speakers.find(s => s.id === curId);

  const items = speakers.map(s =>
    `<button class="spk-menu-item${s.id === curId ? ' active' : ''}" data-reassign="${s.id}">
       <span class="spk-dot" style="background:${escHtml(s.color)}"></span>${escHtml(s.display_name)}</button>`
  ).join('');

  const menu = document.createElement('div');
  menu.className = 'spk-menu';
  menu.innerHTML = `
    <div class="spk-menu-head">Attribute this line to</div>
    ${items}
    <button class="spk-menu-item" data-reassign="">Unassigned</button>
    <button class="spk-menu-item spk-menu-new">+ New speaker</button>
    <div class="spk-menu-sep"></div>
    <div class="spk-menu-head">Name ${escHtml(cur ? cur.display_name : 'this speaker')}</div>
    <div class="spk-menu-rename">
      <input type="text" class="spk-menu-name" maxlength="60" placeholder="Add a name&hellip;"
             value="${escHtml(cur && cur.name ? cur.name : '')}">
      <button class="btn primary spk-menu-save">Save</button>
    </div>`;
  document.body.appendChild(menu);

  const rect = chip.getBoundingClientRect();
  const left = Math.max(8, Math.min(rect.left, window.innerWidth - menu.offsetWidth - 12));
  const top = Math.min(rect.bottom + 4, window.innerHeight - menu.offsetHeight - 8);
  menu.style.left = `${left}px`;
  menu.style.top = `${Math.max(8, top)}px`;
  _openSpkMenu = menu;

  menu.addEventListener('click', e => {
    if (e.target.closest('.spk-menu-new')) { _newSpeakerForLine(segId, videoId); return; }
    const reassign = e.target.closest('[data-reassign]');
    if (reassign) {
      const val = reassign.dataset.reassign;
      _reassignLine(segId, val === '' ? null : parseInt(val, 10), videoId);
      return;
    }
    if (e.target.closest('.spk-menu-save') && curId != null) {
      _renameSpeakerFromLine(curId, menu.querySelector('.spk-menu-name').value.trim(), videoId);
    }
  });
  menu.querySelector('.spk-menu-name')?.addEventListener('keydown', e => {
    if (e.key === 'Enter') { e.preventDefault(); menu.querySelector('.spk-menu-save').click(); }
  });

  // Defer wiring the dismiss handlers so the click that opened the menu doesn't close it.
  setTimeout(() => {
    document.addEventListener('click', _onDocClickSpkMenu, true);
    document.addEventListener('keydown', _onKeydownSpkMenu, true);
  }, 0);
}

// Create a fresh unnamed speaker (for a voice diarization missed or merged) and move
// this line onto it. The user can name it from its dot afterward. Reassignment reuses
// the same path as picking an existing speaker (rebuilds excerpts, refreshes the card).
async function _newSpeakerForLine(segId, videoId) {
  try {
    const res = await fetch(`/api/videos/${videoId}/speakers`, {
      method: 'POST', headers: {'Content-Type': 'application/json'}, body: '{}',
    });
    if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))));
    const speaker = await res.json();
    delete _videoSpeakersCache[videoId];
    await _reassignLine(segId, speaker.id, videoId);
    showToast(`Line moved to a new ${speaker.display_name}`);
  } catch (err) {
    showToast(`Could not add a speaker: ${err.message}`, 'error');
  }
}

async function _reassignLine(segId, speakerId, videoId) {
  try {
    const res = await fetch(`/api/transcript-segments/${segId}/speaker`, {
      method: 'PUT', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({speaker_id: speakerId}),
    });
    if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))));
    const data = await res.json();
    _closeSpeakerMenu();
    const n = (data.affected_clip_ids || []).length;
    showToast(n ? `Speaker reassigned - ${plural(n, 'clip')} affected; re-score to refresh` : 'Speaker reassigned');
    _refreshAfterSpeakerChange(videoId, data.affected_clip_ids);
  } catch (err) {
    showToast(`Could not reassign speaker: ${err.message}`, 'error');
  }
}

async function _renameSpeakerFromLine(speakerId, name, videoId) {
  try {
    const res = await fetch(`/api/speakers/${speakerId}`, {
      method: 'PUT', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({name}),
    });
    if (!res.ok) throw new Error('save failed');
    const updated = await res.json();
    _closeSpeakerMenu();
    showToast(updated.is_named ? `Speaker named ${updated.display_name}` : 'Name cleared');
    _refreshAfterSpeakerChange(videoId, null);
  } catch (_) {
    showToast('Could not save speaker name', 'error');
  }
}

function _refreshAfterSpeakerChange(videoId, affectedClipIds) {
  delete _videoSpeakersCache[videoId];
  if (window.loadSpeakers) loadSpeakers(videoId);
  reloadVideoTranscriptIfOpen(videoId);
  const openClip = AppState.activeClipId;
  if (openClip != null && (affectedClipIds == null || affectedClipIds.includes(openClip))
      && window.refreshClipDetail) {
    refreshClipDetail(openClip);
  }
}

// ── inline caption editing ────────────────────────────────────────────────────
function startEditCaption(span) {
  if (span.classList.contains('editing')) return;
  const segId = span.dataset.segId;
  const original = span.textContent;
  span.classList.add('editing');
  span.innerHTML = '';

  const input = document.createElement('textarea');
  input.className = 'tline-edit-input';
  input.value = original;
  input.rows = Math.min(4, Math.max(1, Math.ceil(original.length / 48)));

  const actions = document.createElement('div');
  actions.className = 'tline-edit-actions';
  const save = document.createElement('button');
  save.className = 'btn primary';
  save.textContent = 'Save';
  const cancel = document.createElement('button');
  cancel.className = 'btn ghost';
  cancel.textContent = 'Cancel';
  actions.append(save, cancel);
  span.append(input, actions);
  input.focus();
  input.setSelectionRange(original.length, original.length);

  const restore = (text) => { span.classList.remove('editing'); span.textContent = text; };

  cancel.onclick = () => restore(original);
  input.onkeydown = ev => {
    if (ev.key === 'Escape') { ev.preventDefault(); restore(original); }
    else if (ev.key === 'Enter' && !ev.shiftKey) { ev.preventDefault(); save.click(); }
  };
  save.onclick = async () => {
    const text = input.value.trim();
    if (!text) { showToast('Caption cannot be empty', 'warning'); return; }
    if (text === original) { restore(original); return; }
    save.disabled = cancel.disabled = true;
    try {
      const res = await fetch(`/api/caption-segments/${segId}`, {
        method: 'PUT',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({text}),
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(formatApiError(err));
      }
      const data = await res.json();
      restore(data.text);
      _onCaptionEdited(data);
    } catch (err) {
      save.disabled = cancel.disabled = false;
      showToast(`Could not save caption: ${err.message}`, 'error');
    }
  };
}

function _onCaptionEdited(data) {
  const affected = data.affected_clip_ids || [];
  showToast(affected.length
    ? `Caption updated - ${plural(affected.length, 'clip')} affected; re-score to refresh`
    : 'Caption updated');
  // Refresh the open clip's detail so its excerpt and the re-score notice update.
  const openId = AppState.activeClipId;
  if (openId && affected.includes(openId) && window.refreshClipDetail) refreshClipDetail(openId);
}

document.addEventListener('DOMContentLoaded', () => {
  const detail = document.getElementById('detail');
  if (!detail) return;
  detail.addEventListener('click', e => {
    if (e.target.closest('.tx-move-toggle')) { _enterLineSelect(); return; }
    if (e.target.closest('.tx-move-cancel')) { _exitLineSelect(); return; }
    const view = document.getElementById('video-transcript-view');
    if (view && view.classList.contains('select-mode') && view.contains(e.target)) {
      // In select mode a line click toggles selection; playback still works, but the
      // dot menu and caption editing yield to selection.
      const play = e.target.closest('.tline-play');
      if (play) { seekPlayerTo(parseFloat(play.dataset.seekS)); return; }
      const row = e.target.closest('.tline');
      if (row) { _toggleLineSelection(row); return; }
    }
    const spk = e.target.closest && e.target.closest('.tline-spk');
    if (spk) { e.stopPropagation(); _openSpeakerMenu(spk); return; }
    const text = e.target.closest && e.target.closest('.tline-text.editable');
    if (text) { startEditCaption(text); return; }
    const btn = e.target.closest && e.target.closest('.tline-play');
    if (btn) seekPlayerTo(parseFloat(btn.dataset.seekS));
  });
  detail.addEventListener('change', e => {
    const target = e.target.closest && e.target.closest('.tx-move-target');
    if (target && target.value) _moveSelectedLines(target.value);
  });
  detail.addEventListener('keydown', e => {
    if (e.key !== 'Enter' && e.key !== ' ') return;
    const text = e.target.closest && e.target.closest('.tline-text.editable');
    if (text && !text.classList.contains('editing')) { e.preventDefault(); startEditCaption(text); }
  });
  // Lazy-load the full-video transcript the first time its collapsible card is
  // expanded (cardtoggle bubbles up from the card - see utils.js).
  detail.addEventListener('cardtoggle', e => {
    if (e.detail.key === 'video-transcript' && !e.detail.collapsed) {
      const card = document.getElementById('video-transcript-details');
      if (card) loadVideoTranscript(parseInt(card.dataset.videoId, 10));
    }
  });
});

Object.assign(window, {
  loadClipTranscript, loadVideoTranscript, reloadVideoTranscriptIfOpen,
  renderTranscriptLines, seekPlayerTo, startEditCaption,
});
})();

//# sourceURL=namecorrections.js
(function () {
// Feature-map - Name corrections (code: name_corrections; UI "Fix names").
//   API: routes/name_corrections.py · Tests: tests/ui/test_ui_namecorrections.py
// ── transcript name correction (Plan 09) ──────────────────────────────────────
// A PanelNav takeover launched from the recording's transcript card. Scans the
// transcript for likely mis-transcriptions of known names ("You" → "Yuu"),
// groups them by pattern, and applies only the instances the user keeps checked.
// Nothing is auto-applied; applying routes through the same caption-edit path as
// a manual edit, so staleness badges and sidecars behave identically.

let _ncVideoId = null;
let _ncData = null;  // last scan result - the source for offsets/replacements at apply time

function isNameCorrectionsOpen() {
  return PanelNav.isOpen('name-corrections');
}

function openNameCorrections(videoId) {
  _ncVideoId = videoId;
  PanelNav.open({
    id: 'name-corrections',
    title: 'Fix names',
    render: container => _ncMount(container),
    isDirty: () => false,
    onClose: () => { _ncVideoId = null; },
  });
}

function _ncMount(container) {
  container.innerHTML = `
    <p class="nc-intro">Reviewing the transcript for mis-heard names. Nothing changes
      until you press Apply - uncheck anything that isn't really a name.</p>
    <div id="nc-results"><div class="transcript-empty">Scanning transcript&hellip;</div></div>
    <div id="nc-footer" class="nc-footer" hidden>
      <button class="btn primary" id="nc-apply">Apply</button>
    </div>`;
  container.querySelector('#nc-apply').onclick = () => _ncApply();
  container.addEventListener('change', _ncOnChange);
  _ncScan();
}

async function _ncScan() {
  const results = document.getElementById('nc-results');
  try {
    const resp = await fetch(`/api/videos/${_ncVideoId}/name-corrections/scan`, {method: 'POST'});
    if (!resp.ok) throw new Error(formatApiError(await resp.json().catch(() => ({}))));
    const data = await resp.json();
    _ncRender(data);
  } catch (err) {
    results.innerHTML = `<div class="transcript-empty">Could not scan: ${escHtml(err.message)}</div>`;
  }
}

function _ncRender(data) {
  _ncData = data;
  const results = document.getElementById('nc-results');
  const footer = document.getElementById('nc-footer');
  if (!data.groups.length) {
    const noNames = !data.lexicon.length;
    results.innerHTML = `<div class="transcript-empty">${noNames
      ? 'No known names yet - name your speakers or add characters to a world context, then scan again.'
      : 'No likely name corrections found. Your transcript looks clean.'}</div>`;
    footer.hidden = true;
    return;
  }
  results.innerHTML = data.groups.map(_ncGroupHtml).join('');
  footer.hidden = false;
  _ncUpdateApply();
}

function _ncGroupHtml(group, gi) {
  const instances = group.instances.map((inst, ii) => _ncInstanceHtml(inst, gi, ii)).join('');
  return `
    <details class="nc-group" open>
      <summary class="nc-group-head">
        <label class="nc-check" title="Select every instance in this group">
          <input type="checkbox" class="nc-group-all" data-group="${gi}" checked>
        </label>
        <span class="nc-pattern">
          <span class="nc-from">${escHtml(group.token)}</span>
          <span class="nc-arrow" aria-hidden="true">→</span>
          <span class="nc-to">${escHtml(group.suggested)}</span>
        </span>
        <span class="nc-count">${plural(group.count, 'instance')}</span>
      </summary>
      <div class="nc-instances">${instances}</div>
    </details>`;
}

function _ncInstanceHtml(inst, gi, ii) {
  const before = inst.before ? `<span class="nc-ctx">${escHtml(inst.before)}</span> ` : '';
  const after = inst.after ? ` <span class="nc-ctx">${escHtml(inst.after)}</span>` : '';
  const line = escHtml(inst.line.slice(0, inst.token_start))
    + `<mark class="nc-mark">${escHtml(inst.line.slice(inst.token_start, inst.token_end))}</mark>`
    + escHtml(inst.line.slice(inst.token_end));
  const chips = [];
  if (!inst.speaker_scoped) chips.push('<span class="nc-chip">speaker unknown</span>');
  else if (inst.speaker) chips.push(`<span class="nc-chip">${escHtml(inst.speaker)}</span>`);
  return `
    <label class="nc-instance">
      <input type="checkbox" class="nc-inst" data-group="${gi}" data-inst="${ii}" checked>
      <span class="nc-line">${before}${line}${after}</span>
      <span class="nc-chips">${chips.join('')}</span>
    </label>`;
}

function _ncOnChange(e) {
  const groupAll = e.target.closest('.nc-group-all');
  if (groupAll) {
    const details = groupAll.closest('.nc-group');
    details.querySelectorAll('.nc-inst').forEach(cb => { cb.checked = groupAll.checked; });
  }
  const inst = e.target.closest('.nc-inst');
  if (inst) _ncSyncGroupCheckbox(inst.closest('.nc-group'));
  _ncUpdateApply();
}

function _ncSyncGroupCheckbox(details) {
  const all = details.querySelector('.nc-group-all');
  const boxes = [...details.querySelectorAll('.nc-inst')];
  all.checked = boxes.every(cb => cb.checked);
  all.indeterminate = !all.checked && boxes.some(cb => cb.checked);
}

function _ncSelected() {
  return [...document.querySelectorAll('.nc-inst:checked')].map(cb => {
    const inst = _ncData.groups[+cb.dataset.group].instances[+cb.dataset.inst];
    return {
      segment_id: inst.segment_id,
      token_start: inst.token_start,
      token_end: inst.token_end,
      token: inst.token,
      replacement: _ncData.groups[+cb.dataset.group].suggested,
    };
  });
}

function _ncUpdateApply() {
  const btn = document.getElementById('nc-apply');
  if (!btn) return;
  const n = document.querySelectorAll('.nc-inst:checked').length;
  btn.disabled = n === 0;
  btn.textContent = n ? `Apply ${plural(n, 'correction')}` : 'Apply';
}

async function _ncApply() {
  const btn = document.getElementById('nc-apply');
  const corrections = _ncSelected();
  if (!corrections.length) return;
  btn.disabled = true;
  try {
    const resp = await fetch(`/api/videos/${_ncVideoId}/name-corrections/apply`, {
      method: 'POST', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({corrections}),
    });
    if (!resp.ok) throw new Error(formatApiError(await resp.json().catch(() => ({}))));
    const data = await resp.json();
    const skipped = data.results.length - data.applied;
    showToast(skipped
      ? `Applied ${plural(data.applied, 'correction')}; ${skipped} skipped (transcript changed)`
      : `Applied ${plural(data.applied, 'correction')}`, skipped ? 'warning' : 'success');
    if (window.reloadVideoTranscriptIfOpen) reloadVideoTranscriptIfOpen(_ncVideoId);
    const openClip = AppState.activeClipId;
    if (openClip != null && (data.affected_clip_ids || []).includes(openClip) && window.refreshClipDetail) {
      refreshClipDetail(openClip);
    }
    _ncScan();  // re-scan so applied patterns drop out and the count refreshes
  } catch (err) {
    btn.disabled = false;
    showToast(`Could not apply corrections: ${err.message}`, 'error');
  }
}

Object.assign(window, {openNameCorrections, isNameCorrectionsOpen});
})();

//# sourceURL=clipcreate.js
(function () {
// Feature-map - Manual clip (code: "manual" tag on ClipCandidate).
//   API: routes/clips/crud.py (create_manual_clip) · Tests: tests/ui/test_ui_clipcreate.py, tests/integration/test_clip_create.py
// ── manual clip creation picker ───────────────────────────────────────────────
// Lets the creator pick an arbitrary time window from a recording's transcript
// (or, with no transcript, from typed times) and create a clip from it. The
// clip then goes through the normal review pipeline: it's created "pending"
// and LLM-scored right away via the existing rescoreClip() SSE flow - there is
// no separate "manual, unscored" state.
//
// The picker gets its own inline preview video (like split.js's split-preview-video)
// rather than reusing #player-area - PanelNav's takeover panel visually covers
// #player-area while open, so seeking that hidden element would give no visible
// feedback for "Play selection".

let _ccVideoId    = null;
let _ccKind       = 'clip';
let _ccDurationMs = 0;
let _ccSeekOffsetS = 0;
let _ccStartMs    = null;
let _ccEndMs      = null;
let _ccPlaybackGuard = null;

function isClipCreateOpen() {
  return PanelNav.isOpen('clip-create');
}

// kind: 'clip' (default) or 'scene' - a scene reuses this exact picker, differing
// only in the created row's kind, the panel copy, and (Stage 0) skipping the
// auto-rescore chain (scene scoring lands in a later stage).
function openClipCreatePicker(videoId, kind = 'clip') {
  if (!videoId) { showToast('Select a recording first', 'warning'); return; }
  const video = AppState.videos.find(v => v.id === videoId);
  if (!video) return;

  _ccVideoId     = videoId;
  _ccKind        = kind === 'scene' ? 'scene' : 'clip';
  _ccDurationMs  = video.duration_ms || 0;
  _ccSeekOffsetS = 0;
  _ccStartMs     = null;
  _ccEndMs       = null;

  const noun = _ccKind === 'scene' ? 'scene' : 'clip';
  PanelNav.open({
    id: 'clip-create',
    title: `New ${noun}: ${video.title || video.filename}`,
    render: container => _mountClipCreatePanel(container, video),
    isDirty: () => _ccStartMs != null || _ccEndMs != null,
    onClose: _teardownClipCreatePanel,
  });
}

function _mountClipCreatePanel(container, video) {
  container.innerHTML = `
    <div style="position:relative">
      <video id="clipcreate-preview-video" controls preload="metadata" aria-label="Recording preview"
             style="display:block;width:100%;max-height:38vh;object-fit:contain;background:#000;border-radius:6px"></video>
      <span id="clipcreate-preview-badge" role="status"
            style="display:none;position:absolute;top:8px;left:8px;background:rgba(0,0,0,.7);color:#e6e6e6;font-size:11px;padding:3px 8px;border-radius:4px"></span>
    </div>
    <div style="font-size:12px;color:var(--muted)">
      Click a transcript line to set the start, then click a later line to set the end - or type exact times below.
    </div>
    <div style="display:flex;align-items:center;gap:14px;flex-wrap:wrap">
      <div id="clipcreate-range-header" style="font-size:14px;font-weight:600"></div>
      <label style="display:flex;align-items:center;gap:6px;font-size:12px;color:var(--muted)">Start
        <input type="text" id="clipcreate-start-input" placeholder="0:00" aria-label="Clip start time (h:mm:ss or m:ss)"
               style="width:70px;padding:4px 8px;background:var(--bg);border:1px solid var(--border);border-radius:4px;color:var(--text);font-size:13px">
      </label>
      <label style="display:flex;align-items:center;gap:6px;font-size:12px;color:var(--muted)">End
        <input type="text" id="clipcreate-end-input" placeholder="0:00" aria-label="Clip end time (h:mm:ss or m:ss)"
               style="width:70px;padding:4px 8px;background:var(--bg);border:1px solid var(--border);border-radius:4px;color:var(--text);font-size:13px">
      </label>
      <button class="btn ghost" id="clipcreate-play-btn" disabled>&#9654; Play selection</button>
    </div>
    <div id="clipcreate-transcript-view" class="transcript"><div class="transcript-empty">Loading…</div></div>
    <div style="display:flex;justify-content:flex-end">
      <button class="btn primary" id="clipcreate-confirm-btn" disabled>Create ${_ccKind === 'scene' ? 'scene' : 'clip'}</button>
    </div>
  `;

  document.getElementById('clipcreate-start-input').onchange = e => _ccApplyTimeInput('start', e.target.value);
  document.getElementById('clipcreate-end-input').onchange   = e => _ccApplyTimeInput('end', e.target.value);
  document.getElementById('clipcreate-play-btn').onclick      = _ccPlaySelection;
  document.getElementById('clipcreate-confirm-btn').onclick   = _ccConfirmCreate;
  document.getElementById('clipcreate-transcript-view').addEventListener('click', _ccOnTranscriptClick);

  setupRecordingPreview(
    document.getElementById('clipcreate-preview-video'),
    document.getElementById('clipcreate-preview-badge'),
    video.id,
    {
      autoBuild: false,
      isCurrent: () => _ccVideoId === video.id,
      startS: video.segment_start_s,
      endS: video.segment_end_s,
      sourcePath: video.source_path,
    },
  );

  _ccRenderHeader();
  _ccLoadTranscript(video.id);
}

async function _ccLoadTranscript(videoId) {
  const el = document.getElementById('clipcreate-transcript-view');
  try {
    const data = await fetch(`/api/videos/${videoId}/transcript`).then(r => r.json());
    if (_ccVideoId !== videoId || !el) return;
    _ccSeekOffsetS = data.seek_offset_s || 0;
    const lines = data.lines || [];
    if (!lines.length) {
      el.innerHTML = '<div class="transcript-empty">No transcript yet - the clip will have no excerpt ' +
        'until this recording is (re)transcribed. Use the time inputs above to pick a range.</div>';
      return;
    }
    el.innerHTML = renderTranscriptLines(lines, { seekOffsetS: _ccSeekOffsetS, readOnly: true });
    el.querySelectorAll('.tline').forEach(row => row.classList.add('cc-pickable'));
    _ccRenderSelectionHighlight();
  } catch (_) {
    if (el) el.innerHTML = '<div class="transcript-empty">Could not load transcript.</div>';
  }
}

function _ccOnTranscriptClick(e) {
  const playBtn = e.target.closest('.tline-play');
  if (playBtn) { _ccSeekTo(parseFloat(playBtn.dataset.seekS)); return; }
  const row = e.target.closest('.tline');
  if (!row) return;
  const startMs = parseInt(row.dataset.startMs, 10);
  const endMs   = parseInt(row.dataset.endMs, 10);
  if (isNaN(startMs) || isNaN(endMs)) return;
  _ccPickLine(startMs, endMs);
}

// First click (or a click before the current start) sets the start and clears
// any end; a click at or after the current start sets the end - clicking the
// same line twice yields a 1-line clip.
function _ccPickLine(lineStartMs, lineEndMs) {
  if (_ccStartMs == null || lineStartMs < _ccStartMs) {
    _ccStartMs = lineStartMs;
    _ccEndMs   = null;
  } else {
    _ccEndMs = lineEndMs;
  }
  _ccRenderHeader();
}

function _ccApplyTimeInput(which, raw) {
  const ms = _ccParseTimeToMs(raw);
  if (ms == null) {
    showToast(`Couldn't read "${raw}" - use h:mm:ss or m:ss`, 'error');
    _ccRenderHeader();
    return;
  }
  if (ms < 0 || (_ccDurationMs > 0 && ms > _ccDurationMs)) {
    showToast(`Time must be between 0:00 and ${_ccFmt(_ccDurationMs)}`, 'error');
    _ccRenderHeader();
    return;
  }
  if (which === 'start') _ccStartMs = ms; else _ccEndMs = ms;
  _ccRenderHeader();
}

function _ccParseTimeToMs(str) {
  const parts = (str || '').trim().split(':').map(Number);
  if (!parts.length || parts.some(isNaN)) return null;
  let sec;
  if (parts.length === 3)      sec = parts[0] * 3600 + parts[1] * 60 + parts[2];
  else if (parts.length === 2) sec = parts[0] * 60 + parts[1];
  else if (parts.length === 1) sec = parts[0];
  else return null;
  return Math.round(sec * 1000);
}

function _ccFmt(ms) {
  const s  = Math.round((ms || 0) / 1000);
  const h  = Math.floor(s / 3600);
  const m  = Math.floor((s % 3600) / 60);
  const ss = s % 60;
  return h ? `${h}:${String(m).padStart(2, '0')}:${String(ss).padStart(2, '0')}` : `${m}:${String(ss).padStart(2, '0')}`;
}

function _ccRenderHeader() {
  const header      = document.getElementById('clipcreate-range-header');
  const playBtn      = document.getElementById('clipcreate-play-btn');
  const confirmBtn   = document.getElementById('clipcreate-confirm-btn');
  const startInput   = document.getElementById('clipcreate-start-input');
  const endInput     = document.getElementById('clipcreate-end-input');
  if (startInput && document.activeElement !== startInput) startInput.value = _ccStartMs != null ? _ccFmt(_ccStartMs) : '';
  if (endInput && document.activeElement !== endInput)     endInput.value   = _ccEndMs   != null ? _ccFmt(_ccEndMs)   : '';

  if (header) {
    if (_ccStartMs == null) {
      header.textContent = 'No range picked yet';
      header.style.color = 'var(--muted)';
    } else if (_ccEndMs == null) {
      header.textContent = `Start ${_ccFmt(_ccStartMs)} - pick an end`;
      header.style.color = 'var(--muted)';
    } else {
      const durationS = Math.round((_ccEndMs - _ccStartMs) / 1000);
      header.textContent = `${_ccFmt(_ccStartMs)} – ${_ccFmt(_ccEndMs)} (${durationS}s)`;
      header.style.color = 'var(--text)';
    }
  }
  const hasRange = _ccStartMs != null && _ccEndMs != null && _ccEndMs > _ccStartMs;
  if (playBtn)    playBtn.disabled    = !hasRange;
  if (confirmBtn) confirmBtn.disabled = !hasRange;
  _ccRenderSelectionHighlight();
}

function _ccRenderSelectionHighlight() {
  const container = document.getElementById('clipcreate-transcript-view');
  if (!container) return;
  container.querySelectorAll('.tline').forEach(row => {
    const startMs = parseInt(row.dataset.startMs, 10);
    const inRange = _ccStartMs != null && (
      (_ccEndMs != null && startMs >= _ccStartMs && startMs < _ccEndMs) ||
      (_ccEndMs == null && startMs === _ccStartMs)
    );
    row.classList.toggle('cc-selected', inRange);
  });
}

function _ccSeekTo(seconds) {
  const video = document.getElementById('clipcreate-preview-video');
  if (!video) return;
  video.currentTime = Math.max(0, seconds || 0);
  const attempt = video.play();
  if (attempt && attempt.catch) attempt.catch(() => {});
}

function _ccPlaySelection() {
  if (_ccStartMs == null || _ccEndMs == null) return;
  const video = document.getElementById('clipcreate-preview-video');
  if (!video) return;
  if (_ccPlaybackGuard) video.removeEventListener('timeupdate', _ccPlaybackGuard);
  const endS = _ccEndMs / 1000 + _ccSeekOffsetS;
  _ccPlaybackGuard = () => {
    if (video.currentTime >= endS) {
      video.pause();
      video.removeEventListener('timeupdate', _ccPlaybackGuard);
      _ccPlaybackGuard = null;
    }
  };
  video.addEventListener('timeupdate', _ccPlaybackGuard);
  _ccSeekTo(_ccStartMs / 1000 + _ccSeekOffsetS);
}

async function _ccConfirmCreate() {
  const btn = document.getElementById('clipcreate-confirm-btn');
  if (!btn || btn.disabled) return;
  if (_ccStartMs == null || _ccEndMs == null || _ccEndMs <= _ccStartMs) return;
  const videoId = _ccVideoId;
  const kind = _ccKind;
  const noun = kind === 'scene' ? 'scene' : 'clip';
  btn.disabled = true;
  btn.textContent = 'Creating…';
  try {
    const res = await fetch(`/api/videos/${videoId}/clips`, {
      method: 'POST', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({start_ms: _ccStartMs, end_ms: _ccEndMs, kind}),
    });
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      throw new Error(formatApiError(err));
    }
    const clip = await res.json();
    _ccStartMs = _ccEndMs = null;  // clears isDirty() before PanelNav tears the panel down
    PanelNav.forceClose();
    await _reloadClipList(videoId);
    selectClip(clip.id);
    // Both kinds auto-score on creation - clips via the Funny/Dramatic/Action prompt,
    // scenes via the scene rubric (the rescore route picks the prompt by kind).
    showToast(`${noun === 'scene' ? 'Scene' : 'Clip'} created - scoring…`);
    rescoreClip(clip.id);
  } catch (err) {
    showToast(`Could not create ${noun}: ${err.message}`, 'error');
    btn.disabled = false;
    btn.textContent = `Create ${noun}`;
  }
}

function _teardownClipCreatePanel() {
  const video = document.getElementById('clipcreate-preview-video');
  if (video) {
    if (_ccPlaybackGuard) video.removeEventListener('timeupdate', _ccPlaybackGuard);
    try { video.pause(); } catch (_) { /* ignore */ }
    video.src = '';
  }
  _ccPlaybackGuard = null;
  _ccVideoId    = null;
  _ccKind       = 'clip';
  _ccStartMs    = null;
  _ccEndMs      = null;
}

Object.assign(window, {
  openClipCreatePicker, isClipCreateOpen,
});
})();

//# sourceURL=exporteditor.js
(function () {
// Feature-map - Clip export editor (Trim + Vertical framing + Caption Style over a live preview).
//   API: routes/clips/ (captions.py context-transcript, export.py) · Tests: tests/ui/test_ui_exporteditor.py
// ── clip export editor (Plan 07) ──────────────────────────────────────────────
// A PanelNav takeover launched before final export: transcript-driven trim with
// extendable ±30 s context, a drag-to-position 9:16 crop box, and a live caption
// preview. It edits the same start_offset/end_offset/crop_x the export dialog
// does (no new timing model, no new encode path) and, on Export, runs the exact
// single-clip export SSE the dialog uses.
//
// Own inline preview <video>: PanelNav's panel visually covers #player-area
// (known coverage bug), so the editor never relies on the main player - it
// embeds its own, proxy-preferred, exactly like the manual-clip picker.

let _edClipId       = null;
let _edClip         = null;   // saved baseline (start_offset/end_offset/crop_x)
let _edVideo        = null;   // parent recording (from AppState.videos)
let _edConfig       = {};     // caption-style defaults from /api/config
let _edLines        = [];     // context transcript (recording-relative ms)
let _edSeekOffsetS  = 0;      // segment_start_s - added to seek the parent player
let _edAspect       = 16 / 9; // source frame aspect (iw/ih), refined on metadata

let _edStartOffset  = 0;
let _edEndOffset    = 0;
let _edCropX        = 0.5;
let _edPreset       = '';
let _edCaptionMode  = 'burn'; // none | embed | burn
let _edTitleCard    = false;
let _edMetaSeeked   = false;

const _ED_MIN_DURATION_MS = 1_000;
const _ED_PAD_S = 30;

function isExportEditorOpen() {
  return PanelNav.isOpen('export-editor');
}

async function openExportEditor(clipId) {
  const clip = await fetch(`/api/clips/${clipId}`).then(r => r.ok ? r.json() : null).catch(() => null);
  if (!clip) { showToast('Could not load clip', 'error'); return; }
  const video = AppState.videos.find(v => v.id === clip.video_id);
  if (!video) { showToast('Open the recording first', 'warning'); return; }

  await ensureExportPresetsCache();
  _edConfig = await fetch('/api/config').then(r => r.ok ? r.json() : {}).catch(() => ({}));

  _edClipId      = clipId;
  _edClip        = clip;
  _edVideo       = video;
  _edLines       = [];
  _edSeekOffsetS = video.segment_start_s || 0;
  _edAspect      = 16 / 9;
  _edStartOffset = clip.start_offset || 0;
  _edEndOffset   = clip.end_offset || 0;
  _edCropX       = clip.crop_x == null ? 0.5 : clip.crop_x;
  _edPreset      = '';
  _edCaptionMode = 'burn';
  _edTitleCard   = false;
  _edMetaSeeked  = false;

  PanelNav.open({
    id: 'export-editor',
    title: `Edit & export: Clip #${clipId}`,
    render: container => _edMount(container),
    isDirty: _edIsDirty,
    onClose: _edTeardown,
  });
  _edLoadContextTranscript();
}

function _edIsDirty() {
  const savedCrop = _edClip.crop_x == null ? 0.5 : _edClip.crop_x;
  return _edStartOffset !== (_edClip.start_offset || 0)
      || _edEndOffset   !== (_edClip.end_offset || 0)
      || _edCropX       !== savedCrop;
}

// ── mount / teardown ──────────────────────────────────────────────────────────

function _edMount(container) {
  container.innerHTML = `
    <div style="font-size:12px;color:var(--muted)">
      Trim with the transcript, frame the vertical crop, preview captions, then export - in one place.
    </div>
    <div id="ed-preview-wrap" style="position:relative;height:42vh;aspect-ratio:16/9;max-width:100%;margin:0 auto;background:#000;border-radius:6px;overflow:hidden">
      <video id="ed-video" controls preload="metadata" aria-label="Clip preview"
             style="display:block;width:100%;height:100%;object-fit:contain;background:#000"></video>
      <div id="ed-crop-box" aria-hidden="true"
           style="display:none;position:absolute;top:0;bottom:0;border:2px solid var(--accent);box-sizing:border-box;box-shadow:0 0 0 9999px rgba(0,0,0,.5);cursor:ew-resize"></div>
      <div id="ed-caption-overlay" aria-hidden="true"
           style="display:none;position:absolute;left:6%;right:6%;bottom:6%;text-align:center;pointer-events:none;font-weight:600;line-height:1.3;text-shadow:0 1px 3px rgba(0,0,0,.9)"></div>
      <span id="ed-badge" role="status"
            style="display:none;position:absolute;top:8px;left:8px;background:rgba(0,0,0,.7);color:#e6e6e6;font-size:11px;padding:3px 8px;border-radius:4px"></span>
    </div>
    <div style="display:flex;flex-wrap:wrap;gap:14px;align-items:center">
      <button class="btn ghost" id="ed-play-btn" title="Play the trimmed clip on a loop">&#9654; Play selection</button>
      <div style="display:flex;align-items:center;gap:6px;font-size:12px;color:var(--muted)">Start
        <button class="btn ghost ed-nudge" data-edge="start" data-delta="-0.5" title="Start 0.5s earlier">&minus;0.5s</button>
        <strong id="ed-start-read" style="color:var(--text);font-family:monospace;min-width:70px;text-align:center"></strong>
        <button class="btn ghost ed-nudge" data-edge="start" data-delta="0.5" title="Start 0.5s later">+0.5s</button>
      </div>
      <div style="display:flex;align-items:center;gap:6px;font-size:12px;color:var(--muted)">End
        <button class="btn ghost ed-nudge" data-edge="end" data-delta="-0.5" title="End 0.5s earlier">&minus;0.5s</button>
        <strong id="ed-end-read" style="color:var(--text);font-family:monospace;min-width:70px;text-align:center"></strong>
        <button class="btn ghost ed-nudge" data-edge="end" data-delta="0.5" title="End 0.5s later">+0.5s</button>
      </div>
      <div style="font-size:13px;font-weight:600;color:var(--text)">Duration <span id="ed-duration" style="font-family:monospace"></span></div>
      <button class="btn ghost" id="ed-reset-trim" style="font-size:12px" title="Reset the trim to the original clip window">Reset trim</button>
    </div>
    <div style="font-size:11px;color:var(--muted)">Click a line's <strong>&#8676;</strong> to start the clip there or <strong>&#8677;</strong> to end it. Highlighted lines are inside the clip.</div>
    <div id="ed-transcript" class="transcript" style="max-height:24vh;overflow-y:auto"><div class="transcript-empty">Loading transcript…</div></div>
    <div style="display:flex;flex-wrap:wrap;gap:14px;align-items:center;border-top:1px solid var(--border);padding-top:12px">
      <label style="display:flex;align-items:center;gap:6px;font-size:13px;color:var(--muted)">Preset
        <select id="ed-preset" aria-label="Export preset" style="padding:5px 8px;background:var(--bg);border:1px solid var(--border);border-radius:4px;color:var(--text);font-size:13px">${_edPresetOptionsHtml('')}</select>
      </label>
      <label style="display:flex;align-items:center;gap:6px;font-size:13px;color:var(--muted)">Captions
        <select id="ed-captions" aria-label="Captions" style="padding:5px 8px;background:var(--bg);border:1px solid var(--border);border-radius:4px;color:var(--text);font-size:13px">
          <option value="none">None</option>
          <option value="embed">Embed track</option>
          <option value="burn" selected>Burn in</option>
        </select>
      </label>
      <span id="ed-caption-approx" style="font-size:11px;color:var(--muted)">Caption overlay is a preview approximation.</span>
      <label style="display:flex;align-items:center;gap:6px;font-size:13px;cursor:pointer">
        <input type="checkbox" id="ed-title-card"> Title card
      </label>
      <button class="btn-secondary" id="ed-autoframe-btn" style="display:none;font-size:12px;padding:4px 8px" title="Suggest a crop position from faces (MediaPipe)">Auto-frame on faces</button>
      <span id="ed-autoframe-note" style="font-size:11px;color:var(--muted)"></span>
      <div style="margin-left:auto;display:flex;gap:8px">
        <button class="btn ghost" id="ed-cancel-btn">Cancel</button>
        <button class="btn primary" id="ed-export-btn">Export</button>
      </div>
    </div>`;

  _edWire(container);
  _edSetupPreview();
  _edRenderReadouts();
  _edUpdateVerticalControls();
  _edApplyCaptionStyle();
}

function _edWire(container) {
  document.getElementById('ed-play-btn').onclick   = _edPlaySelection;
  document.getElementById('ed-reset-trim').onclick = _edResetTrim;
  document.getElementById('ed-cancel-btn').onclick = () => PanelNav.close();
  document.getElementById('ed-export-btn').onclick = _edExport;
  document.getElementById('ed-autoframe-btn').onclick = _edAutoFrame;
  document.getElementById('ed-crop-box').addEventListener('pointerdown', _edCropPointerDown);
  document.getElementById('ed-preset').onchange = e => { _edPreset = e.target.value; _edUpdateVerticalControls(); };
  document.getElementById('ed-captions').onchange = e => {
    _edCaptionMode = e.target.value;
    _edUpdateCaptionOverlay(_edCurrentRecordingMs());
    document.getElementById('ed-caption-approx').style.visibility = _edCaptionMode === 'burn' ? 'visible' : 'hidden';
  };
  document.getElementById('ed-title-card').onchange = e => { _edTitleCard = e.target.checked; };
  container.querySelectorAll('.ed-nudge').forEach(btn => {
    btn.onclick = () => _edNudge(btn.dataset.edge, parseFloat(btn.dataset.delta));
  });
  document.getElementById('ed-transcript').addEventListener('click', _edOnTranscriptClick);
}

function _edSetupPreview() {
  const videoEl = document.getElementById('ed-video');
  setupRecordingPreview(
    videoEl,
    document.getElementById('ed-badge'),
    _edVideo.id,
    { autoBuild: true, isCurrent: () => _edVideo && _edClipId != null, sourcePath: _edVideo.source_path },
  );
  videoEl.addEventListener('loadedmetadata', _edOnMetadata);
  videoEl.addEventListener('timeupdate', _edOnTimeUpdate);
}

function _edTeardown() {
  const videoEl = document.getElementById('ed-video');
  if (videoEl) {
    videoEl.removeEventListener('loadedmetadata', _edOnMetadata);
    videoEl.removeEventListener('timeupdate', _edOnTimeUpdate);
    try { videoEl.pause(); } catch (_) { /* ignore */ }
    videoEl.src = '';
  }
  _edClipId = null;
  _edClip   = null;
  _edVideo  = null;
  _edLines  = [];
}

// ── transcript context ────────────────────────────────────────────────────────

async function _edLoadContextTranscript() {
  const clipId = _edClipId;
  try {
    const data = await fetch(`/api/clips/${clipId}/context-transcript?pad_s=${_ED_PAD_S}`).then(r => r.json());
    if (_edClipId !== clipId) return;
    _edSeekOffsetS = data.seek_offset_s || 0;
    _edLines = data.lines || [];
    _edRenderTranscript();
  } catch (_) {
    const el = document.getElementById('ed-transcript');
    if (el && _edClipId === clipId) el.innerHTML = '<div class="transcript-empty">Could not load transcript.</div>';
  }
}

function _edRenderTranscript() {
  const el = document.getElementById('ed-transcript');
  if (!el) return;
  if (!_edLines.length) {
    el.innerHTML = '<div class="transcript-empty">No transcript for this recording - trim with the nudge buttons above.</div>';
    return;
  }
  const effStart = _edEffStartMs(), effEnd = _edEffEndMs();
  const rows = _edLines.map(line => {
    const inClip = line.start_ms < effEnd && line.end_ms > effStart;
    const clock  = _edClock(line.start_ms);
    const spk = line.speaker
      ? `<span class="tline-speaker" style="align-self:center;margin-top:0${line.color ? `;color:${escHtml(line.color)}` : ''}">${escHtml(line.speaker)}</span>`
      : '';
    return `<div class="tline${inClip ? ' cc-selected' : ''}" data-start-ms="${line.start_ms}" data-end-ms="${line.end_ms}"${inClip ? '' : ' style="opacity:.55"'}>
      <button class="tline-play" data-seek-ms="${line.start_ms}" title="Play from ${clock}" aria-label="Play from ${clock}">&#9654;</button>
      <span class="tline-time">${clock}</span>
      <button class="btn ghost ed-bound" data-edge="start" data-ms="${line.start_ms}" title="Start the clip at this line" aria-label="Start clip here" style="padding:0 6px;font-size:13px">&#8676;</button>
      ${spk}
      <span class="tline-text" style="flex:1">${escHtml(line.text)}</span>
      <button class="btn ghost ed-bound" data-edge="end" data-ms="${line.end_ms}" title="End the clip at this line" aria-label="End clip here" style="padding:0 6px;font-size:13px">&#8677;</button>
    </div>`;
  }).join('');
  el.innerHTML = `<div class="transcript-lines">${rows}</div>`;
}

function _edOnTranscriptClick(e) {
  const bound = e.target.closest('.ed-bound');
  if (bound) { _edSetBoundaryToLine(bound.dataset.edge, parseInt(bound.dataset.ms, 10)); return; }
  const play = e.target.closest('.tline-play');
  if (play) { _edSeekMs(parseInt(play.dataset.seekMs, 10), true); }
}

// ── trim boundaries ───────────────────────────────────────────────────────────

function _edEffStartMs() { return _edClip.start_ms + _edStartOffset * 1000; }
function _edEffEndMs()   { return _edClip.end_ms   + _edEndOffset   * 1000; }

function _edSetBoundaryToLine(edge, ms) {
  if (edge === 'start') _edApplyStartMs(ms);
  else                  _edApplyEndMs(ms);
}

function _edApplyStartMs(effStartMs) {
  effStartMs = Math.max(0, effStartMs);
  if (_edEffEndMs() - effStartMs < _ED_MIN_DURATION_MS) {
    showToast('Clip must stay at least 1 second long', 'warning');
    return;
  }
  _edStartOffset = +((effStartMs - _edClip.start_ms) / 1000).toFixed(3);
  _edAfterBoundaryChange();
}

function _edApplyEndMs(effEndMs) {
  if (effEndMs - _edEffStartMs() < _ED_MIN_DURATION_MS) {
    showToast('Clip must stay at least 1 second long', 'warning');
    return;
  }
  _edEndOffset = +((effEndMs - _edClip.end_ms) / 1000).toFixed(3);
  _edAfterBoundaryChange();
}

function _edNudge(edge, deltaS) {
  if (edge === 'start') _edApplyStartMs(_edEffStartMs() + deltaS * 1000);
  else                  _edApplyEndMs(_edEffEndMs() + deltaS * 1000);
}

function _edResetTrim() {
  _edStartOffset = 0;
  _edEndOffset   = 0;
  _edAfterBoundaryChange();
}

function _edAfterBoundaryChange() {
  _edRenderReadouts();
  _edRenderTranscript();
  _edSeekMs(_edEffStartMs(), false);
}

function _edRenderReadouts() {
  const startEl = document.getElementById('ed-start-read');
  const endEl   = document.getElementById('ed-end-read');
  const durEl   = document.getElementById('ed-duration');
  if (startEl) startEl.textContent = _edClock(_edEffStartMs());
  if (endEl)   endEl.textContent   = _edClock(_edEffEndMs());
  if (durEl)   durEl.textContent   = `${((_edEffEndMs() - _edEffStartMs()) / 1000).toFixed(1)}s`;
}

// ── preview playback ──────────────────────────────────────────────────────────

function _edOnMetadata() {
  const videoEl = document.getElementById('ed-video');
  if (!videoEl || !videoEl.videoWidth) return;
  _edAspect = videoEl.videoWidth / videoEl.videoHeight;
  const wrap = document.getElementById('ed-preview-wrap');
  if (wrap) wrap.style.aspectRatio = `${videoEl.videoWidth}/${videoEl.videoHeight}`;
  _edUpdateVerticalControls();
  _edApplyCaptionStyle();
  if (!_edMetaSeeked) {
    _edMetaSeeked = true;
    _edSeekMs(_edEffStartMs(), false);
  }
}

function _edOnTimeUpdate() {
  const videoEl = document.getElementById('ed-video');
  if (!videoEl) return;
  _edUpdateCaptionOverlay(_edCurrentRecordingMs());
  if (!videoEl.paused) {
    const endParent = _edSeekOffsetS + _edEffEndMs() / 1000;
    if (videoEl.currentTime >= endParent - 0.03) {
      videoEl.currentTime = _edSeekOffsetS + _edEffStartMs() / 1000;
    }
  }
}

function _edCurrentRecordingMs() {
  const videoEl = document.getElementById('ed-video');
  if (!videoEl) return 0;
  return (videoEl.currentTime - _edSeekOffsetS) * 1000;
}

// recordingMs is recording-relative; add the segment offset to seek the parent.
function _edSeekMs(recordingMs, play) {
  const videoEl = document.getElementById('ed-video');
  if (!videoEl) return;
  videoEl.currentTime = Math.max(0, _edSeekOffsetS + recordingMs / 1000);
  if (play) { const p = videoEl.play(); if (p && p.catch) p.catch(() => {}); }
}

function _edPlaySelection() {
  _edSeekMs(_edEffStartMs(), true);
}

// ── caption overlay (preview approximation) ───────────────────────────────────

function _edApplyCaptionStyle() {
  const overlay = document.getElementById('ed-caption-overlay');
  const wrap    = document.getElementById('ed-preview-wrap');
  const videoEl = document.getElementById('ed-video');
  if (!overlay || !wrap) return;
  const sourceH = (videoEl && videoEl.videoHeight) || 1080;
  const sizePt  = _edConfig.caption_font_size || 28;
  const px      = Math.max(11, sizePt * (wrap.clientHeight || 1) / sourceH);
  overlay.style.fontSize   = `${px.toFixed(1)}px`;
  overlay.style.fontFamily = _edConfig.caption_font_name ? `"${_edConfig.caption_font_name}", sans-serif` : '';
  const top = (_edConfig.caption_position === 'top');
  overlay.style.bottom = top ? '' : '6%';
  overlay.style.top    = top ? '6%' : '';
}

function _edUpdateCaptionOverlay(recordingMs) {
  const overlay = document.getElementById('ed-caption-overlay');
  if (!overlay) return;
  if (_edCaptionMode !== 'burn') { overlay.style.display = 'none'; return; }
  const active = _edLines.filter(l => l.in_clip && l.start_ms <= recordingMs && l.end_ms > recordingMs);
  if (!active.length) { overlay.style.display = 'none'; return; }
  overlay.style.display = 'block';
  overlay.innerHTML = active
    .map(l => `<span style="color:${escHtml(l.color || '#fff')}">${escHtml(l.text)}</span>`)
    .join('<br>');
}

// ── vertical crop box ─────────────────────────────────────────────────────────

// Fraction of frame width the 9:16 crop column occupies: min(1, (9/16)/aspect).
function _edCropWFrac() {
  return Math.min(1, (9 / 16) / _edAspect);
}

function _edUpdateVerticalControls() {
  const vertical = exportPresetIsVertical(_edPreset);
  const box = document.getElementById('ed-crop-box');
  const btn = document.getElementById('ed-autoframe-btn');
  if (btn) btn.style.display = vertical ? '' : 'none';
  if (!box) return;
  if (!vertical) { box.style.display = 'none'; return; }
  box.style.display = 'block';
  _edRenderCropBox();
}

function _edRenderCropBox() {
  const box = document.getElementById('ed-crop-box');
  if (!box) return;
  const wFrac = _edCropWFrac();
  box.style.width = `${(wFrac * 100).toFixed(2)}%`;
  box.style.left  = `${(_edCropX * (1 - wFrac) * 100).toFixed(2)}%`;
}

function _edSetCropX(fraction) {
  _edCropX = Math.max(0, Math.min(1, fraction));
  _edRenderCropBox();
}

function _edCropPointerDown(e) {
  e.preventDefault();
  const wrap  = document.getElementById('ed-preview-wrap');
  const wFrac = _edCropWFrac();
  if (wFrac >= 0.999 || !wrap) return;  // source already ≤9:16 - nothing to pan
  function onMove(ev) {
    const rect = wrap.getBoundingClientRect();
    const centerFrac = (ev.clientX - rect.left) / rect.width;
    _edSetCropX((centerFrac - wFrac / 2) / (1 - wFrac));
  }
  function onUp() {
    window.removeEventListener('pointermove', onMove);
    window.removeEventListener('pointerup', onUp);
  }
  window.addEventListener('pointermove', onMove);
  window.addEventListener('pointerup', onUp);
}

async function _edAutoFrame() {
  const btn  = document.getElementById('ed-autoframe-btn');
  const note = document.getElementById('ed-autoframe-note');
  btn.disabled = true;
  note.textContent = 'Finding faces…';
  try {
    const res = await fetch(`/api/clips/${_edClipId}/suggest-framing`, { method: 'POST' });
    if (res.status === 503) { note.textContent = 'Needs MediaPipe - install it in Settings → Export.'; return; }
    if (!res.ok) throw new Error(formatApiError(await res.json().catch(() => ({}))) || `HTTP ${res.status}`);
    const { crop_x } = await res.json();
    if (crop_x == null) { note.textContent = 'No face found - set the crop manually.'; return; }
    _edSetCropX(crop_x);
    note.textContent = 'Framed on faces.';
  } catch (err) {
    note.textContent = `Auto-frame failed: ${err.message}`;
  } finally {
    btn.disabled = false;
  }
}

// ── export ────────────────────────────────────────────────────────────────────

function _edPresetOptionsHtml(selected) {
  const presets = AppState.exportPresets || { builtins: [], custom: [] };
  const opt = (v, l) => `<option value="${escHtml(v)}"${selected === v ? ' selected' : ''}>${escHtml(l)}</option>`;
  return [
    opt('', 'Original quality'),
    ...(presets.builtins || []).map(p => opt(p.name, p.label)),
    ...(presets.custom || []).map(p => opt(p.name, p.label)),
  ].join('');
}

async function _edSaveEdits() {
  const timingRes = await fetch(`/api/clips/${_edClipId}/timing`, {
    method: 'PATCH', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ start_offset: _edStartOffset, end_offset: _edEndOffset }),
  }).catch(() => null);
  if (!timingRes || !timingRes.ok) { showToast('Failed to save trim', 'error'); return false; }

  if (exportPresetIsVertical(_edPreset)) {
    const framingRes = await fetch(`/api/clips/${_edClipId}/framing`, {
      method: 'PATCH', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ crop_x: _edCropX }),
    }).catch(() => null);
    if (!framingRes || !framingRes.ok) { showToast('Failed to save vertical framing', 'error'); return false; }
    _edClip.crop_x = _edCropX;
  }
  _edClip.start_offset = _edStartOffset;
  _edClip.end_offset   = _edEndOffset;
  return true;
}

function _edExportParams() {
  const params = new URLSearchParams();
  if (_edCaptionMode === 'burn')  params.set('burn_subs', 'true');
  if (_edCaptionMode === 'embed') params.set('embed_subs', 'true');
  if (_edPreset)   params.set('preset', _edPreset);
  if (_edTitleCard) params.set('title_card', 'true');
  if (_edCaptionMode === 'burn') {
    params.set('caption_font', _edConfig.caption_font_name || '');
    params.set('caption_size', String(_edConfig.caption_font_size || 0));
    params.set('caption_position', _edConfig.caption_position || 'bottom');
  }
  return params;
}

async function _edExport() {
  const id  = _edClipId;
  const btn = document.getElementById('ed-export-btn');
  btn.disabled = true;
  if (!await _edSaveEdits()) { btn.disabled = false; return; }

  const params = _edExportParams();
  const qs = params.toString() ? `?${params}` : '';
  openLog();
  streamSSE(
    `/api/clips/${id}/export${qs}`,
    async () => {
      const [clip, media] = await Promise.all([
        fetch(`/api/clips/${id}`).then(r => r.json()),
        fetch(`/api/clips/${id}/media_url`).then(r => r.json()),
      ]);
      AppState.activeClipData = clip;
      AppState.activeMediaFilename = media.filename;
      PanelNav.forceClose();
      const captionsUrl = media.has_captions ? `/api/clips/${id}/captions.vtt` : null;
      renderPlayer(media.url, captionsUrl, id);
      renderDetail(clip);
      await _reloadClipList(AppState.activeVideoId);
      loadVideos();
      showToast('Clip exported successfully');
      SoundFx.play('export');
    },
    [{ label: 'Export', patterns: ['Exporting', 'OK Saved'] }],
    'Exporting',
  );
}

// ── helpers ───────────────────────────────────────────────────────────────────

function _edClock(ms) {
  const total = Math.max(0, Math.round((ms || 0) / 1000));
  const s = total % 60, m = Math.floor(total / 60) % 60, h = Math.floor(total / 3600);
  const mm = String(m).padStart(2, '0'), ss = String(s).padStart(2, '0');
  return h ? `${h}:${mm}:${ss}` : `${m}:${ss}`;
}

Object.assign(window, {
  openExportEditor, isExportEditorOpen,
});
})();

//# sourceURL=modeldownload.js
// Feature-map - Background model-download handoffs + in-app progress banners
//   (first-run-friction Stages 4 + 6). On boot two independent background
//   downloads can start: the local LLM the wizard queued (config.pending_local_model)
//   and the analysis-model prefetch - speech + speaker (unless model_prefetch_disabled). Each
//   renders its own dismissible row inside #model-download-banner, so when both run
//   the banners STACK rather than fight for one slot. Non-blocking chrome: it uses
//   the low-level _openSSE transport with its own per-kind stream handle (NOT
//   _activeES, which the single job header owns).
//   API: routes/llm.py (/api/llm/download-status[/clear], /api/llm/gguf/download,
//        /api/whisper/prefetch), /api/config
//   Tests: tests/ui/test_ui_modeldownload.py, tests/ui/test_ui_whisper_prefetch.py
(function () {
// A connection/offline failure reads differently to the user than a mid-download
// error, so the banner shows a "will retry when back online" state for the former.
const _CONNECTION_ERROR_RE = /could not connect|connection lost|server disconnected|failed to fetch/i;
// The download subprocess prints these before __DONE__ on failure; __DONE__ only
// means "the subprocess exited", never "succeeded" (see routes/llm.py + sse.py).
const _DOWNLOAD_ERROR_RE = /download failed|\[error:/i;

// Per-kind copy + endpoints + completion hooks. Keeps the transport generic so
// the LLM handoff and the whisper prefetch share one stacking-banner implementation.
const _KINDS = {
  llm: {
    downloadUrl: id => `/api/llm/gguf/download?model_id=${encodeURIComponent(id)}`,
    progressText: 'Downloading the AI model so scoring gets smarter - you can keep working.',
    failureText: 'Model download failed - check your connection; you can retry in Settings.',
    offlineText: 'No internet - the AI model will download when you are back online, or set it up in Settings.',
    successToast: 'Local model ready - LLM scoring is now available.',
    cancelToast: 'Local model setup skipped - you can set it up anytime in Settings.',
    onSuccess: async () => { await _clearPending(); _refreshCapabilities(); },
    onCancel: async () => { await _clearPending(); },
  },
  whisper: {
    downloadUrl: () => `/api/whisper/prefetch`,
    progressText: 'Downloading the speech model so your first analysis is instant - you can keep working.',
    failureText: 'Speech model download failed - it will download automatically on your first analysis.',
    offlineText: 'No internet - the speech model will download on your first analysis when you are back online.',
    successToast: 'Speech model ready - your first analysis will be instant.',
    cancelToast: 'Speech model download stopped - it will download on your first analysis.',
    onSuccess: async () => {},
    onCancel: async () => {},
  },
  speaker: {
    downloadUrl: () => `/api/models/prefetch?slug=speaker`,
    progressText: 'Downloading the speaker-labeling model in the background - you can keep working.',
    failureText: 'Speaker model download failed - it will download the first time you detect speakers.',
    offlineText: 'No internet - the speaker model will download the first time you detect speakers.',
    successToast: 'Speaker-labeling model ready.',
    cancelToast: 'Speaker model download stopped - it will download the first time you detect speakers.',
    onSuccess: async () => {},
    onCancel: async () => {},
  },
};

// kind -> {es, sawError, lastPct}. lastPct feeds the analyze-start heads-up.
const _streams = {};

function _container() { return document.getElementById('model-download-banner'); }

// ── boot triggers ─────────────────────────────────────────────────────────────
async function initModelDownload() {
  let status;
  try {
    status = await fetch('/api/llm/download-status').then(r => r.json());
  } catch { return; }
  if (!status || !status.pending_model_id) return;
  // Another tab/stream already owns the download - do not start a second one.
  if (status.downloading) return;
  let cap;
  try {
    cap = await fetch('/api/llm/capabilities').then(r => r.json());
  } catch { cap = {text: false}; }
  if (cap && cap.text) {
    // A working model already exists (e.g. the wizard downloaded it, or a manual
    // path was set) - the pending flag is stale, so clear it and show nothing.
    await _clearPending();
    return;
  }
  _startDownload('llm', _KINDS.llm.downloadUrl(status.pending_model_id));
}

// Default-ON background prefetch of the always-needed analysis models (the speech
// model and the speaker-labeling model), unless the wizard opted out. Each starts
// only when it is missing and not already downloading; banners stack.
async function initModelPrefetch() {
  let cfg;
  try {
    cfg = await fetch('/api/config').then(r => r.json());
  } catch { return; }
  if (!cfg || cfg.model_prefetch_disabled) return;
  let status;
  try {
    status = await fetch('/api/llm/download-status').then(r => r.json());
  } catch { return; }
  if (!status) return;
  if (!status.whisper_cached && !status.whisper_downloading) {
    _startDownload('whisper', _KINDS.whisper.downloadUrl());
  }
  // speaker_available guards against prefetching a model whose backend can't run
  // (package not installed, or speaker labels turned off).
  if (status.speaker_available && !status.speaker_cached && !status.speaker_downloading) {
    _startDownload('speaker', _KINDS.speaker.downloadUrl());
  }
}

// ── stream lifecycle ──────────────────────────────────────────────────────────
function _startDownload(kind, url) {
  if (_streams[kind]) return;
  const state = {es: null, sawError: false, lastPct: null};
  _streams[kind] = state;
  _renderProgressRow(kind, null);
  // The model-download endpoints are POST-only (a GET 405s), so the transport
  // must POST rather than the default GET the analyze/score SSE streams use.
  state.es = _openSSE(
    url,
    line => _onDownloadLine(kind, line),
    () => _onDownloadDone(kind),
    message => _onDownloadError(kind, message),
    {method: 'POST'},
  );
}

function _onDownloadLine(kind, line) {
  const state = _streams[kind];
  if (!state) return;
  if (_DOWNLOAD_ERROR_RE.test(line)) state.sawError = true;
  const match = line.match(/(\d+)\s*%/);
  if (match) {
    state.lastPct = parseInt(match[1], 10);
    _renderProgressRow(kind, state.lastPct);
  }
}

async function _onDownloadDone(kind) {
  const state = _streams[kind];
  _streams[kind] = undefined;
  if (state && state.sawError) {
    _renderFailureRow(kind, _KINDS[kind].failureText);
    return;
  }
  await _KINDS[kind].onSuccess();
  // Any completed download can change prerequisites/config (e.g. a local model now
  // exists), so re-sync the boot-cached state and its dependent surfaces - the
  // analyze prereq banner and per-clip description chips - without a restart.
  if (window.refreshServerState) refreshServerState();
  _removeRow(kind);
  showToast(_KINDS[kind].successToast, 'success');
}

function _onDownloadError(kind, message) {
  _streams[kind] = undefined;
  const copy = _CONNECTION_ERROR_RE.test(message || '')
    ? _KINDS[kind].offlineText
    : _KINDS[kind].failureText;
  _renderFailureRow(kind, copy);
}

async function _cancelDownload(kind) {
  const state = _streams[kind];
  if (state && state.es) state.es.close();
  _streams[kind] = undefined;
  await _KINDS[kind].onCancel();
  _removeRow(kind);
  showToast(_KINDS[kind].cancelToast, 'info');
}

function _clearPending() {
  return fetch('/api/llm/download-status/clear', {method: 'POST'}).catch(() => {});
}

function _refreshCapabilities() {
  if (window._updateLlmCapabilities) _updateLlmCapabilities();
  if (window._renderCapabilityTiers) _renderCapabilityTiers();
}

// ── row rendering (each kind owns one [data-mdl-kind] row) ──────────────────────
function _row(kind) {
  const container = _container();
  if (!container) return null;
  let row = container.querySelector(`.mdl-row[data-mdl-kind="${kind}"]`);
  if (!row) {
    row = document.createElement('div');
    row.className = 'mdl-row';
    row.setAttribute('data-mdl-kind', kind);
    container.appendChild(row);
  }
  container.style.display = '';
  return row;
}

// pct null => indeterminate (no percentage parsed yet). Only static per-kind copy
// is interpolated, so nothing user-supplied needs escaping here.
function _renderProgressRow(kind, pct) {
  const row = _row(kind);
  if (!row) return;
  const known = typeof pct === 'number' && pct >= 0;
  const fillClass = known ? 'mdl-bar-fill' : 'mdl-bar-fill indeterminate';
  const fillStyle = known ? ` style="width:${pct}%"` : '';
  row.innerHTML =
    `<div class="mdl-body">` +
      `<span class="mdl-text">${_KINDS[kind].progressText}</span>` +
      `<div class="mdl-bar" role="progressbar"${known ? ` aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"` : ''}>` +
        `<div class="${fillClass}"${fillStyle}></div>` +
      `</div>` +
      (known ? `<span class="mdl-pct">${pct}%</span>` : '') +
    `</div>` +
    `<button type="button" class="btn ghost mdl-cancel" data-mdl-action="cancel">Cancel</button>`;
  _wireRowActions(row, kind);
}

function _renderFailureRow(kind, message) {
  const row = _row(kind);
  if (!row) return;
  row.innerHTML =
    `<div class="mdl-body"><span class="mdl-text mdl-text-warn">${escHtml(message)}</span></div>` +
    `<button type="button" class="btn ghost mdl-cancel" data-mdl-action="dismiss">Dismiss</button>`;
  _wireRowActions(row, kind);
}

function _wireRowActions(row, kind) {
  row.querySelectorAll('[data-mdl-action]').forEach(btn => {
    const action = btn.getAttribute('data-mdl-action');
    btn.onclick = () => { if (action === 'cancel') _cancelDownload(kind); else _removeRow(kind); };
  });
}

function _removeRow(kind) {
  const container = _container();
  if (!container) return;
  const row = container.querySelector(`.mdl-row[data-mdl-kind="${kind}"]`);
  if (row) row.remove();
  if (!container.querySelector('.mdl-row')) {
    container.style.display = 'none';
    container.innerHTML = '';
  }
}

// Read by analyze.js so the pre-analysis heads-up can show the current percentage.
function getWhisperDownloadPct() {
  const state = _streams.whisper;
  return state && typeof state.lastPct === 'number' ? state.lastPct : null;
}

// Test support: close any in-flight streams and clear the banner so a test can
// drive the boot flow deterministically against stubbed routes, independent of
// what the real boot (against the live dev server) already started.
function _resetModelDownloads() {
  for (const kind of Object.keys(_streams)) {
    const state = _streams[kind];
    if (state && state.es) state.es.close();
    _streams[kind] = undefined;
  }
  const container = _container();
  if (container) { container.innerHTML = ''; container.style.display = 'none'; }
}

Object.assign(window, {
  initModelDownload, initModelPrefetch, getWhisperDownloadPct, _cancelDownload,
  _resetModelDownloads,
});
})();

//# sourceURL=boot.js
// Infrastructure - first-paint boot wiring (a11y init, event hookup, initial load).
//   Not a feature module; loaded last in index.html. Entry point: exports nothing,
//   so it is a bare IIFE with no Object.assign(window, ...) list.
// ── accessibility init ────────────────────────────────────────────────────────
(function () {
document.querySelectorAll('.modal-bg').forEach((bg, i) => {
  const inner = bg.querySelector('.modal, [class*="modal"]');
  if (!inner) return;
  inner.setAttribute('role', 'dialog');
  inner.setAttribute('aria-modal', 'true');
  const heading = inner.querySelector('h3');
  if (heading) {
    const labelId = `modal-title-${i}`;
    heading.id = heading.id || labelId;
    inner.setAttribute('aria-labelledby', heading.id || labelId);
  }
});

// ── boot ──────────────────────────────────────────────────────────────────────
initResize();
initPlaybackRate();
initProjectSwitcher();
_loadContexts();
loadVideos();
ensureHotwordsCache();
ensureExportPresetsCache();
fetch('/api/status').then(r => r.json()).then(d => {
  if (d.version) {
    const versionLabel = (/^\d/.test(d.version) ? 'v' : '') + d.version;
    document.getElementById('version-tag').textContent = versionLabel;
    document.getElementById('about-version').textContent = `Version ${versionLabel}`;
  }
  AppState.exportDir = d.export_dir || null;
  AppState.reelsDir = d.reels_dir || null;
  AppState.canReveal = !!d.can_reveal;
  // Reconnect to an analysis that was already running when this page loaded
  // (e.g. after a refresh) - the subprocess survives independently of the stream.
  if (d.analyze_filename) reattachAnalysis(d.analyze_filename, d.analyze_paused);
}).catch(() => {});

if (window.electronAPI) {
  document.getElementById('btn-setup-wizard').style.display = '';
  document.getElementById('btn-refresh').style.display = '';
}

// Single place that (re)loads the boot-cached server state and re-renders every
// surface that reads it, so a server-side change (model download, settings save)
// shows up WITHOUT an app restart. Cached globals and their readers:
//   window._prereqs      -> analyze prereq banner (ui.js), "Basic description"
//                           chip (clips.js), ffmpeg gate (videos.js)
//   window._aiPrivacyMode -> "Basic description" chip (clips.js)
//   window._visionEnabled -> vision frames (clips.js, contexts.js)
// Call refreshServerState() from any action that mutates these on the server.
window._prereqs = {ffmpeg_ok: true, llm_ok: true, llm_reason: ''};
async function refreshServerState() {
  try {
    const cfg = await fetch('/api/config').then(r => r.json());
    window._aiPrivacyMode = cfg.ai_privacy_mode || 'local_only';
    window._visionEnabled = cfg.vision_enabled === true;
  } catch { /* keep the last known config on a transient fetch failure */ }
  try {
    const prereqs = await fetch('/api/prereqs').then(r => r.json());
    window._prereqs = prereqs;
    if (window._applyPrereqWarnings) _applyPrereqWarnings(prereqs);
  } catch { /* keep the last known prereqs */ }
  if (window._renderClips) _renderClips();  // basic-description chip + vision frames
}
window.refreshServerState = refreshServerState;
refreshServerState();
const _savedSort = localStorage.getItem('clips-sort');
if (_savedSort) document.getElementById('clips-sort').value = _savedSort;
const _savedVideoSort = localStorage.getItem('videos-sort');
if (_savedVideoSort) {
  AppState.videoSort = _savedVideoSort;
  document.getElementById('videos-sort').value = _savedVideoSort;
}
AppState.clipSortDir = localStorage.getItem('clips-sort-dir') || 'desc';
AppState.videoSortDir = localStorage.getItem('videos-sort-dir') || 'desc';
_syncSortDirBtn('clips-sort-dir', AppState.clipSortDir);
_syncSortDirBtn('videos-sort-dir', AppState.videoSortDir);
document.getElementById('log-panel').classList.add('visible', 'minimized');
document.getElementById('log-toggle').textContent = '▼';

if (!localStorage.getItem('yuu-getting-started-seen')) openGettingStartedModal();

// Background model-download handoffs (first-run-friction Stages 4 + 6): if the
// wizard queued a local model and none is ready yet, and/or the always-needed
// analysis models (speech + speaker) are not cached and prefetch is enabled, fetch
// them in the background with in-app progress banners that stack. Non-blocking -
// the app stays fully usable.
initModelDownload();
initModelPrefetch();
})();
